-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
-- 本文件为 bible_jpn_data_03.sql 的第 b 半（原文件超过 SQL Editor 体积上限，故拆分）。
-- 运行顺序：01a → 01b → 02a → 02b → … → 06b。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '约伯记', 18, 31, 13, 'もし、しもべや召使いの女が私と争ったとき、私が彼らの訴えを拒んだことがあるなら、'),
('JPN', '约伯记', 18, 31, 14, '神が立たれるとき、私はどうすればよいか。また、神がお調べになるとき、何と答えたらよいか。'),
('JPN', '约伯记', 18, 31, 15, '私を胎内で造られた方は、彼らをも造られたのではないか。同じ方が、私たちを母の胎内に形造られたのではないか。'),
('JPN', '约伯记', 18, 31, 16, 'もし、私が弱い者たちの望みを退け、やもめの目を衰え果てさせ、'),
('JPN', '约伯记', 18, 31, 17, '私一人だけでパンを食べ、みなしごにそれを食べさせなかったのなら、'),
('JPN', '约伯记', 18, 31, 18, '──実は私の幼いときから、弱い者は私を父のようにして育ち、私は生まれたときから、やもめを導いた──'),
('JPN', '约伯记', 18, 31, 19, 'あるいは、もし私が、着る物がなくて死にかかっている人や、身をおおう物を持たない貧しい人を見たとき、'),
('JPN', '约伯记', 18, 31, 20, 'その人の腰が私にあいさつをすることも、私の子羊の毛で彼が暖められることもなかったなら、'),
('JPN', '约伯记', 18, 31, 21, 'あるいは、私が門のところに助け手を見て、みなしごに向かって手を振り上げたことがあったなら、'),
('JPN', '约伯记', 18, 31, 22, '私の肩の骨が肩から落ち、私の腕がつけ根から折れてもよい。'),
('JPN', '约伯记', 18, 31, 23, '神からのわざわいが私をおののかせ、その威力のゆえに、私は何もできないだろう。'),
('JPN', '约伯记', 18, 31, 24, 'もし、私が金を自分の頼みとし、黄金に向かって「私の拠り頼むもの」と言ったことがあるなら、'),
('JPN', '约伯记', 18, 31, 25, 'あるいは、私の富が多いことや、私の手が多くを得たことを喜んだことがあるなら、'),
('JPN', '约伯记', 18, 31, 26, 'あるいは、日の光が輝くのを、月が照りながら動くのを見て、'),
('JPN', '约伯记', 18, 31, 27, 'ひそかに心を惑わされ、手で口づけを投げかけたことがあるなら、'),
('JPN', '约伯记', 18, 31, 28, 'これもまた、裁判で罰せられるべき不義だ。私が、上なる神を否んだのだから。'),
('JPN', '约伯记', 18, 31, 29, 'あるいは、私を憎む者が衰えたのを喜び、彼にわざわいが下ったことに心躍らせたことがあるだろうか。'),
('JPN', '约伯记', 18, 31, 30, '私は自分の口を罪に任せなかった。のろいの誓いで彼のいのちを求めたりして。'),
('JPN', '约伯记', 18, 31, 31, '私の天幕の者たちはみな、こう言っているではないか。「あの方のパンに満腹しなかった者がいったいいるだろうか。」'),
('JPN', '约伯记', 18, 31, 32, '寄留者は外で夜を過ごさず、私は戸口を通りに向けて開けている。'),
('JPN', '约伯记', 18, 31, 33, 'あるいは私がアダムのように、自分の背きをおおい隠し、自分の咎を胸の中に秘めたことがあるだろうか。'),
('JPN', '约伯记', 18, 31, 34, '私が群衆の騒ぎにおびえ、一族の蔑みにひるみ、黙っていて、門を出なかったことがあるだろうか。'),
('JPN', '约伯记', 18, 31, 35, 'だれか、私の言うことを聞いてくれる者はいないものか。──ここに私の署名がある。全能者が私に答えてくださるように──私を訴える者が書いた告訴状があれば、'),
('JPN', '约伯记', 18, 31, 36, '私はそれを肩に担ぎ、冠のように、それをこの身に結び付け、'),
('JPN', '约伯记', 18, 31, 37, '私の歩みの数をこの方に告げ、君主のようにしてこの方に近づきたい。'),
('JPN', '约伯记', 18, 31, 38, 'もし、私の土地が私に向かって叫び、その畝がともに泣くことがあるなら、'),
('JPN', '约伯记', 18, 31, 39, 'あるいは私が金を払わずにその産物を食べ、その持ち主のいのちを失わせたことがあるなら、'),
('JPN', '约伯记', 18, 31, 40, '小麦の代わりに茨が、大麦の代わりに雑草が生えるように。ヨブのことばは終わった。'),
('JPN', '约伯记', 18, 32, 1, 'この三人はヨブに答えるのをやめた。ヨブが自分を正しいと思っていたからである。'),
('JPN', '约伯记', 18, 32, 2, 'すると、ラム族のブズ人、バラクエルの子エリフが怒りを燃やした。彼は、ヨブが神よりも自分自身のほうを義としたので、ヨブに向かって怒りを燃やしたのである。'),
('JPN', '约伯记', 18, 32, 3, '彼はまた、その三人の友に向かっても怒りを燃やした。彼らがヨブを不義に定めながら、言い返せなかったからである。'),
('JPN', '约伯记', 18, 32, 4, 'エリフは、彼らが自分よりも年長だったので、ヨブに語りかける時を待っていた。'),
('JPN', '约伯记', 18, 32, 5, 'エリフは三人の者の口に答えがないのを見て、怒りを燃やした。'),
('JPN', '约伯记', 18, 32, 6, 'ブズ人、バラクエルの子エリフは答えて言った。私は年が若く、あなたがたは年をとっている。だから私はわきに控え、遠慮してあなたがたに私の意見を述べなかった。'),
('JPN', '约伯记', 18, 32, 7, '私は思った。「日を重ねた者が語り、年の多い者が知恵を教えるのだ」と。'),
('JPN', '约伯记', 18, 32, 8, '確かに、人の中には霊があり、全能者の息が人に悟りを与える。'),
('JPN', '约伯记', 18, 32, 9, 'だが、年長者が知恵深いわけではない。老人が道理をわきまえているわけでもない。'),
('JPN', '约伯记', 18, 32, 10, 'だから私は言う。「私の言うことを聞いてくれ。私も自分の意見を述べよう。」'),
('JPN', '约伯记', 18, 32, 11, '今まで私はあなたがたの言うことに期待し、あなたがたの意見に耳を傾けていた。あなたがたがことばを探している間、'),
('JPN', '约伯记', 18, 32, 12, '私はあなたがたに細心の注意を払っていた。しかし、あなたがたのうちには、ヨブを叱責する者も、彼のことばに答える者もいなかった。'),
('JPN', '约伯记', 18, 32, 13, 'だが、おそらくあなたがたは言うだろう。「私たちは知恵を見出した。人ではなく、神が彼を吹き払ったのだ」と。'),
('JPN', '约伯记', 18, 32, 14, '彼はまだ私に向かって、ことばを並べ立ててはいない。私はあなたがたのような言い方では彼に答えることはしない。'),
('JPN', '约伯记', 18, 32, 15, '彼らは意気をそがれて、もう答えない。彼らの言うことばもなくなった。'),
('JPN', '约伯记', 18, 32, 16, '彼らが話さず、じっと立って答えないからといって、私は待っていなければならないのか。'),
('JPN', '约伯记', 18, 32, 17, '私は私で自分の言い分を返し、私も自分の意見を述べよう。'),
('JPN', '约伯记', 18, 32, 18, '私にはことばがあふれていて、内なる霊が私を圧迫しているからだ。'),
('JPN', '约伯记', 18, 32, 19, '今、私の腹は抜け口のないぶどう酒のよう。新しい皮袋のように、張り裂けようとしている。'),
('JPN', '约伯记', 18, 32, 20, '私は話して、気分を晴らしたい。唇を開いて答えたい。'),
('JPN', '约伯记', 18, 32, 21, '私はだれも、えこひいきしない。どんな人にも、へつらったりしない。'),
('JPN', '约伯记', 18, 32, 22, '私はへつらうことを知らないし、そんなことをすれば、私を造った方は、すぐにでも私を取り去ってしまわれるだろう。'),
('JPN', '约伯记', 18, 33, 1, 'そこでヨブよ、どうか私の言い分を聞いてほしい。私のすべてのことばに耳を傾けてほしい。'),
('JPN', '约伯记', 18, 33, 2, 'さあ、私は口を開き、私の口の中の舌が語る。'),
('JPN', '约伯记', 18, 33, 3, '私の言うことは、直ぐな心から出る。私の唇は、率直に知識を語る。'),
('JPN', '约伯记', 18, 33, 4, '神の霊が私を造り、全能者の息が私にいのちを下さる。'),
('JPN', '约伯记', 18, 33, 5, 'あなたにできるのであれば、私に返事をし、ことばを並べ立てて、私の前に立ってみよ。'),
('JPN', '约伯记', 18, 33, 6, '実に、神にとって、私はあなたと同様だ。私もまた粘土で形造られた。'),
('JPN', '约伯记', 18, 33, 7, '見よ、私の脅しも、あなたをおびえさせない。あなたに私の力がのしかかっても、重くはない。'),
('JPN', '约伯记', 18, 33, 8, '確かにあなたは、この耳に言った。私はあなたの話す声を聞いた。'),
('JPN', '约伯记', 18, 33, 9, '「私はきよく、背きがない。私は純潔であり、咎もない。'),
('JPN', '约伯记', 18, 33, 10, 'それなのに、神は私を攻める口実を見つけ、私を神の敵のように見なされる。'),
('JPN', '约伯记', 18, 33, 11, '神は私の足にかせをはめ、私の歩みをことごとく見張られる。」'),
('JPN', '约伯记', 18, 33, 12, '聞け。私はあなたに答える。このことであなたは正しくない。神は人よりも偉大なのだから。'),
('JPN', '约伯记', 18, 33, 13, 'なぜ、あなたは神と言い争うのか。自分のことばに、神がいちいち答えてくださらないからといって。'),
('JPN', '约伯记', 18, 33, 14, '神はある方法で語り、また、ほかの方法で語られるが、人はそれに気づかない。'),
('JPN', '约伯记', 18, 33, 15, '夢の中で、夜の幻の中で、深い眠りが人々を襲うとき、また寝床の上でまどろむとき、'),
('JPN', '约伯记', 18, 33, 16, 'そのとき、神はその人たちの耳を開き、彼らを懲らしめて、それを封印される。'),
('JPN', '约伯记', 18, 33, 17, '神は、人間がその悪いわざを取り除くようにし、人から高ぶりを離れさせ、'),
('JPN', '约伯记', 18, 33, 18, '人のたましいが滅びの穴に入らず、そのいのちが投げ槍で滅びないようにされる。'),
('JPN', '约伯记', 18, 33, 19, '神は、床の上で痛みをもって人を責め、いつまでも続く骨の病によってお叱りになる。'),
('JPN', '约伯记', 18, 33, 20, '彼のいのちは食物を嫌い、そのたましいはうまい物を嫌う。'),
('JPN', '约伯记', 18, 33, 21, 'その肉は衰え果てて見えなくなり、見えなかった骨があらわになる。'),
('JPN', '约伯记', 18, 33, 22, 'そのたましいは滅びの穴に、そのいのちは殺す者たちに近づく。'),
('JPN', '约伯记', 18, 33, 23, 'もし彼のそばに、一人の御使いが、千人に一人の仲介者がいて、その方が彼に代わって彼が誠実であることを告げてくれるなら、'),
('JPN', '约伯记', 18, 33, 24, '神は彼をあわれんで仰せられる。「彼を救って、滅びの穴に下って行かないようにせよ。わたしは身代金を見出した」と。'),
('JPN', '约伯记', 18, 33, 25, 'その肉は幼子のように新しくされて、彼は青年のころに戻る。'),
('JPN', '约伯记', 18, 33, 26, '彼は、神に祈ると受け入れられる。彼は歓喜の声をもって御顔を仰ぎ、神はその人の義に報いてくださる。'),
('JPN', '约伯记', 18, 33, 27, '彼は人々を見つめて言う。「私は罪ある者で、真っ直ぐなことを曲げてきた。しかし私は、当然の報いを受けなかった。'),
('JPN', '约伯记', 18, 33, 28, '神は、私が滅びの穴に下らないように、私のたましいを贖い出してくださった。私のいのちは光を見ることができる」と。'),
('JPN', '约伯记', 18, 33, 29, '見よ、このすべてのことを神は行われる。二度も三度も、人に対して。'),
('JPN', '约伯记', 18, 33, 30, '人のたましいを滅びの穴から引き戻し、いのちの光で照らされる。'),
('JPN', '约伯记', 18, 33, 31, 'ヨブよ、耳を傾けて私に聞け。黙れ。この私が語る。'),
('JPN', '约伯记', 18, 33, 32, 'もし、ことばがあるなら、私に返事をせよ。言え。あなたが正しければ、それを私は喜ぶから。'),
('JPN', '约伯记', 18, 33, 33, 'もし、ことばがないなら、私に聞け。黙れ。私はあなたに知恵を教えよう。'),
('JPN', '约伯记', 18, 34, 1, 'エリフはさらに言った。'),
('JPN', '约伯记', 18, 34, 2, '知恵のある人々よ、私のことばを聞け。知識のある人々よ、私に耳を傾けよ。'),
('JPN', '约伯记', 18, 34, 3, '耳はことばを聞き分け、口は食物を味わうからだ。'),
('JPN', '约伯记', 18, 34, 4, 'さあ、私たちのために正しいことを選び、私たちの間で、何が良いことかをよく知ろう。'),
('JPN', '约伯记', 18, 34, 5, 'ヨブはこう言っているからだ。「私は正しい。神が私の正義を取り去ったのだ。'),
('JPN', '约伯记', 18, 34, 6, '私の正義に反して、私は偽りを言えるだろうか。背きがないのに、私の矢傷は治らない。」'),
('JPN', '约伯记', 18, 34, 7, 'ヨブのような人がほかにいるだろうか。彼は嘲りを水のように飲み、'),
('JPN', '约伯记', 18, 34, 8, '不法を行う者どもとよく交わり、悪人たちとともに歩む。'),
('JPN', '约伯记', 18, 34, 9, '彼は言っている。「神に喜ばれようとしても、それは人の役に立たない。」'),
('JPN', '约伯记', 18, 34, 10, 'だから、あなたがた良識のある人々よ、私に聞け。神が悪を行うなど、全能者が不正をするなど、絶対にあり得ない。'),
('JPN', '约伯记', 18, 34, 11, '神は、人の行いに応じて報いをし、それぞれをその道にしたがって取り扱われる。'),
('JPN', '约伯记', 18, 34, 12, '神は決して悪を行わない。全能者はさばきを曲げない。'),
('JPN', '约伯记', 18, 34, 13, 'だれが、この地を神にゆだねたのか。だれが、全世界を神に任せたのか。'),
('JPN', '约伯记', 18, 34, 14, 'もし、神がご自分だけに心を留め、その霊と息をご自分に集められたら、'),
('JPN', '约伯记', 18, 34, 15, 'すべての肉なるものはともに息絶え、人は土のちりに帰る。'),
('JPN', '约伯记', 18, 34, 16, '悟ることができるなら、これを聞け。私の言うことに耳を傾けよ。'),
('JPN', '约伯记', 18, 34, 17, 'いったい、公正を憎む者が、治めることができるだろうか。正しく力ある方を不義に定めることができるだろうか。'),
('JPN', '约伯记', 18, 34, 18, '人が王に向かって「よこしまな者」と言い、高貴な人に向かって「悪者」と言えるだろうか。'),
('JPN', '约伯记', 18, 34, 19, 'この方は、首長たちをえこひいきせず、上流の人を貧しい民より重んじることはない。彼らはみな、神の御手のわざだからだ。'),
('JPN', '约伯记', 18, 34, 20, '彼らは瞬く間に、それも真夜中に死に、民は動揺のうちにいなくなる。強い者たちも人の手によらずに取り去られる。'),
('JPN', '约伯记', 18, 34, 21, '神の御目が人の道の上にあり、その歩みのすべてを神が見ておられるからだ。'),
('JPN', '约伯记', 18, 34, 22, '不法を行う者どもが身を隠せる闇はなく、暗黒もない。'),
('JPN', '约伯记', 18, 34, 23, '神は人について、それ以上調べる必要はない。さばきのときに、神の前に出させてまでして。'),
('JPN', '约伯记', 18, 34, 24, '神は力ある者を、取り調べなしに打ち滅ぼし、彼らに代えてほかの者たちを立てられる。'),
('JPN', '约伯记', 18, 34, 25, '神は彼らのしわざを知っており、夜に彼らを打ち倒される。彼らは砕かれる。'),
('JPN', '约伯记', 18, 34, 26, '神は、人々の見ているところで、彼らをその邪悪さのゆえに打ちたたかれる。'),
('JPN', '约伯记', 18, 34, 27, 'それは、彼らが神に背いて従わず、神のどの道にも心を留めなかったからだ。'),
('JPN', '约伯记', 18, 34, 28, 'こうして、弱い者の叫びを神に届かせ、神は苦しむ者たちの叫びを聞き入れられる。'),
('JPN', '约伯记', 18, 34, 29, '神が黙っておられるなら、だれがとがめることができるだろうか。神が御顔を隠しておられるなら、だれが神を認めることができるだろうか。一つの国民においても、一人の人間においても同様だ。'),
('JPN', '约伯记', 18, 34, 30, 'それは、神を敬わない人間が治めたり、民を罠にかけたりしないようにするためだ。'),
('JPN', '约伯记', 18, 34, 31, '神に向かってだれかが言ったか。「私は懲らしめを受けました。私はもう悪いことはいたしません。'),
('JPN', '约伯记', 18, 34, 32, '私が見ていないことを、あなたが私に教えてください。私が不正をしたのでしたら、もういたしません」と。'),
('JPN', '约伯记', 18, 34, 33, 'あなたが反対するからといって、神はあなたの願うとおりに報復されるだろうか。私ではなく、あなたが選ぶがよい。あなたの知っていることを言うがよい。'),
('JPN', '约伯记', 18, 34, 34, '良識のある人々や、私に聞く、知恵のある人は私に言うだろう。'),
('JPN', '约伯记', 18, 34, 35, '「ヨブは知識もなしに語る。彼のことばは聡明さに欠けている」と。'),
('JPN', '约伯记', 18, 34, 36, 'どうか、ヨブが最後まで試されるように。彼は不法者のように、ことばを返すからだ。'),
('JPN', '约伯记', 18, 34, 37, '彼は自分の罪にさらに背きを加え、私たちの間で手を打ち鳴らし、神に対してことば数を多くする。'),
('JPN', '约伯记', 18, 35, 1, 'エリフはさらに言った。'),
('JPN', '约伯记', 18, 35, 2, 'あなたは、このことが正義によると見なしているのか。「私の義は神からだ」とでも言うのか。'),
('JPN', '约伯记', 18, 35, 3, 'というのは、あなたがこう言っているからだ。「何があなたの役に立つのでしょうか。私が罪から離れると、どんな利益があるのでしょうか」と。'),
('JPN', '约伯记', 18, 35, 4, '私はあなたにことばを返そう。あなたとともにいる友人たちにも。'),
('JPN', '约伯记', 18, 35, 5, '天を仰ぎ見よ。あなたより、はるかに高い雲をよく見よ。'),
('JPN', '约伯记', 18, 35, 6, 'あなたが罪を犯したとしても、あなたは神に対して何ができるのか。あなたの背きが多くあるとしても、神に対して何をなし得るのか。'),
('JPN', '约伯记', 18, 35, 7, 'あなたが正しかったとしても、神に何を与えられるのか。神は、あなたの手から何を受けられるのか。'),
('JPN', '约伯记', 18, 35, 8, 'あなたの悪は、ただあなたのような人間に、あなたの正しさは、人の子に関わるだけだ。'),
('JPN', '约伯记', 18, 35, 9, '人々は、激しい抑圧のために泣き叫び、偉大な者の腕のために、助けを叫び求める。'),
('JPN', '约伯记', 18, 35, 10, 'しかし、だれも問わない。「私の造り主である神はどこにおられるのか。夜、ほめ歌を下さる方は。'),
('JPN', '约伯记', 18, 35, 11, '地の獣に教えるより、私たちに多くを教え、空の鳥より、私たちを賢くする方は」と。'),
('JPN', '约伯记', 18, 35, 12, 'そこでは、彼らが泣き叫んでも神は答えない。悪人がおごり高ぶっているからだ。'),
('JPN', '约伯记', 18, 35, 13, '神は決して偽りの叫びを聞き入れず、全能者はこれに心を留めない。'),
('JPN', '约伯记', 18, 35, 14, '「神を見られない」とあなたが言うときには、なおさらだ。しかし訴えは神の前にある。あなたは神を待て。'),
('JPN', '约伯记', 18, 35, 15, 'しかし今、神は怒って罰しないだろうか。ひどい罪を知らずにいるだろうか。'),
('JPN', '约伯记', 18, 35, 16, 'ヨブは空しい口を開き、知識もなしに、自分の言い分を並べ立てている。'),
('JPN', '约伯记', 18, 36, 1, 'エリフはさらに続けて言った。'),
('JPN', '约伯记', 18, 36, 2, 'しばらく待て。あなたに示そう。まだ神のために言い分があるからだ。'),
('JPN', '约伯记', 18, 36, 3, '私は遠くから私の意見を持って来て、私の造り主に義を返そう。'),
('JPN', '约伯记', 18, 36, 4, 'まことに、私の言い分は偽りではない。知識の完全な方が、あなたのそばにおられるのだ。'),
('JPN', '约伯记', 18, 36, 5, '見よ。神は強いが、だれをも蔑まれない。その理解の力は強い。'),
('JPN', '约伯记', 18, 36, 6, '神は悪しき者を生かしてはおかず、苦しむ者には権利を与えられる。'),
('JPN', '约伯记', 18, 36, 7, '神は正しい者から目を離さず、彼らを王座にある王たちとともに、永遠に座に着かせる。こうして彼らは高くなる。'),
('JPN', '约伯记', 18, 36, 8, 'もし、彼らが鎖で縛られ、苦しみの縄に捕らえられたら、'),
('JPN', '约伯记', 18, 36, 9, '神は彼らの行いを彼らに告げられる。彼らの背きを。彼らがおごり高ぶったからである。'),
('JPN', '约伯记', 18, 36, 10, '神は彼らの耳を開いて戒め、不法から立ち返るように命じる。'),
('JPN', '约伯记', 18, 36, 11, 'もし彼らが聞き入れて神に仕えるなら、彼らは自分の日々を幸せのうちに、自分の年々を楽しみのうちに全うする。'),
('JPN', '约伯记', 18, 36, 12, 'しかし、もし聞き入れなければ、彼らは槍によって滅び、知識のないまま息絶える。'),
('JPN', '约伯记', 18, 36, 13, '心で神を敬わない者は怒りを蓄え、神が彼らを縛るときでも、助けを叫び求めない。'),
('JPN', '约伯记', 18, 36, 14, '彼らは若くして死に、そのいのちは腐れている。'),
('JPN', '约伯记', 18, 36, 15, '神は苦しむ人をその苦しみの中で助け出し、抑圧の中で彼らの耳を開かれる。'),
('JPN', '约伯记', 18, 36, 16, '神はまた、あなたを苦難の中から誘い出し、束縛のない広いところに導かれる。豊かな食物が備えられた、食卓での安らぎに。'),
('JPN', '约伯记', 18, 36, 17, 'あなたには悪しき者へのさばきが満ちている。さばきと公正があなたを捕らえる。'),
('JPN', '约伯记', 18, 36, 18, 'だからあなたは、憤って、豊かさに誘い込まれないようにせよ。身代金が多いからといって、それに惑わされないようにせよ。'),
('JPN', '约伯记', 18, 36, 19, 'あなたの叫びが並べ立てられても、力の限りが尽くされても、それは役に立たないのではないか。'),
('JPN', '约伯记', 18, 36, 20, '人々が取り去られる夜を、あえぎ求めてはならない。'),
('JPN', '约伯记', 18, 36, 21, '不法に向かわないように注意せよ。あなたは苦しみよりも、これを選んだのだから。'),
('JPN', '约伯记', 18, 36, 22, '見よ、神は力にすぐれておられる。神のような教師が、だれかいるだろうか。'),
('JPN', '约伯记', 18, 36, 23, 'だれが神にその道を指図したのか。だれが「あなたは不正をした」と言ったのか。'),
('JPN', '约伯记', 18, 36, 24, '神のみわざを覚えて賛美せよ。人々がほめ歌った、そのみわざを。'),
('JPN', '约伯记', 18, 36, 25, 'すべての人がこれを見、人が遠くからこれを眺める。'),
('JPN', '约伯记', 18, 36, 26, '見よ。神はいと高く、私たちには知ることができない。その年の数も測り知ることができない。'),
('JPN', '约伯记', 18, 36, 27, '神は水のしずくを引き上げ、それが雨を滴らせて、水の流れとなる。'),
('JPN', '约伯记', 18, 36, 28, '雨雲がこれを降らせ、人の上に豊かに滴らせる。'),
('JPN', '约伯记', 18, 36, 29, 'いったい、だれが濃い雲の広がりと、その幕屋のとどろきを理解できるだろうか。'),
('JPN', '约伯记', 18, 36, 30, '見よ。神はご自分の光をその上に照り渡らせ、また、海の底をおおわれる。'),
('JPN', '约伯记', 18, 36, 31, '神はこれらによって民をさばき、食物を豊かにお与えになる。'),
('JPN', '约伯记', 18, 36, 32, '神は稲妻を両手に包み、これに命じて的を撃たせられる。'),
('JPN', '约伯记', 18, 36, 33, 'その雷鳴は、神について告げ、家畜もまた、起こることについて告げる。'),
('JPN', '约伯记', 18, 37, 1, 'これによって私の心は震え、そこから離れ去るほどだ。'),
('JPN', '约伯记', 18, 37, 2, 'よく聞け。その御声が荒れ狂うのを。その御口から出るとどろきを。'),
('JPN', '约伯记', 18, 37, 3, '神は、天の下のいたるところで放たれる。その稲妻を、地の隅々までも。'),
('JPN', '约伯记', 18, 37, 4, 'その後で雷が鳴りとどろく。神はいかめしい声で雷鳴をとどろかせ、その御声が聞こえるとき、手加減をなさらない。'),
('JPN', '约伯记', 18, 37, 5, '神は御声で、驚くほどに雷鳴をとどろかせ、私たちの知り得ない大きなことをされる。'),
('JPN', '约伯记', 18, 37, 6, '神は雪に対して、地に降れと命じ、夕立に、激しい大雨にも命じられる。'),
('JPN', '约伯记', 18, 37, 7, '神はすべての人の手を封じ込められる。神の造った人間が知るために。'),
('JPN', '约伯记', 18, 37, 8, '獣は巣にもぐり、洞穴の中にうずくまる。'),
('JPN', '约伯记', 18, 37, 9, 'つむじ風は天の間から、寒さは北の方から来る。'),
('JPN', '约伯记', 18, 37, 10, '神の息によって氷が張り、広々とした水が凍りつく。'),
('JPN', '约伯记', 18, 37, 11, '神は濃い雲に水気を含ませ、雲がその稲妻を放つ。'),
('JPN', '约伯记', 18, 37, 12, 'それは神の指図によって巡り回り、事を行う。神が命じるすべてのことを、世界の地の面で。'),
('JPN', '约伯记', 18, 37, 13, '神は、懲らしめのため、ご自分の地のため、または恵みのために、これが起こるようにされる。'),
('JPN', '约伯记', 18, 37, 14, 'ヨブよ、これに耳を傾けよ。神の奇しいみわざを、立ち止まって考えよ。'),
('JPN', '约伯记', 18, 37, 15, 'あなたは知っているか。神がどのようにこれらに命じ、その雲に稲妻をひらめかせられるのかを。'),
('JPN', '约伯记', 18, 37, 16, 'あなたは知っているか。濃い雲のつり合いを、知識の完全な方の不思議なみわざを。'),
('JPN', '约伯记', 18, 37, 17, 'また、南風で地が黙するときに、あなたの衣がいかに熱くなるかを。'),
('JPN', '约伯记', 18, 37, 18, 'あなたは大空を神とともに張り広げられるのか。鋳た鏡のように硬いものを。'),
('JPN', '约伯记', 18, 37, 19, '神に何と言うべきかを私たちに教えよ。闇があるので、ことばを並べることができない。'),
('JPN', '约伯记', 18, 37, 20, '私が語りたいと、神に伝えられるだろうか。人がことばを発すれば、その人は必ず滅ぼされる。'),
('JPN', '约伯记', 18, 37, 21, '今、光は見ることができない。それは雨雲の中に輝いている。しかし、風が吹いて雲を払いのけると、'),
('JPN', '约伯记', 18, 37, 22, '北から黄金の輝きが現れ、神の周りには恐るべき威厳がある。'),
('JPN', '约伯记', 18, 37, 23, '私たちが見出すことのできない全能者は、力にすぐれた方。さばきと正義に富み、苦しめることをなさらない。'),
('JPN', '约伯记', 18, 37, 24, 'だから、人々は神を恐れなければならない。神は心に知恵ある者を顧みられないだろうか。'),
('JPN', '约伯记', 18, 38, 1, '主は嵐の中からヨブに答えられた。'),
('JPN', '约伯记', 18, 38, 2, '知識もなしに言い分を述べて、摂理を暗くするこの者はだれか。'),
('JPN', '约伯记', 18, 38, 3, 'さあ、あなたは勇士のように腰に帯を締めよ。わたしはあなたに尋ねる。わたしに示せ。'),
('JPN', '约伯记', 18, 38, 4, 'わたしが地の基を定めたとき、あなたはどこにいたのか。分かっているなら、告げてみよ。'),
('JPN', '约伯记', 18, 38, 5, 'あなたは知っているはずだ。だれがその大きさを定め、だれがその上に測り縄を張ったかを。'),
('JPN', '约伯记', 18, 38, 6, 'その台座は何の上にはめ込まれたのか。あるいは、その要の石はだれが据えたのか。'),
('JPN', '约伯记', 18, 38, 7, '明けの星々がともに喜び歌い、神の子たちがみな喜び叫んだときに。'),
('JPN', '约伯记', 18, 38, 8, '海が噴き出て、胎内から流れ出たとき、だれが戸でこれを閉じ込めたのか。'),
('JPN', '约伯记', 18, 38, 9, 'そのとき、わたしは雲をその衣とし、暗黒をその産衣とした。'),
('JPN', '约伯记', 18, 38, 10, 'わたしは、これを区切って境を定め、かんぬきと戸を設けて、'),
('JPN', '约伯记', 18, 38, 11, '言った。「ここまでは来てもよい。しかし、これ以上はいけない。おまえの高ぶる波はここでとどまれ」と。'),
('JPN', '约伯记', 18, 38, 12, 'あなたは生まれてこのかた、朝に対して命令を下し、暁に対してあるべき場所を指し示して、'),
('JPN', '约伯记', 18, 38, 13, 'これに地の縁をつかませ、悪しき者をそこから振り落としたことがあるか。'),
('JPN', '约伯记', 18, 38, 14, '地は押印された粘土のように姿を変え、そこにあるものは王服のように彩られる。'),
('JPN', '约伯记', 18, 38, 15, 'その光は悪しき者から退けられ、振り上げられた腕は折られる。'),
('JPN', '约伯记', 18, 38, 16, 'あなたは海の源まで行ったことがあるか。深淵の奥底を歩き回ったことがあるか。'),
('JPN', '约伯记', 18, 38, 17, '死の門があなたに現れたことがあるか。死の陰の門を見たことがあるか。'),
('JPN', '约伯记', 18, 38, 18, '地の広さを見極めたことがあるか。そのすべてを知っているなら、告げてみよ。'),
('JPN', '约伯记', 18, 38, 19, '光の住む所への道はどこか。闇のあるその場所はどこか。'),
('JPN', '约伯记', 18, 38, 20, '光をその国境まで連れて行くというのか。闇の家に至る通りを見分けるというのか。'),
('JPN', '约伯记', 18, 38, 21, 'あなたはよく知っているはずだ。そのとき、あなたは生まれていて、あなたの日数は多いのだから。'),
('JPN', '约伯记', 18, 38, 22, 'あなたは雪の倉に入ったことがあるか。雹の倉を見たことがあるか。'),
('JPN', '约伯记', 18, 38, 23, 'これらは、わたしがとどめているのだ。苦難の時のため、争いと戦の日のために。'),
('JPN', '约伯记', 18, 38, 24, '光が分かれる道はどこか。東風が地の上で分かれ広がる道は。'),
('JPN', '约伯记', 18, 38, 25, 'だれが、大水のために水路を、稲光のために道を切り開き、'),
('JPN', '约伯记', 18, 38, 26, '人のいない地、人間のいない荒野に雨を降らせ、'),
('JPN', '约伯记', 18, 38, 27, '荒れ果てた廃墟の地を満ち足らせ、それに若草を生えさせるのか。'),
('JPN', '约伯记', 18, 38, 28, '雨に父があるのか。露のしずくはだれが生んだのか。'),
('JPN', '约伯记', 18, 38, 29, '氷はだれの胎から出て来たのか。空の白い霜はだれが生んだのか。'),
('JPN', '约伯记', 18, 38, 30, '水は姿を変えて石のようになり、深い淵の面は凍る。'),
('JPN', '约伯记', 18, 38, 31, 'あなたはすばるの鎖を結ぶことができるか。オリオン座の綱を解くことができるか。'),
('JPN', '约伯记', 18, 38, 32, 'あなたは十二宮をその時にかなって、引き出すことができるか。牡牛座をその子の星とともに導くことができるか。'),
('JPN', '约伯记', 18, 38, 33, 'あなたは天の掟を知っているか。地にその法則を立てることができるか。'),
('JPN', '约伯记', 18, 38, 34, 'あなたの声を密雲にまであげ、みなぎる水にあなたをおおわせることができるか。'),
('JPN', '约伯记', 18, 38, 35, 'あなたは稲妻を向こうに行かせ、あなたに向かって「私たちはここです」と言わせることができるか。'),
('JPN', '约伯记', 18, 38, 36, 'だれが、隠されたところに知恵を置いたのか。だれが、秘められたところに悟りを与えたのか。'),
('JPN', '约伯记', 18, 38, 37, 'だれが知恵をもって、雨雲を数えることができるか。だれが天の水袋を傾けることができるか。'),
('JPN', '约伯记', 18, 38, 38, '土が溶け合って塊となり、土くれが硬く固まるときに。'),
('JPN', '约伯记', 18, 38, 39, 'あなたは雌獅子のために獲物を狩り若い獅子の食欲を満たすことができるか。'),
('JPN', '约伯记', 18, 38, 40, 'それらが洞穴に伏し、茂みの中で待ち伏せしているときに。'),
('JPN', '约伯记', 18, 38, 41, '烏に餌を備えるのはだれか。烏の子が神に向かって鳴き叫び、食物がなくてさまようときに。'),
('JPN', '约伯记', 18, 39, 1, 'あなたは岩間の野やぎが子を産む時を知っているか。雌鹿が子を産むのを見守ったことがあるか。'),
('JPN', '约伯记', 18, 39, 2, 'あなたはこれらがはらんでいる月を、数えることができるか。それらが子を産む時を知っているか。'),
('JPN', '约伯记', 18, 39, 3, 'それらは身をかがめて子を産み落とし、その胎児を放り出す。'),
('JPN', '约伯记', 18, 39, 4, 'その子たちは強くなり、野で大きくなる。すると出て行って、元のところには帰らない。'),
('JPN', '约伯记', 18, 39, 5, 'だれが野ろばを解き放ったのか。だれが野生のろばの綱をほどいたのか。'),
('JPN', '约伯记', 18, 39, 6, 'わたしが、荒れた地をその家とし、不毛の地をその住みかとしたのだ。'),
('JPN', '约伯记', 18, 39, 7, 'それは町の騒ぎをあざ笑い、追い立てる者の叫び声を聞かない。'),
('JPN', '约伯记', 18, 39, 8, '山々を自分の牧場として歩き回り、青草なら何でも探し求める。'),
('JPN', '约伯记', 18, 39, 9, '野牛が喜んであなたに仕えるだろうか。あなたの飼葉桶のそばで夜を過ごすだろうか。'),
('JPN', '约伯记', 18, 39, 10, 'あなたはあぜ溝で、野牛に手綱をかけることができるか。それが、あなたに従って谷間を耕すだろうか。'),
('JPN', '约伯记', 18, 39, 11, 'その力が強いからといって、あなたはそれに拠り頼むだろうか。あなた自身の働きをこれに任せるだろうか。'),
('JPN', '约伯记', 18, 39, 12, 'あなたはそう信じているのか。それがあなたの穀物を持ち帰り、あなたの打ち場で、これを集めるとでも。'),
('JPN', '约伯记', 18, 39, 13, 'だちょうは翼を誇らしげに羽ばたかせるが、その羽はこうのとりの羽毛のようだろうか。'),
('JPN', '约伯记', 18, 39, 14, 'だちょうは卵を地面に置き去りにし、これを砂の上で温まるに任せ、'),
('JPN', '约伯记', 18, 39, 15, '自分の足がそれをつぶすかもしれないことを忘れている。野の獣が踏みつけるかもしれないことも。'),
('JPN', '约伯记', 18, 39, 16, 'だちょうは自分の子を、自分のものでないかのように荒く扱い、その産みの苦しみが、無駄になることも全く気にしない。'),
('JPN', '约伯记', 18, 39, 17, '神がこれに知恵を忘れさせ、これに悟りを授けなかったからだ。'),
('JPN', '约伯记', 18, 39, 18, 'それが高く飛び跳ねるとき、馬とその乗り手をあざ笑う。'),
('JPN', '约伯记', 18, 39, 19, 'あなたが馬に力を与えるのか。その首にたてがみを付けるのか。'),
('JPN', '约伯记', 18, 39, 20, 'あなたはこれを、いなごのように飛び跳ねさせることができるのか。その威厳あるいななきは恐ろしい。'),
('JPN', '约伯记', 18, 39, 21, '馬は谷間で、前かきをして力を喜び、武器に立ち向かって進んで行く。'),
('JPN', '约伯记', 18, 39, 22, '恐怖をあざ笑って、ひるむことなく、剣の前から退くことはない。'),
('JPN', '约伯记', 18, 39, 23, '矢筒はその上でうなり、槍と投げ槍はきらめく。'),
('JPN', '约伯记', 18, 39, 24, '荒れ狂って、地を駆け回り、角笛の音に、じっとしてはいられない。'),
('JPN', '约伯记', 18, 39, 25, '角笛が鳴るごとに、ヒヒーンといななき、遠くから戦いを嗅ぎつける。隊長の怒号、ときの声さえも。'),
('JPN', '约伯记', 18, 39, 26, 'あなたの考えによってか。鷹が舞い上がり、南にその翼を広げるのは。'),
('JPN', '约伯记', 18, 39, 27, 'あなたの命令によってか。鷲が高く上がり、その巣を高いところに作るのは。'),
('JPN', '约伯记', 18, 39, 28, 'それは岩場に宿って住み、近寄りがたい切り立つ岩の上にいる。'),
('JPN', '约伯记', 18, 39, 29, 'そこから獲物をうかがい、その目は遠くまで見渡す。'),
('JPN', '约伯记', 18, 39, 30, 'ひなは血を吸い、殺されたもののところに、それはいる。'),
('JPN', '约伯记', 18, 40, 1, '主はヨブに答えられた。'),
('JPN', '约伯记', 18, 40, 2, '非難する者が全能者と争おうとするのか。神を責める者は、それに答えよ。'),
('JPN', '约伯记', 18, 40, 3, 'ヨブは主に答えた。'),
('JPN', '约伯记', 18, 40, 4, 'ああ、私は取るに足りない者です。あなたに何と口答えできるでしょう。私はただ手を口に当てるばかりです。'),
('JPN', '约伯记', 18, 40, 5, '一度、私は語りました。もう答えません。二度、語りました。もう繰り返しません。'),
('JPN', '约伯记', 18, 40, 6, '主は嵐の中からヨブに答えられた。'),
('JPN', '约伯记', 18, 40, 7, 'さあ、あなたは勇士のように腰に帯を締めよ。わたしはあなたに尋ねる。わたしに示せ。'),
('JPN', '约伯记', 18, 40, 8, 'あなたはわたしのさばきを無効にするつもりか。自分を義とするため、わたしを不義に定めるのか。'),
('JPN', '约伯记', 18, 40, 9, 'あなたには神のような腕があるのか。神のような声で雷鳴をとどろき渡らせるのか。'),
('JPN', '约伯记', 18, 40, 10, 'さあ、誉れと気高さで身を飾り、威厳と威光を身にまとえ。'),
('JPN', '约伯记', 18, 40, 11, 'あなたの激しい怒りを吐き散らし、すべて高ぶる者を見て、これを低くせよ。'),
('JPN', '约伯记', 18, 40, 12, 'すべて高ぶる者を見て、これを押さえ、悪者どもを、その場で踏みにじれ。'),
('JPN', '约伯记', 18, 40, 13, '彼らをともに土のちりの中に隠し、その顔を隠れた所につなぎとめよ。'),
('JPN', '约伯记', 18, 40, 14, 'そうすれば、わたしもあなたをたたえて言う。「あなたの右の手は自分を救うことができる」と。'),
('JPN', '约伯记', 18, 40, 15, 'さあ、河馬を見よ。これはあなたと並べてわたしが造ったもの。牛のように草をはむ。'),
('JPN', '约伯记', 18, 40, 16, '見よ。その力は腰にあり、その強さは腹の筋にある。'),
('JPN', '约伯记', 18, 40, 17, '尾は杉の木のように垂れ下がり、ももの筋は絡み合っている。'),
('JPN', '约伯记', 18, 40, 18, '骨は青銅の管、肋骨は鉄の棒のようだ。'),
('JPN', '约伯记', 18, 40, 19, 'これは神の作品の第一のもの、これを造った者が、その剣でこれに近づく。'),
('JPN', '约伯记', 18, 40, 20, '山々はこの獣のために産物をもたらし、野の獣もみなそこで戯れる。'),
('JPN', '约伯记', 18, 40, 21, '蓮の下にそれは横たわる。葦の茂み、沼地の中で。'),
('JPN', '约伯记', 18, 40, 22, '蓮はこれをその陰でおおい、川の柳はこれを囲む。'),
('JPN', '约伯记', 18, 40, 23, 'たとえ川があふれても、慌てない。ヨルダン川が口に注ぎ込んでも、動じない。'),
('JPN', '约伯记', 18, 40, 24, 'その目をつかんで、これを捕らえられるか。罠にかけて、その鼻を突き通せるか。'),
('JPN', '约伯记', 18, 41, 1, 'あなたは釣り針でレビヤタンを釣り上げることができるか。輪縄でその舌を押さえつけることができるか。'),
('JPN', '约伯记', 18, 41, 2, 'あなたは葦をその鼻に通すことができるか。鉤をそのあごに突き通すことができるか。'),
('JPN', '约伯记', 18, 41, 3, 'これが、しきりにあなたに哀願し、優しく語りかけるだろうか。'),
('JPN', '约伯记', 18, 41, 4, 'これがあなたと契約を結び、あなたがこれを捕らえて、永久に奴隷とすることになるだろうか。'),
('JPN', '约伯记', 18, 41, 5, 'あなたは鳥と戯れるように、これと戯れ、娘たちのために、これをつなぐことができるか。'),
('JPN', '约伯记', 18, 41, 6, '漁師仲間がこれを競りにかけ、商人たちの間で分けるだろうか。'),
('JPN', '约伯记', 18, 41, 7, 'あなたは銛でその皮を、やすでその頭を突くことができるだろうか。'),
('JPN', '约伯记', 18, 41, 8, 'その上にあなたの手を置いてみよ。その戦いを思い出して、二度と手を出すな。'),
('JPN', '约伯记', 18, 41, 9, '見よ。それに立ち向かう期待は裏切られる。それを見ただけで圧倒されるではないか。'),
('JPN', '约伯记', 18, 41, 10, 'それを起こすほどの狂暴な者はいない。そうであれば、だれがいったい、わたしの前に立つことができるだろうか。'),
('JPN', '约伯记', 18, 41, 11, 'だれが、まずわたしに与えたというのか。わたしがそれに報いなければならないほどに。天の下にあるものはみな、わたしのものだ。'),
('JPN', '约伯记', 18, 41, 12, 'そのからだの部分についてわたしは黙ってはいられない。それの力強さと、その体格の見事さについて。'),
('JPN', '约伯记', 18, 41, 13, 'だれが、その外套をはぎ取ることができるか。胸当ての折り目の間に入ることができるか。'),
('JPN', '约伯记', 18, 41, 14, 'だれが、その顔の戸を開けることができるか。その歯の周りには恐怖がある。'),
('JPN', '约伯记', 18, 41, 15, 'その背は並んだ盾、封印したように固く閉じている。'),
('JPN', '约伯记', 18, 41, 16, '一つ一つぴったり付いて、風もその間を通れない。'),
('JPN', '约伯记', 18, 41, 17, '互いにくっつき、固くつながって離れない。'),
('JPN', '约伯记', 18, 41, 18, 'そのくしゃみは光を放ち、その目は暁のまぶたのようだ。'),
('JPN', '约伯记', 18, 41, 19, 'その口からは、たいまつが燃え出し、火花が噴き出す。'),
('JPN', '约伯记', 18, 41, 20, 'その鼻からは煙が出て、煮え立つ釜や、燃える葦のようだ。'),
('JPN', '约伯记', 18, 41, 21, 'その息は炭火をおこし、その口からは炎が出る。'),
('JPN', '约伯记', 18, 41, 22, 'その首には力が宿り、その前には恐れが踊る。'),
('JPN', '约伯记', 18, 41, 23, 'その肉のひだはつなぎ合わされ、その身に固く付いて、揺るがない。'),
('JPN', '约伯记', 18, 41, 24, 'その心臓は石のように硬く、臼の下石のように硬い。'),
('JPN', '约伯记', 18, 41, 25, 'それが起き上がると、力ある者もおじけづき、おろおろして逃げ惑う。'),
('JPN', '约伯记', 18, 41, 26, 'それを剣で襲っても無駄だ。槍でも、投げ矢でも、矢じりでも。'),
('JPN', '约伯记', 18, 41, 27, 'それは鉄を藁のように、青銅を腐った木のように見なす。'),
('JPN', '约伯记', 18, 41, 28, '矢によっても、それが逃げるようにはできず、石投げの石も、それには藁となる。'),
('JPN', '约伯记', 18, 41, 29, 'こん棒さえ藁のように見なし、投げ槍のうなる音をあざ笑う。'),
('JPN', '约伯记', 18, 41, 30, 'その下腹は鋭い土器のかけら、それは打穀機のように泥の上に身を伸ばす。'),
('JPN', '约伯记', 18, 41, 31, 'それは深みを釜のように沸き立たせ、海を、香油をかき混ぜる鍋のようにする。'),
('JPN', '约伯记', 18, 41, 32, 'それが通った跡には光が輝き、深淵は白髪のように見なされる。'),
('JPN', '约伯记', 18, 41, 33, '地の上に、これと似たものはなく、恐れを知らないものとして造られた。'),
('JPN', '约伯记', 18, 41, 34, '高いものすべてを見下ろし、誇り高い獣すべての王である。'),
('JPN', '约伯记', 18, 42, 1, 'ヨブは主に答えた。'),
('JPN', '约伯记', 18, 42, 2, 'あなたには、すべてのことができること、どのような計画も不可能ではないことを、私は知りました。'),
('JPN', '约伯记', 18, 42, 3, 'あなたは言われます。「知識もなしに摂理をおおい隠す者はだれか」と。確かに私は、自分の理解できないことを告げてしまいました。自分では知り得ない、あまりにも不思議なことを。'),
('JPN', '约伯记', 18, 42, 4, 'あなたは言われます。「さあ、聞け。わたしが語る。わたしがあなたに尋ねる。わたしに示せ」と。'),
('JPN', '约伯记', 18, 42, 5, '私はあなたのことを耳で聞いていました。しかし今、私の目があなたを見ました。'),
('JPN', '约伯记', 18, 42, 6, 'それで、私は自分を蔑み、悔いています。ちりと灰の中で。'),
('JPN', '约伯记', 18, 42, 7, '主がこれらのことばをヨブに語った後、主はテマン人エリファズに言われた。「わたしの怒りはあなたとあなたの二人の友に向かって燃える。あなたがたが、わたしのしもべヨブのように、わたしについて確かなことを語らなかったからだ。'),
('JPN', '约伯记', 18, 42, 8, '今、あなたがたは雄牛七頭と雄羊七匹を取って、わたしのしもべヨブのところに行き、自分たちのために全焼のささげ物を献げよ。わたしのしもべヨブがあなたがたのために祈る。わたしは彼の願いを受け入れるので、あなたがたの愚行に報いるようなことはしない。あなたがたは、わたしのしもべヨブのように、わたしについて確かなことを語らなかったが。」'),
('JPN', '约伯记', 18, 42, 9, 'テマン人エリファズと、シュアハ人ビルダデと、ナアマ人ツォファルは行って、主が彼らに命じられたようにした。すると主はヨブの願いを受け入れられた。'),
('JPN', '约伯记', 18, 42, 10, 'ヨブがその友人たちのために祈ったとき、主はヨブを元どおりにされた。さらに主はヨブの財産をすべて、二倍にされた。'),
('JPN', '约伯记', 18, 42, 11, 'こうして彼のすべての兄弟、すべての姉妹、それに以前のすべての知人は、彼のところに来て、彼の家で一緒に食事をした。そして彼に同情し、主が彼の上にもたらされたすべてのわざわいについて、彼を慰めた。彼らはそれぞれ一ケシタと金の輪一つずつを彼に与えた。'),
('JPN', '约伯记', 18, 42, 12, '主はヨブの後の半生を前の半生に増して祝福された。それで彼は羊一万四千匹、らくだ六千頭、牛一千くびき、雌ろば一千頭を持つことになった。'),
('JPN', '约伯记', 18, 42, 13, 'また、息子七人、娘三人を持った。'),
('JPN', '约伯记', 18, 42, 14, '彼はその第一の娘をエミマ、第二の娘をケツィア、第三の娘をケレン・ハ・プクと名づけた。'),
('JPN', '约伯记', 18, 42, 15, 'ヨブの娘たちほど美しい女は、この地のどこにも見つからなかった。彼女たちの父は彼女たちに、その兄弟たちの間で相続地を分け与えた。'),
('JPN', '约伯记', 18, 42, 16, 'この後ヨブは百四十年生き、自分の子と、その子の子たちを四代目まで見た。'),
('JPN', '约伯记', 18, 42, 17, 'こうしてヨブは死んだ。年老いて満ち足りた生涯であった。'),
('JPN', '诗篇', 19, 1, 1, '幸いなことよ悪しき者のはかりごとに歩まず罪人の道に立たず嘲る者の座に着かない人。'),
('JPN', '诗篇', 19, 1, 2, '主のおしえを喜びとし昼も夜もそのおしえを口ずさむ人。'),
('JPN', '诗篇', 19, 1, 3, 'その人は流れのほとりに植えられた木。時が来ると実を結びその葉は枯れずそのなすことはすべて栄える。'),
('JPN', '诗篇', 19, 1, 4, '悪しき者はそうではない。まさしく風が吹き飛ばす籾殻だ。'),
('JPN', '诗篇', 19, 1, 5, 'それゆえ悪しき者はさばきに罪人は正しい者の集いに立ち得ない。'),
('JPN', '诗篇', 19, 1, 6, 'まことに正しい者の道は主が知っておられ悪しき者の道は滅び去る。'),
('JPN', '诗篇', 19, 2, 1, 'なぜ国々は騒ぎ立ちもろもろの国民は空しいことを企むのか。'),
('JPN', '诗篇', 19, 2, 2, 'なぜ地の王たちは立ち構え君主たちは相ともに集まるのか。主と主に油注がれた者に対して。'),
('JPN', '诗篇', 19, 2, 3, '「さあ彼らのかせを打ち砕き彼らの綱を解き捨てよう。」'),
('JPN', '诗篇', 19, 2, 4, '天の御座に着いておられる方は笑い主はその者どもを嘲られる。'),
('JPN', '诗篇', 19, 2, 5, 'そのとき主は怒りをもって彼らに告げ激しく怒って彼らを恐れおののかせる。'),
('JPN', '诗篇', 19, 2, 6, '「わたしがわたしの王を立てたのだ。わたしの聖なる山シオンに。」'),
('JPN', '诗篇', 19, 2, 7, '「私は主の定めについて語ろう。主は私に言われた。『あなたはわたしの子。わたしが今日あなたを生んだ。'),
('JPN', '诗篇', 19, 2, 8, 'わたしに求めよ。わたしは国々をあなたへのゆずりとして与える。地の果ての果てまであなたの所有として。'),
('JPN', '诗篇', 19, 2, 9, 'あなたは鉄の杖で彼らを牧し陶器師が器を砕くように粉々にする。』」'),
('JPN', '诗篇', 19, 2, 10, 'それゆえ今王たちよ悟れ。地をさばく者たちよ慎め。'),
('JPN', '诗篇', 19, 2, 11, '恐れつつ主に仕えよ。おののきつつ震え子に口づけせよ。'),
('JPN', '诗篇', 19, 2, 12, '主が怒りおまえたちが道で滅びないために。御怒りがすぐにも燃えようとしているからだ。幸いなことよすべて主に身を避ける人は。'),
('JPN', '诗篇', 19, 3, 1, '主よなんと私の敵が多くなり私に向かい立つ者が多くいることでしょう。'),
('JPN', '诗篇', 19, 3, 2, '多くの者が私のたましいのことを言っています。「彼には神の救いがない」と。セラ'),
('JPN', '诗篇', 19, 3, 3, 'しかし主よあなたこそ私の周りを囲む盾私の栄光私の頭を上げる方。'),
('JPN', '诗篇', 19, 3, 4, '私は声をあげて主を呼び求める。すると主はその聖なる山から私に答えてくださる。セラ'),
('JPN', '诗篇', 19, 3, 5, '私は身を横たえて眠りまた目を覚ます。主が私を支えてくださるから。'),
('JPN', '诗篇', 19, 3, 6, '私は幾万の民をも恐れない。彼らが私を取り囲もうとも。'),
('JPN', '诗篇', 19, 3, 7, '主よ立ち上がってください。私の神よお救いください。あなたは私のすべての敵の頬を打ち悪しき者の歯を砕いてくださいます。'),
('JPN', '诗篇', 19, 3, 8, '救いは主にあります。あなたの民にあなたの祝福がありますように。セラ'),
('JPN', '诗篇', 19, 4, 1, '私が呼ぶとき答えてください。私の義なる神。追いつめられたときあなたは私を解き放ってくださいました。私をあわれみ私の祈りを聞いてください。'),
('JPN', '诗篇', 19, 4, 2, '人の子たちよいつまで私の栄光を辱め空しいものを愛し偽りを慕い求めるのか。セラ'),
('JPN', '诗篇', 19, 4, 3, '知れ。主はご自分の聖徒を特別に扱われるのだ。私が呼ぶとき主は聞いてくださる。'),
('JPN', '诗篇', 19, 4, 4, '震えわななけ。罪を犯すな。心の中で語り床の上で静まれ。セラ'),
('JPN', '诗篇', 19, 4, 5, '義のいけにえを献げ主に拠り頼め。'),
('JPN', '诗篇', 19, 4, 6, '多くの者は言っています。「だれがわれわれに良い目を見させてくれるのか」と。主よどうかあなたの御顔の光を私たちの上に照らしてください。'),
('JPN', '诗篇', 19, 4, 7, 'あなたは喜びを私の心に下さいます。それは彼らに穀物と新しいぶどう酒が豊かにある時にもまさっています。'),
('JPN', '诗篇', 19, 4, 8, '平安のうちに私は身を横たえすぐ眠りにつきます。主よただあなただけが安らかに私を住まわせてくださいます。'),
('JPN', '诗篇', 19, 5, 1, '私のことばに耳を傾けてください。主よ。私のうめきを聞き取ってください。'),
('JPN', '诗篇', 19, 5, 2, '私の叫ぶ声を耳に留めてください。私の王私の神私はあなたに祈っています。'),
('JPN', '诗篇', 19, 5, 3, '主よ朝明けに私の声を聞いてください。朝明けに私はあなたの御前に備えをし仰ぎ望みます。'),
('JPN', '诗篇', 19, 5, 4, 'あなたは悪を喜ぶ神ではなくわざわいはあなたとともに住まないからです。'),
('JPN', '诗篇', 19, 5, 5, '誇り高ぶる者たちは御目の前に立つことはできません。あなたは不法を行う者をすべて憎まれます。'),
('JPN', '诗篇', 19, 5, 6, 'あなたは偽りを言う者どもを滅ぼされます。主は人の血を流す者や欺く者を忌み嫌われます。'),
('JPN', '诗篇', 19, 5, 7, 'しかし私はあなたの豊かな恵みによってあなたの家に行きあなたを恐れつつあなたの聖なる宮に向かってひれ伏します。'),
('JPN', '诗篇', 19, 5, 8, '主よ私を待ち伏せている者がいますからあなたの義によって私を導いてください。私の前にあなたの道をまっすぐにしてください。'),
('JPN', '诗篇', 19, 5, 9, '彼らの口には真実がなく心にあるのは破壊です。彼らの喉は開いた墓。彼らはその舌でへつらうのです。'),
('JPN', '诗篇', 19, 5, 10, '神よ彼らに責めを負わせてください。彼らが自分のはかりごとで倒れますように。その多くの背きのゆえに彼らを追い散らしてください。あなたに逆らっているからです。'),
('JPN', '诗篇', 19, 5, 11, 'どうかあなたに身を避ける者がみな喜びとこしえまでも喜び歌いますように。あなたが彼らをかばってくださり御名を愛する者たちがあなたを誇りますように。'),
('JPN', '诗篇', 19, 5, 12, '主よまことにあなたは正しい者を祝福し大盾のようにいつくしみでおおってくださいます。'),
('JPN', '诗篇', 19, 6, 1, '主よ御怒りで私を責めないでください。あなたの憤りで私を懲らしめないでください。'),
('JPN', '诗篇', 19, 6, 2, '主よ私をあわれんでください。私は衰えています。主よ私を癒やしてください。私の骨は恐れおののいています。'),
('JPN', '诗篇', 19, 6, 3, '私のたましいはひどく恐れおののいています。主よあなたはいつまで──。'),
('JPN', '诗篇', 19, 6, 4, '主よ帰って来て私のたましいを助け出してください。私を救ってください。あなたの恵みのゆえに。'),
('JPN', '诗篇', 19, 6, 5, '死においてはあなたを覚えることはありません。よみにおいてはだれがあなたをほめたたえるでしょう。'),
('JPN', '诗篇', 19, 6, 6, '私は嘆きで疲れ果て夜ごとに涙で寝床を漂わせふしどを大水で押し流します。'),
('JPN', '诗篇', 19, 6, 7, '私の目は苦悶で衰え私のすべての敵のゆえに弱まりました。'),
('JPN', '诗篇', 19, 6, 8, '不法を行う者たちみな私から離れて行け。主が私の泣く声を聞かれたからだ。'),
('JPN', '诗篇', 19, 6, 9, '主は私の切なる願いを聞き主は私の祈りを受け入れられる。'),
('JPN', '诗篇', 19, 6, 10, '私の敵がみな恥を見ひどく恐れおののきますように。彼らが退き恥を見ますように。瞬く間に。'),
('JPN', '诗篇', 19, 7, 1, '私の神主よ私はあなたに身を避けます。どうか追い迫るすべての者から私を救い助け出してください。'),
('JPN', '诗篇', 19, 7, 2, '彼らが獅子のように私のたましいを引き裂き助け出す者もなくさらって行かないように。'),
('JPN', '诗篇', 19, 7, 3, '私の神主よもしも私がこのことをしたのならもしも私の手に不正があるのなら'),
('JPN', '诗篇', 19, 7, 4, 'もしも私が親しい友に悪い仕打ちをしたのならまた私に敵対する者からゆえなく奪ったのなら'),
('JPN', '诗篇', 19, 7, 5, '敵が私のたましいに追い迫り追いつき私のいのちを地に踏みにじるようにし私の栄光をちりの中に埋もれさせてください。セラ'),
('JPN', '诗篇', 19, 7, 6, '主よ御怒りをもって立ち上がり私の敵の激しい怒りに対してご自身を高くし私のために目を覚ましてください。あなたはさばきを定められました。'),
('JPN', '诗篇', 19, 7, 7, '国民の群れをあなたの周りに集めその上の高いみくらにお帰りください。'),
('JPN', '诗篇', 19, 7, 8, '主は諸国の民にさばきを行われます。私の義と私にある誠実にしたがって主よ私をさばいてください。'),
('JPN', '诗篇', 19, 7, 9, 'どうか悪しき者の悪が後を絶ちあなたが正しい者を堅く立てられますように。正しい神は心の深みまで調べられます。'),
('JPN', '诗篇', 19, 7, 10, '私の盾は神にあり神は心の直ぐな人を救われます。'),
('JPN', '诗篇', 19, 7, 11, '神は正しい審判者日々憤る神。'),
('JPN', '诗篇', 19, 7, 12, '立ち返らない者には剣を研ぎ弓を張って狙いを定められます。'),
('JPN', '诗篇', 19, 7, 13, 'その者に向かって死の武器を構えその矢を燃える火矢とされます。'),
('JPN', '诗篇', 19, 7, 14, '見よその者は不法を宿し害悪をはらみ偽りを産んでいます。'),
('JPN', '诗篇', 19, 7, 15, '彼は穴を掘ってそれを深くし自分が作った穴に落ち込みます。'),
('JPN', '诗篇', 19, 7, 16, 'その害悪は自分の頭上に戻りその暴虐は自分の脳天に下ります。'),
('JPN', '诗篇', 19, 7, 17, '私は主をほめたたえます。その義にふさわしく。いと高き方主の御名をほめ歌います。'),
('JPN', '诗篇', 19, 8, 1, '主よ私たちの主よあなたの御名は全地にわたりなんと力に満ちていることでしょう。あなたのご威光は天でたたえられています。'),
('JPN', '诗篇', 19, 8, 2, '幼子たち乳飲み子たちの口を通してあなたは御力を打ち立てられました。あなたに敵対する者に応えるため復讐する敵を鎮めるために。'),
('JPN', '诗篇', 19, 8, 3, 'あなたの指のわざであるあなたの天あなたが整えられた月や星を見るに'),
('JPN', '诗篇', 19, 8, 4, '人とは何ものなのでしょう。あなたが心に留められるとは。人の子とはいったい何ものなのでしょう。あなたが顧みてくださるとは。'),
('JPN', '诗篇', 19, 8, 5, 'あなたは人を御使いよりわずかに欠けがあるものとしこれに栄光と誉れの冠をかぶらせてくださいました。'),
('JPN', '诗篇', 19, 8, 6, 'あなたの御手のわざを人に治めさせ万物を彼の足の下に置かれました。'),
('JPN', '诗篇', 19, 8, 7, '羊も牛もすべてまた野の獣も'),
('JPN', '诗篇', 19, 8, 8, '空の鳥海の魚海路を通うものも。'),
('JPN', '诗篇', 19, 8, 9, '主よ私たちの主よあなたの御名は全地にわたりなんと力に満ちていることでしょう。'),
('JPN', '诗篇', 19, 9, 1, '心を尽くして私は主に感謝をささげます。あなたの奇しいみわざのすべてを語り告げます。'),
('JPN', '诗篇', 19, 9, 2, '私はあなたを喜び誇ります。いと高き方よあなたの御名をほめ歌います。'),
('JPN', '诗篇', 19, 9, 3, '私の敵は退くとき御前でつまずきついえます。'),
('JPN', '诗篇', 19, 9, 4, 'あなたが私の正しい訴えを聞かれるからです。義の審判者として王座に着いておられるからです。'),
('JPN', '诗篇', 19, 9, 5, 'あなたは国々を叱り悪しき者を滅ぼし彼らの名をとこしえに消し去られました。'),
('JPN', '诗篇', 19, 9, 6, '敵は絶え果てました。──永遠の廃墟あなたが根こそぎにされた町々──彼らの記憶さえ消え失せました。'),
('JPN', '诗篇', 19, 9, 7, 'しかし主はとこしえに御座に着きさばきのために王座を堅く立てられた。'),
('JPN', '诗篇', 19, 9, 8, '主は義によって世界をさばき公正をもってもろもろの国民をさばかれる。'),
('JPN', '诗篇', 19, 9, 9, '主は虐げられた者の砦苦しみのときの砦。'),
('JPN', '诗篇', 19, 9, 10, '御名を知る者はあなたに拠り頼みます。主よあなたを求める者をあなたはお見捨てになりませんでした。'),
('JPN', '诗篇', 19, 9, 11, '主にほめ歌を歌えシオンに住まうその方に。主のみわざを告げ知らせよ国々の民に。'),
('JPN', '诗篇', 19, 9, 12, '血に報いる方は彼らを心に留め貧しい者の叫びをお忘れにならない。'),
('JPN', '诗篇', 19, 9, 13, '主よ私をあわれんでください。私を憎む者から来る私の苦しみをご覧ください。死の門から私を引き上げてくださる方よ。'),
('JPN', '诗篇', 19, 9, 14, '私はあなたのすべての誉れを語り告げるため娘シオンの城門であなたの救いに歓声をあげます。'),
('JPN', '诗篇', 19, 9, 15, '国々は自分で作った穴に陥り自分で隠した網に足を取られる。'),
('JPN', '诗篇', 19, 9, 16, '主はご自身を知らしめさばきを行われた。悪しき者は自分の手で作った罠にかかった。ヒガヨンセラ'),
('JPN', '诗篇', 19, 9, 17, '悪しき者はよみに帰って行く。神を忘れるあらゆる国々も。'),
('JPN', '诗篇', 19, 9, 18, '貧しい者は決して忘れられることがなく苦しむ者の望みは永遠に失せることがない。'),
('JPN', '诗篇', 19, 9, 19, '主よ立ち上がり人間が勝ち誇らないようにしてください。国々が御前でさばかれるようにしてください。'),
('JPN', '诗篇', 19, 9, 20, '主よ彼らに恐れを起こさせ国々に思い知らせてください。自らが人間にすぎないことを。セラ'),
('JPN', '诗篇', 19, 10, 1, '主よなぜあなたは遠く離れて立ち苦しみのときに身を隠されるのですか。'),
('JPN', '诗篇', 19, 10, 2, '悪しき者は高ぶって苦しむ人に追い迫ります。彼らが自分の企みに捕らえられますように。'),
('JPN', '诗篇', 19, 10, 3, '悪しき者は自分自身の欲望を誇り貪欲な者は主を呪い侮ります。'),
('JPN', '诗篇', 19, 10, 4, '悪しき者は高慢を顔に表し神を求めません。「神はいない。」これが彼の思いのすべてです。'),
('JPN', '诗篇', 19, 10, 5, '彼の道はいつも栄えあなたのさばきは高すぎて彼の目に入りません。敵という敵を彼は吹き飛ばしてしまいます。'),
('JPN', '诗篇', 19, 10, 6, '彼は心の中で言っています。「私は揺るがされることがなく代々にわたってわざわいにあわない。」'),
('JPN', '诗篇', 19, 10, 7, '彼の口は呪いと欺きと虐げに満ち舌の裏にあるのは害悪と不法です。'),
('JPN', '诗篇', 19, 10, 8, '彼は村外れの待ち伏せ場に座り隠れた所で咎なき者を殺します。彼の目は不幸な人をひそかに狙っています。'),
('JPN', '诗篇', 19, 10, 9, '茂みの中の獅子のように隠れ場で待ち伏せます。苦しむ人を捕らえようと待ち伏せ苦しむ人を網にかけて捕らえてしまいます。'),
('JPN', '诗篇', 19, 10, 10, '彼の強さに不幸な人は砕かれ崩れ倒れます。'),
('JPN', '诗篇', 19, 10, 11, '彼は心の中で言っています。「神は忘れているのだ。顔を隠して永久に見ることはないのだ。」'),
('JPN', '诗篇', 19, 10, 12, '主よ立ち上がってください。神よ御手を上げてください。どうか貧しい者を忘れないでください。'),
('JPN', '诗篇', 19, 10, 13, '何のために悪しき者は神を侮るのでしょうか。彼は心の中であなたが追及することはないと言っています。'),
('JPN', '诗篇', 19, 10, 14, 'あなたは見ておられました。労苦と苦痛をじっと見つめておられました。それを御手の中に収めるために。不幸な人はあなたに身をゆだねます。みなしごはあなたがお助けになります。'),
('JPN', '诗篇', 19, 10, 15, '悪しき者と邪悪な者の腕を折りその悪を探し出して一つも残らないようにしてください。'),
('JPN', '诗篇', 19, 10, 16, '主は世々にわたって永遠の王。国々は主の地から滅び失せました。'),
('JPN', '诗篇', 19, 10, 17, '主よあなたは貧しい者たちの願いを聞いてくださいます。あなたは彼らの心を強くし耳を傾けてくださいます。'),
('JPN', '诗篇', 19, 10, 18, 'みなしごと虐げられた者をかばってくださいます。地から生まれた人間がもはや彼らをおびえさせることがないように。'),
('JPN', '诗篇', 19, 11, 1, '主に私は身を避ける。どうしてあなたがたは私のたましいに言うのか。「鳥のように自分の山に飛んで行け。'),
('JPN', '诗篇', 19, 11, 2, 'それ見よ悪者どもが弓を張り弦に矢をつがえ暗がりで心の直ぐな人を射抜こうとしている。'),
('JPN', '诗篇', 19, 11, 3, '拠り所が壊されたら正しい者に何ができるだろうか。」'),
('JPN', '诗篇', 19, 11, 4, '主はその聖なる宮におられる。主はその王座が天にある。その目は見通しそのまぶたは人の子らを調べる。'),
('JPN', '诗篇', 19, 11, 5, '主は正しい者と悪者を調べる。そのみこころは暴虐を好む者を憎む。'),
('JPN', '诗篇', 19, 11, 6, '主は悪者どもの上に網を下す。火と硫黄燃える風が彼らへの杯。'),
('JPN', '诗篇', 19, 11, 7, '主は正しく正義を愛される。直ぐな人は御顔を仰ぎ見る。'),
('JPN', '诗篇', 19, 12, 1, '主よお救いください。敬虔な人は後を絶ち誠実な人は人の子らの中から消え去りました。'),
('JPN', '诗篇', 19, 12, 2, '人は互いにむなしいことを話しへつらいの唇と二心で話します。'),
('JPN', '诗篇', 19, 12, 3, '主がへつらいの唇と傲慢の舌をことごとく断ち切ってくださいますように。'),
('JPN', '诗篇', 19, 12, 4, '彼らはこう言っています。「われらはこの舌で勝つことができる。この唇はわれらのものだ。だれがわれらの主人なのか。」'),
('JPN', '诗篇', 19, 12, 5, '主は言われます。「苦しむ人が踏みにじられ貧しい人が嘆くから今わたしは立ち上がる。わたしは彼をその求める救いに入れよう。」'),
('JPN', '诗篇', 19, 12, 6, '主のことばは混じり気のないことば。土の炉で七度試され純化された銀。'),
('JPN', '诗篇', 19, 12, 7, '主よあなたは彼らを守られます。今の代からとこしえまでも彼らを保たれます。'),
('JPN', '诗篇', 19, 12, 8, '人の子の間で卑しいことがあがめられているときには悪しき者がいたるところで横行します。'),
('JPN', '诗篇', 19, 13, 1, '主よいつまでですか。あなたは私を永久にお忘れになるのですか。いつまで御顔を私からお隠しになるのですか。'),
('JPN', '诗篇', 19, 13, 2, 'いつまで私は自分のたましいのうちで思い悩まなければならないのでしょう。私の心には一日中悲しみがあります。いつまで敵が私の上におごり高ぶるのですか。'),
('JPN', '诗篇', 19, 13, 3, '私に目を注ぎ私に答えてください。私の神主よ。私の目を明るくしてください。私が死の眠りにつかないように。'),
('JPN', '诗篇', 19, 13, 4, '「彼に勝った」と私の敵が言わないように。私がぐらつくことを逆らう者が喜ばないように。'),
('JPN', '诗篇', 19, 13, 5, '私はあなたの恵みに拠り頼みます。私の心はあなたの救いを喜びます。'),
('JPN', '诗篇', 19, 13, 6, '私は主に歌を歌います。主が私に良くしてくださいましたから。'),
('JPN', '诗篇', 19, 14, 1, '愚か者は心の中で「神はいない」と言う。彼らは腐っていて忌まわしいことを行う。善を行う者はいない。'),
('JPN', '诗篇', 19, 14, 2, '主は天から人の子らを見下ろされた。悟る者神を求める者がいるかどうかと。'),
('JPN', '诗篇', 19, 14, 3, 'すべての者が離れて行きだれもかれも無用の者となった。善を行う者はいない。だれ一人いない。'),
('JPN', '诗篇', 19, 14, 4, '不法を行う者はみな知らないのか。彼らはわたしの民を食らいながらパンを食べ主を呼び求めない。'),
('JPN', '诗篇', 19, 14, 5, '見よ彼らは大いに恐れた。神は正しい一族とともにおられるからだ。'),
('JPN', '诗篇', 19, 14, 6, 'おまえたちは苦しむ者の計画を踏みにじろうとするだろう。しかし主が彼の避け所である。'),
('JPN', '诗篇', 19, 14, 7, 'ああイスラエルの救いがシオンから来るように。主が御民を元どおりにされるときヤコブは楽しめ。イスラエルは喜べ。'),
('JPN', '诗篇', 19, 15, 1, '主よだれがあなたの幕屋に宿るのでしょうか。だれがあなたの聖なる山に住むのでしょうか。'),
('JPN', '诗篇', 19, 15, 2, '全き者として歩み義を行い心の中の真実を語る人。'),
('JPN', '诗篇', 19, 15, 3, '舌をもって中傷せず友人に悪を行わず隣人へのそしりを口にしない人。'),
('JPN', '诗篇', 19, 15, 4, 'その目は主に捨てられた者を蔑み主を恐れる者を彼は尊ぶ。損になっても誓ったことは変えない。'),
('JPN', '诗篇', 19, 15, 5, '利息をつけて金を貸すことはせず潔白な人を不利にする賄賂を受け取らない。このように行う人は決して揺るがされない。'),
('JPN', '诗篇', 19, 16, 1, '神よ私をお守りください。私はあなたに身を避けています。'),
('JPN', '诗篇', 19, 16, 2, '私は主に申し上げます。「あなたこそ私の主。私の幸いはあなたのほかにはありません。」'),
('JPN', '诗篇', 19, 16, 3, '地にある聖徒たちには威厳があり私の喜びはすべて彼らの中にあります。'),
('JPN', '诗篇', 19, 16, 4, 'ほかの神に走った者の痛みは増し加わります。私は彼らが献げる血の酒を注がずその名を口にいたしません。'),
('JPN', '诗篇', 19, 16, 5, '主は私への割り当て分また杯。あなたは私の受ける分を堅く保たれます。'),
('JPN', '诗篇', 19, 16, 6, '割り当ての地は定まりました。私の好む所に。実にすばらしい私へのゆずりの地です。'),
('JPN', '诗篇', 19, 16, 7, '私はほめたたえます。助言を下さる主を。実に夜ごとに内なる思いが私を教えます。'),
('JPN', '诗篇', 19, 16, 8, '私はいつも主を前にしています。主が私の右におられるので私は揺るがされることがありません。'),
('JPN', '诗篇', 19, 16, 9, 'それゆえ私の心は喜び私の胸は喜びにあふれます。私の身も安らかに住まいます。'),
('JPN', '诗篇', 19, 16, 10, 'あなたは私のたましいをよみに捨て置かずあなたにある敬虔な者に滅びをお見せにならないからです。'),
('JPN', '诗篇', 19, 16, 11, 'あなたは私にいのちの道を知らせてくださいます。満ち足りた喜びがあなたの御前にあり楽しみがあなたの右にとこしえにあります。'),
('JPN', '诗篇', 19, 17, 1, '主よ聞いてください正しい訴えを。耳に留めてください私の叫びを。耳に入れてください私の祈りを。これらは欺きの唇から出たものではありません。'),
('JPN', '诗篇', 19, 17, 2, 'あなたの御前で私のためのさばきが行われ御目が正しいことに注がれますように。'),
('JPN', '诗篇', 19, 17, 3, 'あなたは私の心を調べ夜私を問いただされました。私を炉で試されましたが何も見つかりません。私は口の過ちを犯さないように心がけました。'),
('JPN', '诗篇', 19, 17, 4, '人としての行いはあなたの唇のことばに従い無法者が行く道を避けました。'),
('JPN', '诗篇', 19, 17, 5, '私の歩みはあなたの道を堅く守り私の足は揺るぎませんでした。'),
('JPN', '诗篇', 19, 17, 6, '神よ私はあなたを呼び求めました。あなたは私に答えてくださるからです。私に耳を傾けて私のことばを聞いてください。'),
('JPN', '诗篇', 19, 17, 7, 'あなたの右の手で奇しい恵みをお示しください。向かい立つ者どもから身を避ける者を救う方。'),
('JPN', '诗篇', 19, 17, 8, '瞳のように私を守り御翼の陰にかくまってください。'),
('JPN', '诗篇', 19, 17, 9, '私を襲う悪しき者から私を取り巻く貪欲な敵から。'),
('JPN', '诗篇', 19, 17, 10, '彼らは鈍い心を固く閉ざしその口をもって高慢に語ります。'),
('JPN', '诗篇', 19, 17, 11, '彼らは私たちの跡をつけ今取り囲み目を据えて地に投げ倒そうとしています。'),
('JPN', '诗篇', 19, 17, 12, 'それはまるでかみ裂くことに飢えた獅子待ち伏せしている若い獅子のようです。'),
('JPN', '诗篇', 19, 17, 13, '主よ立ち上がり彼の前に進み行き打ちのめしてください。あなたの剣で悪しき者から私のたましいを助け出してください。'),
('JPN', '诗篇', 19, 17, 14, '主よ御手をもって人々から相続分が地上のいのちであるこの世の人々から私のたましいを助け出してください。あなたの蓄えで彼らの腹は満たされ子たちは満ち足りその余りをさらにその幼子らに残します。'),
('JPN', '诗篇', 19, 17, 15, 'しかし私は義のうちに御顔を仰ぎ見目覚めるとき御姿に満ち足りるでしょう。'),
('JPN', '诗篇', 19, 18, 1, '彼は言った。わが力なる主よ。私はあなたを慕います。'),
('JPN', '诗篇', 19, 18, 2, '主はわが巌わが砦わが救い主身を避けるわが岩わが神。わが盾わが救いの角わがやぐら。'),
('JPN', '诗篇', 19, 18, 3, 'ほめたたえられる方。この主を呼び求めると私は敵から救われる。'),
('JPN', '诗篇', 19, 18, 4, '死の綱は私を取り巻き滅びの激流は私をおびえさせた。'),
('JPN', '诗篇', 19, 18, 5, 'よみの綱は私を取り囲み死の罠は私に立ち向かった。'),
('JPN', '诗篇', 19, 18, 6, '私は苦しみの中で主を呼び求めわが神に叫び求めた。主はその宮で私の声を聞かれ御前への叫びは御耳に届いた。'),
('JPN', '诗篇', 19, 18, 7, '地は揺るぎ動いた。山々の基も震え揺れた。主がお怒りになったからだ。'),
('JPN', '诗篇', 19, 18, 8, '煙は鼻から立ち上りその口から出る火は貪り食い炭火は主から燃え上がった。'),
('JPN', '诗篇', 19, 18, 9, '主は天を押し曲げて降りて来られた。黒雲をその足の下にして。'),
('JPN', '诗篇', 19, 18, 10, '主はケルビムに乗って飛び風の翼で天翔られた。'),
('JPN', '诗篇', 19, 18, 11, '主は闇を隠れ家とし水の暗闇濃い雲をご自分の周りで仮庵とされた。'),
('JPN', '诗篇', 19, 18, 12, '御前の輝きから密雲を突き抜けて来たもの。それは雹と燃える炭。'),
('JPN', '诗篇', 19, 18, 13, '主は天に雷鳴を響かせいと高き方は御声を発せられた。雹そして燃える炭。'),
('JPN', '诗篇', 19, 18, 14, '主はご自分の矢を放って彼らを散らしすさまじい稲妻を放ってかき乱された。'),
('JPN', '诗篇', 19, 18, 15, 'こうして水の底が現れ地の基があらわにされた。主よあなたのとがめによりあなたの鼻の荒い息吹によって。'),
('JPN', '诗篇', 19, 18, 16, '主はいと高き所から御手を伸ばして私を捕らえ大水から私を引き上げられました。'),
('JPN', '诗篇', 19, 18, 17, '主は力ある敵から私を救い出されました。私を憎む者どもからも。彼らが私より強かったからです。'),
('JPN', '诗篇', 19, 18, 18, '私のわざわいの日に彼らは立ちはだかりました。けれども主は私の支えとなられました。'),
('JPN', '诗篇', 19, 18, 19, '主は私を広いところに導き出し私を助け出してくださいました。主が私を喜びとされたからです。'),
('JPN', '诗篇', 19, 18, 20, '主は私の義にしたがって私に報い手のきよさにしたがって顧みてくださいました。'),
('JPN', '诗篇', 19, 18, 21, '私は主の道を守り私の神に対して悪を行いませんでした。'),
('JPN', '诗篇', 19, 18, 22, '主のすべてのさばきは私の前にあり主のおきてを私は遠ざけませんでした。'),
('JPN', '诗篇', 19, 18, 23, '私は主の前に全き者。自分の咎から身を守ります。'),
('JPN', '诗篇', 19, 18, 24, '主は私の義にしたがって顧みてくださいました。御目の前のこの手のきよさにしたがって。'),
('JPN', '诗篇', 19, 18, 25, 'あなたは恵み深い者には恵み深く全き者には全き方。'),
('JPN', '诗篇', 19, 18, 26, '清い者には清く曲がった者にはねじ曲げる方。'),
('JPN', '诗篇', 19, 18, 27, 'まことにあなたは苦しむ民を救い高ぶる目を低くされます。'),
('JPN', '诗篇', 19, 18, 28, 'まことにあなたは私のともしびをともされます。私の神主は私の闇を照らされます。'),
('JPN', '诗篇', 19, 18, 29, 'あなたによって私は防塞を突き破り私の神によって城壁を跳び越えます。'),
('JPN', '诗篇', 19, 18, 30, '神その道は完全。主のことばは純粋。主はすべて主に身を避ける者の盾。'),
('JPN', '诗篇', 19, 18, 31, '主のほかにだれが神でしょうか。私たちの神を除いてだれが岩でしょうか。'),
('JPN', '诗篇', 19, 18, 32, '神は私に力を帯びさせ私の道を全きものとされます。'),
('JPN', '诗篇', 19, 18, 33, '主は私の足を雌鹿のようにし高い所に立たせてくださいます。'),
('JPN', '诗篇', 19, 18, 34, '戦いのために私の手を鍛え腕が青銅の弓も引けるようにしてくださいます。'),
('JPN', '诗篇', 19, 18, 35, 'あなたは御救いの盾を私に下さいます。あなたの右の手は私を支えあなたの謙遜は私を大きくします。'),
('JPN', '诗篇', 19, 18, 36, 'あなたは私の歩みを大きくし私のくるぶしはゆるみません。'),
('JPN', '诗篇', 19, 18, 37, '私は敵を追ってこれに追いつき絶ち滅ぼすまでは引き返しませんでした。'),
('JPN', '诗篇', 19, 18, 38, '私が彼らを打ち砕いたので彼らは立てず私の足もとに倒れました。'),
('JPN', '诗篇', 19, 18, 39, 'あなたは戦いのために私に力を帯びさせ向かい立つ者を私のもとにひれ伏させました。'),
('JPN', '诗篇', 19, 18, 40, 'あなたは敵が私を憎む者どもが私に背を見せるようにされました。私は彼らを滅ぼしました。'),
('JPN', '诗篇', 19, 18, 41, '彼らが主に叫び求めても救う者はなく答えもありませんでした。'),
('JPN', '诗篇', 19, 18, 42, '風の前のちりのように私は彼らを粉々に砕き道の泥のように除き去りました。'),
('JPN', '诗篇', 19, 18, 43, 'あなたは民の争いから私を助け出し国々のかしらに任じられました。私の知らなかった民が私に仕えます。'),
('JPN', '诗篇', 19, 18, 44, '彼らは耳で聞くとすぐ私に聞き従います。異国の人々は私にへつらいます。'),
('JPN', '诗篇', 19, 18, 45, '異国の人々は打ちしおれ砦から震えて出て来ます。'),
('JPN', '诗篇', 19, 18, 46, '主は生きておられる。ほむべきかなわが岩。あがむべきかなわが救いの神。'),
('JPN', '诗篇', 19, 18, 47, 'この神は私のために復讐する方。諸国の民を私のもとに従わせてくださる。'),
('JPN', '诗篇', 19, 18, 48, '神は敵から私を助け出される方。実にあなたは向かい立つ者から私を引き上げ不法を行う者から救い出してくださいます。'),
('JPN', '诗篇', 19, 18, 49, 'それゆえ主よ私は国々の間であなたをほめたたえます。あなたの御名をほめ歌います。'),
('JPN', '诗篇', 19, 18, 50, '主はご自分の王に救いを増し加え主に油注がれた者ダビデとその裔にとこしえに恵みを施されます。'),
('JPN', '诗篇', 19, 19, 1, '天は神の栄光を語り告げ大空は御手のわざを告げ知らせる。'),
('JPN', '诗篇', 19, 19, 2, '昼は昼へ話を伝え夜は夜へ知識を示す。'),
('JPN', '诗篇', 19, 19, 3, '話しもせず語りもせずその声も聞こえない。'),
('JPN', '诗篇', 19, 19, 4, 'しかしその光芒は全地にそのことばは世界の果てまで届いた。神は天に太陽のために幕屋を設けられた。'),
('JPN', '诗篇', 19, 19, 5, '花婿のように太陽は部屋から出て勇士のように走路を喜び走る。'),
('JPN', '诗篇', 19, 19, 6, '天の果てからそれは昇り天の果てまでそれは巡る。その熱から隠れ得るものは何もない。'),
('JPN', '诗篇', 19, 19, 7, '主のおしえは完全でたましいを生き返らせ主の証しは確かで浅はかな者を賢くする。'),
('JPN', '诗篇', 19, 19, 8, '主の戒めは真っ直ぐで人の心を喜ばせ主の仰せは清らかで人の目を明るくする。'),
('JPN', '诗篇', 19, 19, 9, '主からの恐れはきよくとこしえまでも変わらない。主のさばきはまことでありことごとく正しい。'),
('JPN', '诗篇', 19, 19, 10, 'それらは金よりも多くの純金よりも慕わしく蜜よりも蜜蜂の巣の滴りよりも甘い。'),
('JPN', '诗篇', 19, 19, 11, 'あなたのしもべもそれらにより戒めを受けそれを守れば大きな報いがあります。'),
('JPN', '诗篇', 19, 19, 12, 'だれが自分の過ちを悟ることができるでしょう。どうか隠れた罪から私を解き放ってください。'),
('JPN', '诗篇', 19, 19, 13, 'あなたのしもべを傲慢から守ってください。それらが私を支配しないようにしてください。そのとき私は大きな背きから解き放たれて全き者となるでしょう。'),
('JPN', '诗篇', 19, 19, 14, '私の口のことばと私の心の思いとが御前に受け入れられますように。主よわが岩わが贖い主よ。'),
('JPN', '诗篇', 19, 20, 1, '苦難の日に主があなたにお答えになりますように。ヤコブの神の御名があなたを高く上げますように。'),
('JPN', '诗篇', 19, 20, 2, '主が聖所からあなたに助けを送りシオンからあなたを支えられますように。'),
('JPN', '诗篇', 19, 20, 3, 'あなたの穀物のささげ物をすべて心に留めあなたの全焼のささげ物を受け入れてくださいますように。セラ'),
('JPN', '诗篇', 19, 20, 4, 'あなたの心の望みを主がかなえてくださいますように。あなたのすべての計画を遂げさせてくださいますように。'),
('JPN', '诗篇', 19, 20, 5, '私たちはあなたの勝利を喜び歌い私たちの神の御名により旗を高く掲げます。あなたの願いのすべてを主が遂げさせてくださいますように。'),
('JPN', '诗篇', 19, 20, 6, '今私は知る。主が主に油注がれた者を救ってくださることを。右の御手の救いの御力をもって聖なる天からその者に答えてくださることを。'),
('JPN', '诗篇', 19, 20, 7, 'ある者は戦車をある者は馬を求める。しかし私たちは私たちの神主の御名を呼び求める。'),
('JPN', '诗篇', 19, 20, 8, '彼らは膝をつき倒れた。しかし私たちはまっすぐに立ち上がった。'),
('JPN', '诗篇', 19, 20, 9, '主よ王をお救いください。私たちが呼ぶときに答えてください。'),
('JPN', '诗篇', 19, 21, 1, '主よあなたの御力を王は喜びます。あなたの御救いをどんなに楽しむことでしょう。'),
('JPN', '诗篇', 19, 21, 2, 'あなたは彼の心の望みをかなえ唇の願いを退けられません。セラ'),
('JPN', '诗篇', 19, 21, 3, 'あなたは幸いに至る祝福をもって彼を迎え頭に純金の冠を置かれます。'),
('JPN', '诗篇', 19, 21, 4, 'いのちを彼はあなたに願いあなたは彼にそれをお与えになります。いつまでもとこしえまでも限りなく。'),
('JPN', '诗篇', 19, 21, 5, '御救いによって彼の栄光は大いなるものとなり威厳と威光をあなたは彼の上に置かれます。'),
('JPN', '诗篇', 19, 21, 6, 'あなたはとこしえに彼に祝福を与え御前で喜び楽しませてくださいます。'),
('JPN', '诗篇', 19, 21, 7, '王は主に信頼しているのでいと高き方の恵みにあって揺るぎません。'),
('JPN', '诗篇', 19, 21, 8, 'あなたの御手はすべての敵を見つけ出しあなたの右の手はあなたを憎む者を見つけ出します。'),
('JPN', '诗篇', 19, 21, 9, 'あなたの現れのときあなたは彼らを燃える炉のようにされます。主は御怒りによって彼らを吞み尽くし火は彼らを食い尽くします。'),
('JPN', '诗篇', 19, 21, 10, '地の上から彼らの裔を人の子らの中から彼らの子孫をあなたは滅ぼしてしまわれます。'),
('JPN', '诗篇', 19, 21, 11, '彼らがあなたに対して悪を企て計略をめぐらしても成し遂げられません。'),
('JPN', '诗篇', 19, 21, 12, 'あなたは彼らが背を見せるようにし弓弦を引き彼らの顔を狙われます。'),
('JPN', '诗篇', 19, 21, 13, '主よあなたの御力のゆえにあなたがあがめられますように。大いなる御力を私たちは歌いほめ歌います。'),
('JPN', '诗篇', 19, 22, 1, 'わが神わが神どうして私をお見捨てになったのですか。私を救わず遠く離れておられるのですか。私のうめきのことばにもかかわらず。'),
('JPN', '诗篇', 19, 22, 2, 'わが神昼に私はあなたを呼びます。しかしあなたは答えてくださいません。夜にも私は黙っていられません。'),
('JPN', '诗篇', 19, 22, 3, 'けれどもあなたは聖なる方御座に着いておられる方イスラエルの賛美です。'),
('JPN', '诗篇', 19, 22, 4, 'あなたに私たちの先祖は信頼しました。彼らは信頼しあなたは彼らを助け出されました。'),
('JPN', '诗篇', 19, 22, 5, 'あなたに叫び彼らは助け出されました。あなたに信頼し彼らは恥を見ませんでした。'),
('JPN', '诗篇', 19, 22, 6, 'しかし私は虫けらです。人間ではありません。人のそしりの的民の蔑みの的です。'),
('JPN', '诗篇', 19, 22, 7, '私を見る者はみな私を嘲ります。口をとがらせ頭を振ります。'),
('JPN', '诗篇', 19, 22, 8, '「主に身を任せよ。助け出してもらえばよい。主に救い出してもらえ。彼のお気に入りなのだから。」'),
('JPN', '诗篇', 19, 22, 9, 'まことにあなたは私を母の胎から取り出した方。母の乳房に拠り頼ませた方。'),
('JPN', '诗篇', 19, 22, 10, '生まれる前から私はあなたにゆだねられました。母の胎内にいたときからあなたは私の神です。'),
('JPN', '诗篇', 19, 22, 11, 'どうか私から遠く離れないでください。苦しみが近くにあり助ける者がいないのです。'),
('JPN', '诗篇', 19, 22, 12, '多くの雄牛が私を取り囲みバシャンの猛者どもが私を囲みました。'),
('JPN', '诗篇', 19, 22, 13, '彼らは私に向かって口を開けています。かみ裂く吼えたける獅子のように。'),
('JPN', '诗篇', 19, 22, 14, '水のように私は注ぎ出され骨はみな外れました。心はろうのように私のうちで溶けました。'),
('JPN', '诗篇', 19, 22, 15, '私の力は土器のかけらのように乾ききり舌は上あごに貼り付いています。死のちりの上にあなたは私を置かれます。'),
('JPN', '诗篇', 19, 22, 16, '犬どもが私を取り囲み悪者どもの群れが私を取り巻いて私の手足にかみついたからです。'),
('JPN', '诗篇', 19, 22, 17, '私は自分の骨をみな数えることができます。彼らは目を凝らし私を見ています。'),
('JPN', '诗篇', 19, 22, 18, '彼らは私の衣服を分け合い私の衣をくじ引きにします。'),
('JPN', '诗篇', 19, 22, 19, '主よあなたは離れないでください。私の力よ早く助けに来てください。'),
('JPN', '诗篇', 19, 22, 20, '救い出してください。私のたましいを剣から。私のただ一つのものを犬の手から。'),
('JPN', '诗篇', 19, 22, 21, '救ってください。獅子の口から野牛の角から。あなたは私に答えてくださいました。'),
('JPN', '诗篇', 19, 22, 22, '私はあなたの御名を兄弟たちに語り告げ会衆の中であなたを賛美します。'),
('JPN', '诗篇', 19, 22, 23, '主を恐れる人々よ主を賛美せよ。ヤコブのすべての裔よ主をあがめよ。イスラエルのすべての裔よ主の前におののけ。'),
('JPN', '诗篇', 19, 22, 24, '主は貧しい人の苦しみを蔑まずいとわず御顔を彼から隠すことなく助けを叫び求めたとき聞いてくださった。'),
('JPN', '诗篇', 19, 22, 25, '大いなる会衆の中での私の賛美はあなたからのものです。私は誓いを果たします。主を恐れる人々の前で。'),
('JPN', '诗篇', 19, 22, 26, 'どうか貧しい人々が食べて満ち足り主を求める人々が主を賛美しますように。──あなたがたの心がいつまでも生きるように──'),
('JPN', '诗篇', 19, 22, 27, '地の果てのすべての者が思い起こし主に帰って来ますように。国々のあらゆる部族もあなたの御前にひれ伏しますように。'),
('JPN', '诗篇', 19, 22, 28, '王権は主のもの。主は国々を統べ治めておられます。'),
('JPN', '诗篇', 19, 22, 29, '地の裕福な者はみな食べてひれ伏しちりに下る者もみな主の御前にひざまずきます。自分のたましいを生かすことができない者も。'),
('JPN', '诗篇', 19, 22, 30, '子孫たちは主に仕え主のことが世代を越えて語り告げられます。'),
('JPN', '诗篇', 19, 22, 31, '彼らは来て生まれてくる民に主の義を告げ知らせます。主が義を行われたからです。'),
('JPN', '诗篇', 19, 23, 1, '主は私の羊飼い。私は乏しいことがありません。'),
('JPN', '诗篇', 19, 23, 2, '主は私を緑の牧場に伏させいこいのみぎわに伴われます。'),
('JPN', '诗篇', 19, 23, 3, '主は私のたましいを生き返らせ御名のゆえに私を義の道に導かれます。'),
('JPN', '诗篇', 19, 23, 4, 'たとえ死の陰の谷を歩むとしても私はわざわいを恐れません。あなたがともにおられますから。あなたのむちとあなたの杖それが私の慰めです。'),
('JPN', '诗篇', 19, 23, 5, '私の敵をよそにあなたは私の前に食卓を整え頭に香油を注いでくださいます。私の杯はあふれています。'),
('JPN', '诗篇', 19, 23, 6, 'まことに私のいのちの日の限りいつくしみと恵みが私を追って来るでしょう。私はいつまでも主の家に住まいます。'),
('JPN', '诗篇', 19, 24, 1, '地とそこに満ちているもの世界とその中に住んでいるものそれは主のもの。'),
('JPN', '诗篇', 19, 24, 2, '主が海に地の基を据え川の上にそれを堅く立てられたからだ。'),
('JPN', '诗篇', 19, 24, 3, 'だれが主の山に登り得るのか。だれが聖なる御前に立てるのか。'),
('JPN', '诗篇', 19, 24, 4, '手がきよく心の澄んだ人そのたましいをむなしいものに向けず偽りの誓いをしない人。'),
('JPN', '诗篇', 19, 24, 5, 'その人は主から祝福を受け自分の救いの神から義を受ける。'),
('JPN', '诗篇', 19, 24, 6, 'これこそヤコブの一族。神を求める者たちあなたの御顔を慕い求める人々である。セラ'),
('JPN', '诗篇', 19, 24, 7, '門よおまえたちの頭を上げよ。永遠の戸よ上がれ。栄光の王が入って来られる。'),
('JPN', '诗篇', 19, 24, 8, '栄光の王とはだれか。強く力ある主。戦いに力ある主。'),
('JPN', '诗篇', 19, 24, 9, '門よおまえたちの頭を上げよ。永遠の戸よ上がれ。栄光の王が入って来られる。'),
('JPN', '诗篇', 19, 24, 10, '栄光の王それはだれか。万軍の主この方こそ栄光の王。セラ'),
('JPN', '诗篇', 19, 25, 1, '主よあなたをわがたましいは仰ぎ求めます。'),
('JPN', '诗篇', 19, 25, 2, 'わが神あなたに私は信頼いたします。どうか私が恥を見ないように敵が私に勝ち誇らないようにしてください。'),
('JPN', '诗篇', 19, 25, 3, 'まことにあなたを待ち望む者がだれも恥を見ずゆえなく裏切る者が恥を見ますように。'),
('JPN', '诗篇', 19, 25, 4, '主よあなたの道を私に知らせあなたの進む道を私に教えてください。'),
('JPN', '诗篇', 19, 25, 5, 'あなたの真理に私を導き教えてください。あなたこそ私の救いの神私はあなたを一日中待ち望みます。'),
('JPN', '诗篇', 19, 25, 6, '主よ思い起こしてください。あなたのあわれみと恵みを。それらはとこしえからのものです。'),
('JPN', '诗篇', 19, 25, 7, '私の若いころの罪や背きを思い起こさないでください。あなたの恵みによって私を覚えていてください。主よあなたのいつくしみのゆえに。'),
('JPN', '诗篇', 19, 25, 8, '主はいつくしみ深く正しくあられます。それゆえ罪人に道をお教えになります。'),
('JPN', '诗篇', 19, 25, 9, '主は貧しい者を正義に歩ませ貧しい者にご自分の道をお教えになります。'),
('JPN', '诗篇', 19, 25, 10, '主の道はみな恵みとまことです。主の契約とさとしを守る者には。'),
('JPN', '诗篇', 19, 25, 11, '主よあなたの御名のゆえに私の咎をお赦しください。それは大きいのです。'),
('JPN', '诗篇', 19, 25, 12, '主を恐れる人はだれか。主はその人に選ぶべき道をお教えになる。'),
('JPN', '诗篇', 19, 25, 13, 'その人のたましいは幸せの中に宿りその子孫は地を受け継ぐ。'),
('JPN', '诗篇', 19, 25, 14, '主はご自分を恐れる者と親しく交わりその契約を彼らにお知らせになる。'),
('JPN', '诗篇', 19, 25, 15, '私の目はいつも主に向かう。主が私の足を罠から引き出してくださるから。'),
('JPN', '诗篇', 19, 25, 16, '私に御顔を向け私をあわれんでください。私はひとり苦しんでいます。'),
('JPN', '诗篇', 19, 25, 17, '私の心の苦しみが大きくなりました。どうかこの苦悩から私を引き出してください。'),
('JPN', '诗篇', 19, 25, 18, '私の悩みと労苦を見て私のすべての罪を赦してください。'),
('JPN', '诗篇', 19, 25, 19, 'ご覧ください。私の敵がどんなに多いかを。彼らは不当な憎しみで私を憎んでいます。'),
('JPN', '诗篇', 19, 25, 20, '私のたましいを守り私を救い出してください。私が恥を見ないようにしてください。私はあなたに身を避けます。'),
('JPN', '诗篇', 19, 25, 21, '誠実で直ぐな心で私が保たれますように。私はあなたを待ち望んでいますから。'),
('JPN', '诗篇', 19, 25, 22, '神よイスラエルをそのすべての苦難から贖い出してください。'),
('JPN', '诗篇', 19, 26, 1, '主よ私を弁護してください。私は誠実に歩みよろめくことなく主に信頼しています。'),
('JPN', '诗篇', 19, 26, 2, '主よ私を調べ試みてください。私の心の深みまで精錬してください。'),
('JPN', '诗篇', 19, 26, 3, 'あなたの恵みは私の目の前にありあなたの真理のうちを私は歩み続けました。'),
('JPN', '诗篇', 19, 26, 4, '私は不信実な人とともに座らず偽善者とともに行きません。'),
('JPN', '诗篇', 19, 26, 5, '悪を行う者の集まりを憎み悪しき者とともに座りません。'),
('JPN', '诗篇', 19, 26, 6, '手を洗い自らの潔白を示します。主よ私はあなたの祭壇の周りを歩きます。'),
('JPN', '诗篇', 19, 26, 7, '感謝の声を響き渡らせて語り告げます。あなたの奇しいみわざのすべてを。'),
('JPN', '诗篇', 19, 26, 8, '主よ私は愛します。あなたの住まいのある所あなたの栄光のとどまる所を。'),
('JPN', '诗篇', 19, 26, 9, 'どうか私のたましいを罪人どもとともに私のいのちを人の血を流す者どもとともに取り去らないでください。'),
('JPN', '诗篇', 19, 26, 10, '彼らの手には悪事がありその右の手は賄賂で満ちているのです。'),
('JPN', '诗篇', 19, 26, 11, 'しかし私は誠実に歩みます。私を贖い出してください。あわれんでください。'),
('JPN', '诗篇', 19, 26, 12, '私の足は平らな所に立っています。数々の集いで私は主をほめたたえます。'),
('JPN', '诗篇', 19, 27, 1, '主は私の光私の救い。だれを私は恐れよう。主は私のいのちの砦。だれを私は怖がろう。'),
('JPN', '诗篇', 19, 27, 2, '私の肉を食らおうと悪を行う者が私に襲いかかったとき崩れ落ちたのは私に逆らう者私の敵であった。'),
('JPN', '诗篇', 19, 27, 3, 'たとえ私に対して陣営が張られても私の心は恐れない。たとえ私に対して戦いが起こってもそれにも私は動じない。'),
('JPN', '诗篇', 19, 27, 4, '一つのことを私は主に願った。それを私は求めている。私のいのちの日の限り主の家に住むことを。主の麗しさに目を注ぎその宮で思いを巡らすために。'),
('JPN', '诗篇', 19, 27, 5, 'それは主が苦しみの日に私を隠れ場に隠しその幕屋のひそかな所に私をかくまい岩の上に私を上げてくださるからだ。'),
('JPN', '诗篇', 19, 27, 6, '今私の頭は私を取り囲む敵の上に高く上げられる。私は主の幕屋で喜びのいけにえをささげ主に歌いほめ歌を歌おう。'),
('JPN', '诗篇', 19, 27, 7, '聞いてください主よ。私が呼ぶこの声を。私をあわれみ私に答えてください。'),
('JPN', '诗篇', 19, 27, 8, 'あなたに代わって私の心は言います。「わたしの顔を慕い求めよ」と。主よあなたの御顔を私は慕い求めます。'),
('JPN', '诗篇', 19, 27, 9, 'どうか御顔を私に隠さないでください。あなたのしもべを怒って押しのけないでください。あなたは私の助けです。見放さないでください。見捨てないでください。私の救いの神よ。'),
('JPN', '诗篇', 19, 27, 10, '私の父私の母が私を見捨てるときは主が私を取り上げてくださいます。'),
('JPN', '诗篇', 19, 27, 11, '主よあなたの道を私に教えてください。私を待ち伏せている者どもがいますから私を平らな道に導いてください。'),
('JPN', '诗篇', 19, 27, 12, '私を敵の意のままにさせないでください。偽りの証人どもが私に向かい立ち暴言を吐いているのです。'),
('JPN', '诗篇', 19, 27, 13, 'もしも私が生ける者の地で主のいつくしみを見ると信じていなかったなら──。'),
('JPN', '诗篇', 19, 27, 14, '待ち望め主を。雄々しくあれ。心を強くせよ。待ち望め主を。'),
('JPN', '诗篇', 19, 28, 1, '主よ私はあなたを呼び求めます。わが岩よどうか私に耳を閉ざさないでください。私に沈黙しないでください。私が穴に下る者どもと同じにされないように。'),
('JPN', '诗篇', 19, 28, 2, '私の願いの声を聞いてください。私があなたに助けを叫び求めるとき。私の手をあなたの聖所の奥に向けて上げるとき。'),
('JPN', '诗篇', 19, 28, 3, 'どうか悪者や不法を行う者どもと一緒に私を引いて行かないでください。彼らは隣人と平和を語りながらその心には悪があるのです。'),
('JPN', '诗篇', 19, 28, 4, '彼らの行いとその悪にしたがって彼らに報いてください。その手のわざにしたがって彼らに報いその仕打ちに報復してください。'),
('JPN', '诗篇', 19, 28, 5, '彼らは主のなさることも御手のわざをも悟らないので主は彼らを打ち壊し建て直すことはされません。'),
('JPN', '诗篇', 19, 28, 6, 'ほむべきかな主。主は私の願いの声を聞かれた。'),
('JPN', '诗篇', 19, 28, 7, '主は私の力私の盾。私の心は主に拠り頼み私は助けられた。私の心は喜び躍り私は歌をもって主に感謝しよう。'),
('JPN', '诗篇', 19, 28, 8, '主は彼らの力。主は主に油注がれた者の救いの砦。'),
('JPN', '诗篇', 19, 28, 9, 'どうか御民を救ってください。あなたのゆずりの民を祝福してください。どうか彼らの羊飼いとなっていつまでも彼らを携え導いてください。'),
('JPN', '诗篇', 19, 29, 1, '力ある者の子らよ。主に帰せよ。栄光と力を主に帰せよ。'),
('JPN', '诗篇', 19, 29, 2, '御名の栄光を主に帰せよ。聖なる装いをして主にひれ伏せ。'),
('JPN', '诗篇', 19, 29, 3, '主の声は水の上にあり栄光の神は雷鳴をとどろかせる。主は大水の上におられる。'),
('JPN', '诗篇', 19, 29, 4, '主の声は力強く主の声は威厳がある。'),
('JPN', '诗篇', 19, 29, 5, '主の声は杉の木を引き裂き主はレバノンの杉を打ち砕く。'),
('JPN', '诗篇', 19, 29, 6, 'それらの木々を子牛のようにレバノンとシルヨンを若い野牛のように跳ねさせる。'),
('JPN', '诗篇', 19, 29, 7, '主の声は炎の穂先をひらめかせる。'),
('JPN', '诗篇', 19, 29, 8, '主の声は荒野を揺さぶり主はカデシュの荒野を揺さぶる。'),
('JPN', '诗篇', 19, 29, 9, '主の声は雌鹿をもだえさせ大森林を裸にする。主の宮ではすべてのものが「栄光」と言う。'),
('JPN', '诗篇', 19, 29, 10, '主は大洪水の前から御座に着いておられる。主はとこしえに王座に着いておられる。'),
('JPN', '诗篇', 19, 29, 11, '主はご自分の民に力をお与えになる。主はご自分の民を平安をもって祝福される。'),
('JPN', '诗篇', 19, 30, 1, '主よ私はあなたをあがめます。あなたは私を引き上げ私の敵が喜ばないようにされたからです。'),
('JPN', '诗篇', 19, 30, 2, 'わが神主よ私が叫び求めるとあなたは私を癒やしてくださいました。'),
('JPN', '诗篇', 19, 30, 3, '主よあなたは私のたましいをよみから引き上げ私を生かしてくださいました。私が穴に下って行かないように。'),
('JPN', '诗篇', 19, 30, 4, '主にある敬虔な者たちよ主をほめ歌え。主の聖なる御名に感謝せよ。'),
('JPN', '诗篇', 19, 30, 5, 'まことに御怒りは束の間いのちは恩寵のうちにある。夕暮れには涙が宿っても朝明けには喜びの叫びがある。'),
('JPN', '诗篇', 19, 30, 6, '私は平安のうちに言った。「私は決して揺るがされない」と。'),
('JPN', '诗篇', 19, 30, 7, '主よあなたはご恩寵のうちに私を私の山に堅く立たせてくださいました。あなたが御顔を隠されると私はおじ惑いました。'),
('JPN', '诗篇', 19, 30, 8, '主よあなたを私は呼び求めます。私の主にあわれみを乞います。'),
('JPN', '诗篇', 19, 30, 9, '私が墓に下っても私の血に何の益があるでしょうか。ちりがあなたをほめたたえるでしょうか。あなたのまことを告げるでしょうか。'),
('JPN', '诗篇', 19, 30, 10, '聞いてください主よ。私をあわれんでください主よ。私の助けとなってください。'),
('JPN', '诗篇', 19, 30, 11, 'あなたは私のために嘆きを踊りに変えてくださいました。私の粗布を解き喜びをまとわせてくださいました。'),
('JPN', '诗篇', 19, 30, 12, '私のたましいがあなたをほめ歌い押し黙ることがないために。私の神主よ私はとこしえまでもあなたに感謝します。'),
('JPN', '诗篇', 19, 31, 1, '主よ私はあなたに身を避けています。私が決して恥を見ないようにしてください。あなたの義によって私を助け出してください。'),
('JPN', '诗篇', 19, 31, 2, '私に耳を傾け急いで私を救い出してください。私の力の岩となり強い砦となって救ってください。'),
('JPN', '诗篇', 19, 31, 3, 'あなたこそ私の巌私の砦。あなたの御名のゆえに私を導き私を伴ってください。'),
('JPN', '诗篇', 19, 31, 4, 'あなたは私を狙って隠された網から私を引き出してくださいます。あなたは私の力です。'),
('JPN', '诗篇', 19, 31, 5, '私の霊をあなたの御手にゆだねます。まことの神主よ。あなたは私を贖い出してくださいます。'),
('JPN', '诗篇', 19, 31, 6, '空しい偶像につく者を私は憎みます。この私は主に信頼しています。'),
('JPN', '诗篇', 19, 31, 7, 'あなたの恵みを私は楽しみ喜びます。あなたは私の悩みをご覧になり私のたましいの苦しみをご存じです。'),
('JPN', '诗篇', 19, 31, 8, 'あなたは私を敵の手に引き渡さず私の足を広いところに立たせてくださいました。'),
('JPN', '诗篇', 19, 31, 9, '私をあわれんでください。主よ。私は苦しんでいるのです。私の目は苦悶で衰え果てました。私のたましいも私のからだも。'),
('JPN', '诗篇', 19, 31, 10, '悲しみのうちに私のいのちは尽き嘆きのうちに私の年は果てました。私の咎によって私の力は弱まり私の骨は衰えてしまいました。'),
('JPN', '诗篇', 19, 31, 11, '敵対するすべての者から私はそしられました。わけても私の隣人から。知り合いには恐れられ外で私を見る者は私を避けて離れ去ります。'),
('JPN', '诗篇', 19, 31, 12, '死人のように私は人の心から忘れられ壊れた器のようになりました。'),
('JPN', '诗篇', 19, 31, 13, '私は多くの者がささやくうわさを聞きました。「恐怖が取り囲んでいる」と。彼らは私に対して謀議をめぐらし私のいのちを取ろうと図りました。'),
('JPN', '诗篇', 19, 31, 14, 'しかし主よ私はあなたに信頼します。私は告白します。「あなたこそ私の神です。」'),
('JPN', '诗篇', 19, 31, 15, '私の時は御手の中にあります。私を救い出してください。敵の手から追い迫る者の手から。'),
('JPN', '诗篇', 19, 31, 16, '御顔をしもべの上に照り輝かせてください。あなたの恵みによって私をお救いください。'),
('JPN', '诗篇', 19, 31, 17, '主よ私が恥を見ないようにしてください。私はあなたを呼び求めていますから。悪しき者どもを辱めてください。彼らが黙ってよみへと下るように。'),
('JPN', '诗篇', 19, 31, 18, '偽りの唇を封じてください。それは正しい者に横柄に語っています。高ぶりと蔑みをもって。'),
('JPN', '诗篇', 19, 31, 19, 'なんと大きいのでしょう。あなたのいつくしみは。あなたを恐れる者のためにあなたはそれを蓄えあなたに身を避ける者のために人の子らの目の前でそれを備えられました。'),
('JPN', '诗篇', 19, 31, 20, 'あなたは彼らを人のそしりから御顔の前にひそかにかくまい舌の争いから隠れ場に隠されます。'),
('JPN', '诗篇', 19, 31, 21, '主はほむべきかな。主は堅固な城壁の町の中で私に奇しい恵みを施してくださいました。'),
('JPN', '诗篇', 19, 31, 22, '私はうろたえて言いました。「私はあなたの目の前から断たれたのだ」と。しかし私の願いの声をあなたは聞かれました。私があなたに叫び求めたときに。'),
('JPN', '诗篇', 19, 31, 23, '主を愛せよ。すべて主にある敬虔な者たち。主は誠実な者を保たれるが高ぶる者には厳しく報いをされる。'),
('JPN', '诗篇', 19, 31, 24, '雄々しくあれ。心を強くせよ。すべて主を待ち望む者よ。'),
('JPN', '诗篇', 19, 32, 1, '幸いなことよその背きを赦され罪をおおわれた人は。'),
('JPN', '诗篇', 19, 32, 2, '幸いなことよ主が咎をお認めにならずその霊に欺きがない人は。'),
('JPN', '诗篇', 19, 32, 3, '私が黙っていたとき私の骨は疲れきり私は一日中うめきました。'),
('JPN', '诗篇', 19, 32, 4, '昼も夜も御手が私の上に重くのしかかり骨の髄さえ夏の日照りで乾ききったからです。セラ'),
('JPN', '诗篇', 19, 32, 5, '私は自分の罪をあなたに知らせ自分の咎を隠しませんでした。私は言いました。「私の背きを主に告白しよう」と。するとあなたは私の罪のとがめを赦してくださいました。セラ'),
('JPN', '诗篇', 19, 32, 6, 'それゆえ敬虔な人はみな祈ります。あなたに向かってあなたがおられるうちに。大水は濁流となっても彼のところに届きません。'),
('JPN', '诗篇', 19, 32, 7, 'あなたは私の隠れ場。あなたは苦しみから私を守り救いの歓声で私を囲んでくださいます。セラ'),
('JPN', '诗篇', 19, 32, 8, '私はあなたが行く道であなたを教えあなたを諭そう。あなたに目を留め助言を与えよう。'),
('JPN', '诗篇', 19, 32, 9, 'あなたがたは分別のない馬やらばのようであってはならない。くつわや手綱そうした馬具で強いるのでなければそれらはあなたの近くには来ない。'),
('JPN', '诗篇', 19, 32, 10, '悪しき者は心の痛みが多い。しかし主に信頼する者は恵みがその人を囲んでいる。'),
('JPN', '诗篇', 19, 32, 11, '正しい者たち主を喜び楽しめ。すべて心の直ぐな人たちよ喜びの声をあげよ。'),
('JPN', '诗篇', 19, 33, 1, '正しい者たち主を喜び歌え。賛美は直ぐな人たちにふさわしい。'),
('JPN', '诗篇', 19, 33, 2, '竪琴に合わせて主に感謝せよ。十弦の琴に合わせてほめ歌を歌え。'),
('JPN', '诗篇', 19, 33, 3, '新しい歌を主に歌え。喜びの叫びとともに巧みに弦をかき鳴らせ。'),
('JPN', '诗篇', 19, 33, 4, 'まことに主のことばは真っ直ぐでそのみわざはことごとく真実である。'),
('JPN', '诗篇', 19, 33, 5, '主は正義と公正を愛される。主の恵みで地は満ちている。'),
('JPN', '诗篇', 19, 33, 6, '主のことばによって天は造られた。天の万象もすべて御口の息吹によって。'),
('JPN', '诗篇', 19, 33, 7, '主は海の水をせき止めて集め湧き出る水を倉に納められる。'),
('JPN', '诗篇', 19, 33, 8, '全地よ主を恐れよ。すべて世界に住む者よ主の御前におののけ。'),
('JPN', '诗篇', 19, 33, 9, '主が仰せられるとそのようになり主が命じられるとそれは立つ。'),
('JPN', '诗篇', 19, 33, 10, '主は国々のはかりごとを破りもろもろの民の計画をくじかれる。'),
('JPN', '诗篇', 19, 33, 11, '主のはかられることはとこしえに立ちみこころの計画は代々に続く。'),
('JPN', '诗篇', 19, 33, 12, '幸いなことよ主を自らの神とする国は。神がご自分のゆずりとして選ばれた民は。'),
('JPN', '诗篇', 19, 33, 13, '主は天から目を注ぎ人の子らをすべてご覧になる。'),
('JPN', '诗篇', 19, 33, 14, '御座が据えられた所から地に住むすべての者に目を留められる。'),
('JPN', '诗篇', 19, 33, 15, '主は一人ひとりの心を形造りわざのすべてを読み取る方。'),
('JPN', '诗篇', 19, 33, 16, '王は軍勢の大きさでは救われない。勇者は力の大きさでは救い出されない。'),
('JPN', '诗篇', 19, 33, 17, '軍馬も勝利の頼みにはならず軍勢の大きさも救いにはならない。'),
('JPN', '诗篇', 19, 33, 18, '見よ主の目は主を恐れる者に注がれる。主の恵みを待ち望む者に。'),
('JPN', '诗篇', 19, 33, 19, '彼らのたましいを死から救い出し飢饉のときにも彼らを生かし続けるために。'),
('JPN', '诗篇', 19, 33, 20, '私たちのたましいは主を待ち望む。主は私たちの助け私たちの盾。'),
('JPN', '诗篇', 19, 33, 21, 'まことに私たちの心は主を喜び私たちは聖なる御名に拠り頼む。'),
('JPN', '诗篇', 19, 33, 22, '主よあなたの恵みが私たちの上にありますように。私たちがあなたを待ち望むときに。'),
('JPN', '诗篇', 19, 34, 1, '私はあらゆるときに主をほめたたえる。私の口にはいつも主への賛美がある。'),
('JPN', '诗篇', 19, 34, 2, '私のたましいは主を誇る。貧しい者はそれを聞いて喜ぶ。'),
('JPN', '诗篇', 19, 34, 3, '私とともに主をほめよ。一つになって御名をあがめよう。'),
('JPN', '诗篇', 19, 34, 4, '私が主を求めると主は答えすべての恐怖から私を救い出してくださった。'),
('JPN', '诗篇', 19, 34, 5, '主を仰ぎ見ると彼らは輝いた。彼らの顔は辱められることがない。'),
('JPN', '诗篇', 19, 34, 6, 'この苦しむ者が呼ぶと主は聞かれすべての苦難から救ってくださった。'),
('JPN', '诗篇', 19, 34, 7, '主の使いは主を恐れる者の周りに陣を張り彼らを助け出される。'),
('JPN', '诗篇', 19, 34, 8, '味わい見つめよ。主がいつくしみ深い方であることを。幸いなことよ主に身を避ける人は。'),
('JPN', '诗篇', 19, 34, 9, '主を恐れよ。主の聖徒たちよ。主を恐れる者には乏しいことがないからだ。'),
('JPN', '诗篇', 19, 34, 10, '若い獅子も乏しくなり飢える。しかし主を求める者は良いものに何一つ欠けることがない。'),
('JPN', '诗篇', 19, 34, 11, '来なさい。子たちよ私に聞きなさい。主を恐れることを教えよう。'),
('JPN', '诗篇', 19, 34, 12, 'いのちを喜びとする人はだれか。幸せを見ようと日数の多いことを愛する人は。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '诗篇', 19, 34, 13, 'あなたの舌に悪口を言わせず唇に欺きを語らせるな。'),
('JPN', '诗篇', 19, 34, 14, '悪を離れて善を行い平和を求めそれを追い続けよ。'),
('JPN', '诗篇', 19, 34, 15, '主の目は正しい人たちの上にあり主の耳は彼らの叫びに傾けられる。'),
('JPN', '诗篇', 19, 34, 16, '主の御顔は悪をなす者どもに敵対し主は彼らの記憶を地から消し去られる。'),
('JPN', '诗篇', 19, 34, 17, '苦しむ者が叫ぶと主は聞かれそのすべての苦難から救い出してくださる。'),
('JPN', '诗篇', 19, 34, 18, '主は心の打ち砕かれた者の近くにおられ霊の砕かれた者を救われる。'),
('JPN', '诗篇', 19, 34, 19, '正しい人には苦しみが多い。しかし主はそのすべてから救い出してくださる。'),
('JPN', '诗篇', 19, 34, 20, '主は彼の骨をことごとく守りその一つさえ折られることはない。'),
('JPN', '诗篇', 19, 34, 21, '悪は悪しき者を殺し正しい人を憎む者は責めを負う。'),
('JPN', '诗篇', 19, 34, 22, '主はそのしもべのたましいを贖い出される。主に身を避ける人はだれも責めを負わない。'),
('JPN', '诗篇', 19, 35, 1, '主よ私と争う者と争い私と戦う者と戦ってください。'),
('JPN', '诗篇', 19, 35, 2, '盾と大盾を手に取って私を助けに来てください。'),
('JPN', '诗篇', 19, 35, 3, '槍を抜き私に追い迫る者たちを封じてください。私のたましいに言ってください。「わたしがあなたの救いだ」と。'),
('JPN', '诗篇', 19, 35, 4, '私のいのちを求める者たちが恥を見卑しめられますように。私に対してわざわいを謀る者たちが退き辱めを受けますように。'),
('JPN', '诗篇', 19, 35, 5, '彼らを風の前の籾殻のようにし主の使いが追い散らすようにしてください。'),
('JPN', '诗篇', 19, 35, 6, '彼らの道を暗闇とし滑りやすくし主の使いが彼らを追うようにしてください。'),
('JPN', '诗篇', 19, 35, 7, 'ゆえもなく彼らは隠しました。網を張った穴を私のために。ゆえもなくそれを掘りました。私のたましいのために。'),
('JPN', '诗篇', 19, 35, 8, '思わぬときに滅びが彼を襲いますように。隠した網が彼を捕らえ滅びの中に彼が落ち込みますように。'),
('JPN', '诗篇', 19, 35, 9, '私のたましいは主にあって喜び御救いの中にあって楽しみます。'),
('JPN', '诗篇', 19, 35, 10, '私のすべての骨は言います。「主よだれがあなたのようでしょう。苦しむ者をより強い者から救い苦しむ者貧しい者を略奪者から救う方。」'),
('JPN', '诗篇', 19, 35, 11, '悪意のある証人どもが立ち私が知らないことを私に問います。'),
('JPN', '诗篇', 19, 35, 12, '彼らは悪をもって善に報い私のたましいは見捨てられています。'),
('JPN', '诗篇', 19, 35, 13, 'しかし私は彼らが病のとき粗布をまといました。私は断食してたましいを苦しめ私の祈りは胸の中を行き来していました。'),
('JPN', '诗篇', 19, 35, 14, '私の友や兄弟であるかのように私は足を運び母の喪に服するようにうなだれて泣き悲しみました。'),
('JPN', '诗篇', 19, 35, 15, 'それなのに私がつまずくと彼らは喜んで集まり私の知らない攻撃者が私に向かって集まり休みなく私を中傷しました。'),
('JPN', '诗篇', 19, 35, 16, '嘲りののしる者たちは私の周りで私に向かって歯をむき出しました。'),
('JPN', '诗篇', 19, 35, 17, 'わが主よいつまで眺めておられるのですか。私のたましいを彼らの略奪から私のただ一つのものを若い獅子から奪い返してください。'),
('JPN', '诗篇', 19, 35, 18, '私は大いなる会衆の中であなたに感謝し力強い民の間であなたを賛美します。'),
('JPN', '诗篇', 19, 35, 19, '偽り者の私の敵を私のことで喜ばせないでください。ゆえもなく私を憎む人々が目くばせし合わないようにしてください。'),
('JPN', '诗篇', 19, 35, 20, '彼らは平和を語らず地の平穏な人々に欺きを企むからです。'),
('JPN', '诗篇', 19, 35, 21, '彼らは私に向かって大きく口を開け「あははこの目で見たぞ」と言います。'),
('JPN', '诗篇', 19, 35, 22, '主よあなたはご覧になりました。黙っていないでください。わが主よ私から遠く離れないでください。'),
('JPN', '诗篇', 19, 35, 23, '奮い立ってください。目を覚ましてください。私のさばきのために。わが神わが主よ私の訴えのために。'),
('JPN', '诗篇', 19, 35, 24, 'あなたの義にしたがって私のためにさばきを行ってください。主よわが神よ彼らを私のことで喜ばせないでください。'),
('JPN', '诗篇', 19, 35, 25, '彼らに心のうちで言わせないでください。「あははわれわれの望みどおりだ」と。どうか言わせないでください。「われわれは彼を吞み込んだ」と。'),
('JPN', '诗篇', 19, 35, 26, '私のわざわいを楽しむ者たちがみな恥を見辱めを受けますように。私に向かって高ぶる者が恥と恥辱を身にまといますように。'),
('JPN', '诗篇', 19, 35, 27, '私の義を喜びとする者たちが喜びの声をあげ楽しむようにしてください。彼らがいつもこう言うようにしてください。「主は大いなるかな。ご自分のしもべの平和を喜ばれる方は」と。'),
('JPN', '诗篇', 19, 35, 28, '私の舌は告げ知らせます。あなたの義を。日夜あなたの誉れを。'),
('JPN', '诗篇', 19, 36, 1, '私の心の奥にまで悪しき者の背きのことばが届く。彼の目の前には神に対する恐れがない。'),
('JPN', '诗篇', 19, 36, 2, '彼は自分の判断で自分を偽り自分の咎を見つけてそれを憎む。'),
('JPN', '诗篇', 19, 36, 3, '彼の口のことばは不法と欺き。思慮深くあろうともせず善を行おうともしない。'),
('JPN', '诗篇', 19, 36, 4, '彼は寝床で不法を謀り良くない道に堅く立ち悪を捨てようとしない。'),
('JPN', '诗篇', 19, 36, 5, '主よあなたの恵みは天にありあなたの真実は雲にまで及びます。'),
('JPN', '诗篇', 19, 36, 6, 'あなたの義は高くそびえる山。あなたのさばきは大いなる淵。主よあなたは人や獣を救ってくださいます。'),
('JPN', '诗篇', 19, 36, 7, '神よあなたの恵みはなんと尊いことでしょう。人の子らは御翼の陰に身を避けます。'),
('JPN', '诗篇', 19, 36, 8, '彼らはあなたの家の豊かさに満たされあなたは楽しみの流れで潤してくださいます。'),
('JPN', '诗篇', 19, 36, 9, 'いのちの泉はあなたとともにありあなたの光のうちに私たちは光を見るからです。'),
('JPN', '诗篇', 19, 36, 10, '注いでください。あなたの恵みをあなたを知る者に。あなたの義を心の直ぐな人たちに。'),
('JPN', '诗篇', 19, 36, 11, '高ぶりの足が私に追いつかず悪しき者の手が私を追いやることのないように。'),
('JPN', '诗篇', 19, 36, 12, 'そこでは不法を行う者は倒れ突き倒されて立ち上がれません。'),
('JPN', '诗篇', 19, 37, 1, '悪を行う者に腹を立てるな。不正を行う者にねたみを起こすな。'),
('JPN', '诗篇', 19, 37, 2, '彼らは草のようにたちまちしおれ青草のように枯れるのだから。'),
('JPN', '诗篇', 19, 37, 3, '主に信頼し善を行え。地に住み誠実を養え。'),
('JPN', '诗篇', 19, 37, 4, '主を自らの喜びとせよ。主はあなたの心の願いをかなえてくださる。'),
('JPN', '诗篇', 19, 37, 5, 'あなたの道を主にゆだねよ。主に信頼せよ。主が成し遂げてくださる。'),
('JPN', '诗篇', 19, 37, 6, '主はあなたの義を光のようにあなたの正しさを真昼のように輝かされる。'),
('JPN', '诗篇', 19, 37, 7, '主の前に静まり耐え忍んで主を待て。その道が栄えている者や悪意を遂げようとする者に腹を立てるな。'),
('JPN', '诗篇', 19, 37, 8, '怒ることをやめ憤りを捨てよ。腹を立てるな。それはただ悪への道だ。'),
('JPN', '诗篇', 19, 37, 9, '悪を行う者は断ち切られ主を待ち望む者彼らが地を受け継ぐからだ。'),
('JPN', '诗篇', 19, 37, 10, 'もうしばらくで悪しき者はいなくなる。その居所を調べてもそこにはいない。'),
('JPN', '诗篇', 19, 37, 11, 'しかし柔和な人は地を受け継ぎ豊かな繁栄を自らの喜びとする。'),
('JPN', '诗篇', 19, 37, 12, '悪しき者は正しい人に敵対して事を謀り彼に向かって歯をむき出す。'),
('JPN', '诗篇', 19, 37, 13, '主は悪しき者を笑われる。彼の日が来るのをご覧になるから。'),
('JPN', '诗篇', 19, 37, 14, '悪しき者は剣を抜き弓を引いた。苦しむ人貧しい人を打ち倒し行いの正しい人を切り殺すために。'),
('JPN', '诗篇', 19, 37, 15, '彼らの剣は自分の胸を貫き彼らの弓はへし折られる。'),
('JPN', '诗篇', 19, 37, 16, '一人の正しい人が持つわずかなものは多くの悪しき者が持つ富にまさる。'),
('JPN', '诗篇', 19, 37, 17, '悪しき者の腕はへし折られるが主は正しい人を支えられるからだ。'),
('JPN', '诗篇', 19, 37, 18, '主は全き人の日々を知っておられ彼らのゆずりは永久に続く。'),
('JPN', '诗篇', 19, 37, 19, '彼らはわざわいのときにも恥を見ず飢饉のときにも満ち足りる。'),
('JPN', '诗篇', 19, 37, 20, 'しかし悪しき者は滅びる。主の敵は牧場の青草のようだ。彼らは消え失せる。煙となって消え失せる。'),
('JPN', '诗篇', 19, 37, 21, '悪しき者は借りるが返さない。正しい人は情け深く人に施す。'),
('JPN', '诗篇', 19, 37, 22, '主に祝福された人は地を受け継ぎ主にのろわれた者は断ち切られる。'),
('JPN', '诗篇', 19, 37, 23, '主によって人の歩みは確かにされる。主はその人の道を喜ばれる。'),
('JPN', '诗篇', 19, 37, 24, 'その人は転んでも倒れ伏すことはない。主がその人の腕を支えておられるからだ。'),
('JPN', '诗篇', 19, 37, 25, '若かったころも年老いた今も私は見たことがない。正しい人が見捨てられることを。その子孫が食べ物を乞うことを。'),
('JPN', '诗篇', 19, 37, 26, 'その人はいつも情け深く人に貸す。その子孫は祝福を得る。'),
('JPN', '诗篇', 19, 37, 27, '悪を離れて善を行え。いつまでも地に住め。'),
('JPN', '诗篇', 19, 37, 28, 'まことに主は義を愛し主にある敬虔な人をお見捨てにならない。彼らは永遠に保たれるが悪しき者どもの子孫は断ち切られる。'),
('JPN', '诗篇', 19, 37, 29, '正しい人は地を受け継ぎいつまでもそこに住む。'),
('JPN', '诗篇', 19, 37, 30, '正しい人の口は知恵を語りその舌は義を告げる。'),
('JPN', '诗篇', 19, 37, 31, 'その心には彼の神のみおしえがあり彼の歩みはよろけることがない。'),
('JPN', '诗篇', 19, 37, 32, '悪しき者は正しい人を待ち伏せ彼を殺そうとする。'),
('JPN', '诗篇', 19, 37, 33, '主は悪しき者の手の中に彼を捨て置かずさばきのときにも彼を不義に定めない。'),
('JPN', '诗篇', 19, 37, 34, '主を待ち望め。主の道を守れ。主はあなたを高く上げ地を受け継がせてくださる。あなたは悪しき者どもが断ち切られるのを見る。'),
('JPN', '诗篇', 19, 37, 35, '私は悪しき者の横暴を見た。彼は野生の木のようにはびこっていた。'),
('JPN', '诗篇', 19, 37, 36, 'だが彼は過ぎ去った。見よ彼はもういない。私は捜したが見つからなかった。'),
('JPN', '诗篇', 19, 37, 37, '全き人に目を留め直ぐな人を見よ。平和の人には未来がある。'),
('JPN', '诗篇', 19, 37, 38, 'しかし背く者はことごとく滅ぼされ悪しき者どもの未来は断ち切られる。'),
('JPN', '诗篇', 19, 37, 39, '正しい人の救いは主から来る。苦難のときの彼らの砦から。'),
('JPN', '诗篇', 19, 37, 40, '主は彼らを助け解き放たれる。悪しき者どもから解き放ち彼らを救われる。彼らが主に身を避けているからだ。'),
('JPN', '诗篇', 19, 38, 1, '主よあなたの激しい怒りで私を責めないでください。あなたの大いなる憤りで私を懲らしめないでください。'),
('JPN', '诗篇', 19, 38, 2, 'あなたの矢が私に突き刺さり御手が私に激しく下りました。'),
('JPN', '诗篇', 19, 38, 3, 'あなたの憤りのため私の肉には完全なところがなく私の罪のゆえ私の骨には健全なところがありません。'),
('JPN', '诗篇', 19, 38, 4, '私の咎が頭を越えるほどになり重荷となって担いきれません。'),
('JPN', '诗篇', 19, 38, 5, '私の傷は悪臭を放って腐り果てました。それは私の愚かさのためです。'),
('JPN', '诗篇', 19, 38, 6, '私は身をかがめ深くうなだれ一日中嘆いて歩き回ります。'),
('JPN', '诗篇', 19, 38, 7, '私の腰は火傷でおおい尽くされ私の肉にはどこにも完全なところがありません。'),
('JPN', '诗篇', 19, 38, 8, '私は衰え果て砕き尽くされ心もだえてほえ叫んでいます。'),
('JPN', '诗篇', 19, 38, 9, '主よ私の願いはすべてあなたの御前にあり私の嘆きはあなたに隠れてはいません。'),
('JPN', '诗篇', 19, 38, 10, '私の胸は激しく鼓動し私の力は私を見捨て目の光さえも私から失せてしまいました。'),
('JPN', '诗篇', 19, 38, 11, '愛する者や私の友も私の病を避けて立ち近親の者でさえ遠く離れて立っています。'),
('JPN', '诗篇', 19, 38, 12, '私のいのちを求める者は罠を仕掛け私のわざわいを願い求める者は私の破滅を告げ絶えず欺くことを語っています。'),
('JPN', '诗篇', 19, 38, 13, 'しかし私は聞きません。聞こえない人のように。口を開きません。話せない人のように。'),
('JPN', '诗篇', 19, 38, 14, 'まるで私は耳が聞こえず口で争わない人のようです。'),
('JPN', '诗篇', 19, 38, 15, 'まことに主よあなたを私は待ち望んでいます。わが神主よあなたが私に答えてくださいます。'),
('JPN', '诗篇', 19, 38, 16, '私は思いました。彼らが私のことで喜ぶのではないか。私の足がよろけるとき私に対して高ぶるのではないかと。'),
('JPN', '诗篇', 19, 38, 17, '私はつまずき倒れそうで痛みが絶えずともにあります。'),
('JPN', '诗篇', 19, 38, 18, '私は自分の咎を言い表します。自分の罪で不安なのです。'),
('JPN', '诗篇', 19, 38, 19, '私の敵は活気に満ちて強く私を憎む偽り者が多くいます。'),
('JPN', '诗篇', 19, 38, 20, '悪をもって善に報いる者どもは私が善を追い求めると私をなじります。'),
('JPN', '诗篇', 19, 38, 21, '主よ私を見捨てないでください。わが神よ私から遠く離れないでください。'),
('JPN', '诗篇', 19, 38, 22, '急いで私を助けてください。主よ私の救いよ。'),
('JPN', '诗篇', 19, 39, 1, '私は言った。私は自分の道に気をつけよう。私が舌で罪を犯さないように。口に口輪をはめておこう。悪しき者が私の前にいる間は。'),
('JPN', '诗篇', 19, 39, 2, '私はひたすら黙っていた。良いことにさえ沈黙した。そのため私の痛みは激しくなった。'),
('JPN', '诗篇', 19, 39, 3, '心は私のうちで熱くなりうめきとともに火が燃え上がった。そこで私は自分の舌で言った。'),
('JPN', '诗篇', 19, 39, 4, '主よお知らせください。私の終わり私の齢がどれだけなのか。私がいかにはかないかを知ることができるように。'),
('JPN', '诗篇', 19, 39, 5, 'ご覧ください。あなたは私の日数を手幅ほどにされました。あなたの御前では私の一生はないも同然です。人はみなしっかり立ってはいても実に空しいかぎりです。セラ'),
('JPN', '诗篇', 19, 39, 6, 'まことに人は幻のように歩き回りまことに空しく立ち騒ぎます。人は蓄えるがだれのものになるのか知りません。'),
('JPN', '诗篇', 19, 39, 7, '主よ今私は何を待ち望みましょう。私の望みそれはあなたです。'),
('JPN', '诗篇', 19, 39, 8, '私のすべての背きから私を助け出してください。私を愚か者のそしりの的としないでください。'),
('JPN', '诗篇', 19, 39, 9, '私は黙し口を開きません。あなたがそうなさったからです。'),
('JPN', '诗篇', 19, 39, 10, 'どうかあなたのむちを取り去ってください。あなたの手に打たれて私は衰え果てました。'),
('JPN', '诗篇', 19, 39, 11, 'あなたは不義を責めて人を懲らしめシミが食うように人の欲するものをなくされます。実に人はみな空しいものです。セラ'),
('JPN', '诗篇', 19, 39, 12, '主よ私の祈りを聞いてください。助けを求める叫びに耳を傾けてください。私の涙に黙っていないでください。私はあなたとともにいる旅人すべての先祖のように寄留の者なのです。'),
('JPN', '诗篇', 19, 39, 13, '私を見つめないでください。私が朗らかになれるようにしてください。私が去っていなくなる前に。'),
('JPN', '诗篇', 19, 40, 1, '私は切に主を待ち望んだ。主は私に耳を傾け助けを求める叫びを聞いてくださった。'),
('JPN', '诗篇', 19, 40, 2, '滅びの穴から泥沼から主は私を引き上げてくださった。私の足を巌に立たせ私の歩みを確かにされた。'),
('JPN', '诗篇', 19, 40, 3, '主はこの口に授けてくださった。新しい歌を私たちの神への賛美を。多くの者は見て恐れ主に信頼するだろう。'),
('JPN', '诗篇', 19, 40, 4, '幸いなことよ主に信頼を置き高ぶる者や偽りに傾く者たちの方を向かない人。'),
('JPN', '诗篇', 19, 40, 5, 'わが神主よなんと多いことでしょう。あなたがなさった奇しいみわざと私たちへの計らいは。あなたに並ぶ者はありません。語ろうとしても告げようとしてもそれはあまりに多くて数えきれません。'),
('JPN', '诗篇', 19, 40, 6, 'あなたはいけにえや穀物のささげ物をお喜びにはなりませんでした。あなたは私の耳を開いてくださいました。全焼のささげ物や罪のきよめのささげ物をあなたはお求めになりませんでした。'),
('JPN', '诗篇', 19, 40, 7, 'そのとき私は申し上げました。「今私はここに来ております。巻物の書に私のことが書いてあります。'),
('JPN', '诗篇', 19, 40, 8, 'わが神よ私はあなたのみこころを行うことを喜びとします。あなたのみおしえは私の心のうちにあります。」'),
('JPN', '诗篇', 19, 40, 9, '私は大いなる会衆の中で義を喜び知らせます。ご覧ください。私は唇を押さえません。主よあなたはご存じです。'),
('JPN', '诗篇', 19, 40, 10, '私はあなたの義を心の中におおい隠さずあなたの真実とあなたの救いを言い表します。私はあなたの恵みとあなたのまことを大いなる会衆に隠しません。'),
('JPN', '诗篇', 19, 40, 11, '主よあなたは私にあわれみを惜しまないでください。あなたの恵みとあなたのまことが絶えず私を見守るようにしてください。'),
('JPN', '诗篇', 19, 40, 12, '数えきれないわざわいが私を取り囲んでいるのです。私の咎が襲いかかり私は何も見ることができません。それは私の髪の毛よりも多く私の心も私を見捨てました。'),
('JPN', '诗篇', 19, 40, 13, '主よみこころによって私を救い出してください。主よ急いで私を助けてください。'),
('JPN', '诗篇', 19, 40, 14, '私のいのちを求め滅ぼそうとする者たちがことごとく恥を見辱められますように。私のわざわいを喜ぶ者たちが退き卑しめられますように。'),
('JPN', '诗篇', 19, 40, 15, '私を「あはは」とあざ笑う者どもが自らの恥に啞然としますように。'),
('JPN', '诗篇', 19, 40, 16, 'あなたを慕い求める人たちがみなあなたにあって楽しみ喜びますように。あなたの救いを愛する人たちが「主は大いなる方」といつも言いますように。'),
('JPN', '诗篇', 19, 40, 17, '私は苦しむ者貧しい者です。主が私を顧みてくださいますように。あなたは私の助け私を救い出す方。わが神よ遅れないでください。'),
('JPN', '诗篇', 19, 41, 1, '幸いなことよ弱っている者に心を配る人は。わざわいの日に主はその人を助け出される。'),
('JPN', '诗篇', 19, 41, 2, '主は彼を見守り彼を生かし地上で幸せな者とされる。どうか彼を敵の意のままにさせないでください。'),
('JPN', '诗篇', 19, 41, 3, '主が病の床で彼を支えられますように。彼が病むとき寝床から起き上がらせてください。'),
('JPN', '诗篇', 19, 41, 4, '私は申し上げます。「主よあわれんでください。私のたましいを癒やしてください。私はあなたの前に罪ある者ですから。」'),
('JPN', '诗篇', 19, 41, 5, '私の敵は私の悪口を言います。「いつ彼は死にその名は消え去るのだろうか。」'),
('JPN', '诗篇', 19, 41, 6, '人が見舞いに来てもその人は噓を言い心のうちでは悪意を蓄え外に出てはそれを言いふらします。'),
('JPN', '诗篇', 19, 41, 7, '私を憎む者はみな私についてともにささやき私に対して悪を企みます。'),
('JPN', '诗篇', 19, 41, 8, '「邪悪なものが彼に取りついている。彼が床についたからにはもう二度と起き上がれまい。」'),
('JPN', '诗篇', 19, 41, 9, '私が信頼した親しい友が私のパンを食べている者までが私に向かってかかとを上げます。'),
('JPN', '诗篇', 19, 41, 10, 'しかし主よ。あなたは私をあわれみ立ち上がらせてください。そうすれば彼らに報いを返せます。'),
('JPN', '诗篇', 19, 41, 11, 'このことによって私は知ります。あなたが私を喜んでおられることを。敵は私に向かって勝ちどきをあげません。'),
('JPN', '诗篇', 19, 41, 12, '私の誠実さゆえに私を強く支えてください。いつまでもあなたの御前に立たせてください。'),
('JPN', '诗篇', 19, 41, 13, 'ほむべきかなイスラエルの神主。とこしえからとこしえまで。アーメン、アーメン。'),
('JPN', '诗篇', 19, 42, 1, '鹿が谷川の流れを慕いあえぐように神よ私のたましいはあなたを慕いあえぎます。'),
('JPN', '诗篇', 19, 42, 2, '私のたましいは神を生ける神を求めて渇いています。いつになれば私は行って神の御前に出られるのでしょうか。'),
('JPN', '诗篇', 19, 42, 3, '昼も夜も私の涙が私の食べ物でした。「おまえの神はどこにいるのか」と人が絶えず私に言う間。'),
('JPN', '诗篇', 19, 42, 4, '私は自分のうちで思い起こし私のたましいを注ぎ出しています。私が祭りを祝う群衆とともに喜びと感謝の声をあげてあの群れと一緒に神の家へとゆっくり歩んで行ったことなどを。'),
('JPN', '诗篇', 19, 42, 5, 'わがたましいよなぜおまえはうなだれているのか。私のうちで思い乱れているのか。神を待ち望め。私はなおも神をほめたたえる。御顔の救いを。'),
('JPN', '诗篇', 19, 42, 6, '私の神よ私のたましいは私のうちでうなだれています。それゆえ私はヨルダンとヘルモンの地からまたミツアルの山からあなたを思い起こします。'),
('JPN', '诗篇', 19, 42, 7, 'あなたの大滝のとどろきに淵が淵を呼び起こしあなたの波あなたの大波はみな私の上を越えて行きました。'),
('JPN', '诗篇', 19, 42, 8, '昼には主が恵みを下さり夜には主の歌が私とともにあります。私のいのちなる神への祈りが。'),
('JPN', '诗篇', 19, 42, 9, '私はわが巌なる神に申し上げます。「なぜあなたは私をお忘れになったのですか。なぜ私は敵の虐げに嘆いて歩き回るのですか。」'),
('JPN', '诗篇', 19, 42, 10, '私に敵対する者たちは私の骨を砕くほどに私をそしり絶えず私に言っています。「おまえの神はどこにいるのか」と。'),
('JPN', '诗篇', 19, 42, 11, 'わがたましいよなぜおまえはうなだれているのか。なぜ私のうちで思い乱れているのか。神を待ち望め。私はなおも神をほめたたえる。私の救い私の神を。'),
('JPN', '诗篇', 19, 43, 1, '神よ私のためにさばいてください。私の訴えを取り上げ不敬虔な民の言い分を退けてください。欺きと不正の人から私を助け出してください。'),
('JPN', '诗篇', 19, 43, 2, 'あなたは私の力の神であられるからです。なぜあなたは私を退けられたのですか。なぜ私は敵の虐げに嘆いて歩き回るのですか。'),
('JPN', '诗篇', 19, 43, 3, 'どうかあなたの光とまことを送りそれらが私を導くようにしてください。あなたの聖なる山あなたの住まいへとそれらが私を連れて行きますように。'),
('JPN', '诗篇', 19, 43, 4, 'こうして私は神の祭壇に私の最も喜びとする神のみもとに行き竪琴に合わせてあなたをほめたたえます。神よ私の神よ。'),
('JPN', '诗篇', 19, 43, 5, 'わがたましいよなぜおまえはうなだれているのか。なぜ私のうちで思い乱れているのか。神を待ち望め。私はなおも神をほめたたえる。私の救い私の神を。'),
('JPN', '诗篇', 19, 44, 1, '神よ私たちはこの耳で聞きました。先祖たちが語ってくれました。あなたが彼らの時代昔になさったみわざを。'),
('JPN', '诗篇', 19, 44, 2, 'あなたは御手をもって異邦の民を追い払いそこに先祖たちを植えられました。もろもろの国民にわざわいを下しそこに先祖たちを送り込まれました。'),
('JPN', '诗篇', 19, 44, 3, '自分の剣によって彼らは地を得たのではなく自分の腕が彼らを救ったのでもありません。ただあなたの右の手あなたの御腕あなたの御顔の光がそうしたのです。あなたが彼らを愛されたからです。'),
('JPN', '诗篇', 19, 44, 4, '神よあなたこそ私の王です。ヤコブの勝利を命じてください。'),
('JPN', '诗篇', 19, 44, 5, 'あなたによって私たちは敵を押し返し御名によって向かい立つ者どもを踏みつけます。'),
('JPN', '诗篇', 19, 44, 6, '私の弓に私は頼りません。私の剣も私を救いません。'),
('JPN', '诗篇', 19, 44, 7, 'しかしあなたは私たちを敵から救い私たちを憎む者どもを辱められます。'),
('JPN', '诗篇', 19, 44, 8, '神にあって私たちはいつも誇ります。あなたの御名をとこしえにほめたたえます。セラ'),
('JPN', '诗篇', 19, 44, 9, 'それなのにあなたは私たちを退け卑しめられました。あなたはもはや私たちの軍勢とともに出陣なさいません。'),
('JPN', '诗篇', 19, 44, 10, 'あなたは私たちを敵から退かせ私たちを憎む者どもは思うままに略奪しました。'),
('JPN', '诗篇', 19, 44, 11, 'あなたは私たちを餌食となる羊のようにし国々の間に散らされました。'),
('JPN', '诗篇', 19, 44, 12, 'ご自分の民を安く売り渡しその代価で何の利益も得ませんでした。'),
('JPN', '诗篇', 19, 44, 13, 'あなたは私たちを隣人のそしりの的とし周りの者の嘲りとし笑いぐさとされます。'),
('JPN', '诗篇', 19, 44, 14, '私たちを国々の間で物笑いの種としもろもろの民の間で笑いものとされるのです。'),
('JPN', '诗篇', 19, 44, 15, '私の前には絶えず辱めがあり恥が私の顔をおおってしまいました。'),
('JPN', '诗篇', 19, 44, 16, 'それはそしる者とののしる者の声のゆえ敵と復讐する者のゆえでした。'),
('JPN', '诗篇', 19, 44, 17, 'これらすべてが私たちを襲いました。しかし私たちはあなたを忘れずあなたの契約を無にしませんでした。'),
('JPN', '诗篇', 19, 44, 18, '私たちの心はたじろがず私たちの歩みはあなたの道からそれませんでした。'),
('JPN', '诗篇', 19, 44, 19, 'あなたはジャッカルの住みかで私たちを砕き死の陰で私たちをおおわれたのです。'),
('JPN', '诗篇', 19, 44, 20, 'もし私たちが自分たちの神の御名を忘れほかの神に向かって手を伸べ広げたなら'),
('JPN', '诗篇', 19, 44, 21, '神はそれを探り出されないでしょうか。神こそ心の秘密を知っておられるからです。'),
('JPN', '诗篇', 19, 44, 22, 'あなたのために私たちは休みなく殺され屠られる羊と見なされています。'),
('JPN', '诗篇', 19, 44, 23, '起きてください。主よなぜ眠っておられるのですか。目を覚ましてください。いつまでも拒まないでください。'),
('JPN', '诗篇', 19, 44, 24, 'なぜ御顔を隠されるのですか。私たちの苦しみと虐げをお忘れになるのですか。'),
('JPN', '诗篇', 19, 44, 25, '私たちのたましいはちりに伏し私たちの腹は地についています。'),
('JPN', '诗篇', 19, 44, 26, '立ち上がって私たちをお助けください。御恵みのゆえに私たちを贖い出してください。'),
('JPN', '诗篇', 19, 45, 1, 'すばらしいことばで私の心は沸き立っている。王のために私が作った詩を私は歌おう。私の舌は巧みな書記の筆。'),
('JPN', '诗篇', 19, 45, 2, 'あなたは人の子らにまさって麗しい。あなたの唇からは優しさが流れ出る。神がとこしえにあなたを祝福しておられるからだ。'),
('JPN', '诗篇', 19, 45, 3, '勇士よあなたの剣を腰に帯びよ。あなたの威厳とあなたの威光を。'),
('JPN', '诗篇', 19, 45, 4, 'あなたの威光は勝利のうちに進み行け。真理と柔和と義のゆえにあなたの右の手はあなたに教えよ。恐るべきわざを。'),
('JPN', '诗篇', 19, 45, 5, 'あなたの矢は鋭い。国々の民はあなたのもとに倒れ王の敵は気を失う。'),
('JPN', '诗篇', 19, 45, 6, '神よあなたの王座は世々限りなくあなたの王国の杖は公平の杖。'),
('JPN', '诗篇', 19, 45, 7, 'あなたは義を愛し悪を憎む。それゆえ神よあなたの神は喜びの油をあなたに注がれた。あなたに並ぶだれにもまして。'),
('JPN', '诗篇', 19, 45, 8, 'あなたの服はみな没薬アロエシナモンの香りを放ち象牙の宮殿に流れる弦の調べはあなたを喜ばせた。'),
('JPN', '诗篇', 19, 45, 9, 'あなたの貴婦人たちの中には諸国の王の娘らもいて王妃はあなたの右に立つ。オフィルの金を身に着けて。'),
('JPN', '诗篇', 19, 45, 10, '娘よ聞け。心して耳を傾けよ。あなたの民とあなたの父の家を忘れよ。'),
('JPN', '诗篇', 19, 45, 11, 'そうすれば王はあなたの美しさを慕うだろう。彼こそあなたの主。彼の前にひれ伏せ。'),
('JPN', '诗篇', 19, 45, 12, '娘ツロは贈り物を携え民のうちの富む者もあなたの好意を求めて来る。'),
('JPN', '诗篇', 19, 45, 13, '王の娘は奥にいて栄華を極めその衣には黄金が織り合わされている。'),
('JPN', '诗篇', 19, 45, 14, '彼女はあや織物をまとい王の前に導かれる。おとめたちが彼女の後に付き従い彼女はあなたのもとに連れて来られる。'),
('JPN', '诗篇', 19, 45, 15, '喜びと楽しみをもって彼女たちは導かれ王の宮殿に入って行く。'),
('JPN', '诗篇', 19, 45, 16, 'あなたの息子らがあなたの父祖に代わりあなたは彼らを全地の君主に任じる。'),
('JPN', '诗篇', 19, 45, 17, '私はあなたの名を代々にわたって呼び求めよう。それゆえ国々の民は世々限りなくあなたをほめたたえよう。'),
('JPN', '诗篇', 19, 46, 1, '神はわれらの避け所また力。苦しむときそこにある強き助け。'),
('JPN', '诗篇', 19, 46, 2, 'それゆえわれらは恐れない。たとえ地が変わり山々が揺れ海のただ中に移るとも。'),
('JPN', '诗篇', 19, 46, 3, 'たとえその水が立ち騒ぎ泡立ってもその水かさが増し山々が揺れ動いても。セラ'),
('JPN', '诗篇', 19, 46, 4, '川がある。その豊かな流れは神の都を喜ばせる。いと高き方のおられるその聖なる所を。'),
('JPN', '诗篇', 19, 46, 5, '神はそのただ中におられその都は揺るがない。神は朝明けまでにこれを助けられる。'),
('JPN', '诗篇', 19, 46, 6, '国々は立ち騒ぎ諸方の王国は揺らぐ。神が御声を発せられると地は溶ける。'),
('JPN', '诗篇', 19, 46, 7, '万軍の主はわれらとともにおられる。ヤコブの神はわれらの砦である。セラ'),
('JPN', '诗篇', 19, 46, 8, '来て見よ。主のみわざを。主は地で恐るべきことをなされた。'),
('JPN', '诗篇', 19, 46, 9, '主は地の果てまでも戦いをやめさせる。弓をへし折り槍を断ち切り戦車を火で焼かれる。'),
('JPN', '诗篇', 19, 46, 10, '「やめよ。知れ。わたしこそ神。わたしは国々の間であがめられ地の上であがめられる。」'),
('JPN', '诗篇', 19, 46, 11, '万軍の主はわれらとともにおられる。ヤコブの神はわれらの砦である。セラ'),
('JPN', '诗篇', 19, 47, 1, 'すべての国々の民よ手をたたけ。喜びの声をもって神に大声で叫べ。'),
('JPN', '诗篇', 19, 47, 2, 'まことにいと高き方主は恐るべき方。全地を治める大いなる王。'),
('JPN', '诗篇', 19, 47, 3, '国々の民を私たちのもとにもろもろの国民を私たちの足もとに従わせられる。'),
('JPN', '诗篇', 19, 47, 4, '主は私たちのために選んでくださる。私たちの受け継ぐ地を。主が愛されるヤコブの誉れを。セラ'),
('JPN', '诗篇', 19, 47, 5, '神は上られる。喜びの叫びの中を。主は行かれる。角笛の音の中を。'),
('JPN', '诗篇', 19, 47, 6, 'ほめ歌を歌え。神にほめ歌を歌え。ほめ歌を歌え。私たちの王にほめ歌を歌え。'),
('JPN', '诗篇', 19, 47, 7, 'まことに神は全地の王。ことばの限りほめ歌を歌え。'),
('JPN', '诗篇', 19, 47, 8, '神は国々を統べ治めておられる。神はその聖なる王座に着いておられる。'),
('JPN', '诗篇', 19, 47, 9, '国々の民の高貴な者たちは集められた。アブラハムの神の民として。まことに地の盾は神のもの。神は大いにあがめられる方。'),
('JPN', '诗篇', 19, 48, 1, '主は大いなる方。大いにほめたたえられるべき方。主の聖なる山私たちの神の都で。'),
('JPN', '诗篇', 19, 48, 2, '高嶺の麗しさは全地の喜び。北の端なるシオンの山は大王の都。'),
('JPN', '诗篇', 19, 48, 3, '神はその都の宮殿でご自分を砦として示された。'),
('JPN', '诗篇', 19, 48, 4, '見よ王たちは集ってともどもにやって来た。'),
('JPN', '诗篇', 19, 48, 5, '彼らは見ると驚きおじ惑い慌てた。'),
('JPN', '诗篇', 19, 48, 6, 'その場で震えが彼らをとらえた。子を産むときのような激しい痛みが。'),
('JPN', '诗篇', 19, 48, 7, '東風によってあなたはタルシシュの船を砕かれる。'),
('JPN', '诗篇', 19, 48, 8, '私たちは聞いたとおりを見た。万軍の主の都私たちの神の都で。神は都をとこしえに堅く立てられる。セラ'),
('JPN', '诗篇', 19, 48, 9, '神よ私たちはあなたの宮の中であなたの恵みを思いました。'),
('JPN', '诗篇', 19, 48, 10, '神よあなたの御名と同じくあなたの誉れは地の果てにまで及んでいます。あなたの右の手は義に満ちています。'),
('JPN', '诗篇', 19, 48, 11, 'あなたのさばきのゆえにシオンの山が喜びユダの娘たちが楽しみますように。'),
('JPN', '诗篇', 19, 48, 12, 'シオンを巡りその周りを歩け。その塔を数えよ。'),
('JPN', '诗篇', 19, 48, 13, 'その城壁に心を留めよ。その宮殿を巡り歩け。後の時代に語り伝えるために。'),
('JPN', '诗篇', 19, 48, 14, 'この方こそまさしく神。世々限りなくわれらの神。神は死を越えて私たちを導かれる。'),
('JPN', '诗篇', 19, 49, 1, 'すべて国々の民よこれを聞け。すべて世に住む者よ耳を傾けよ。'),
('JPN', '诗篇', 19, 49, 2, '低い者も高い者も富む者も貧しい者もともどもに。'),
('JPN', '诗篇', 19, 49, 3, '私の口は知恵を語り私の心は英知を告げる。'),
('JPN', '诗篇', 19, 49, 4, '私はたとえ話に耳を傾け竪琴に合わせて謎を解き明かそう。'),
('JPN', '诗篇', 19, 49, 5, 'なぜ私はわざわいの日々に恐れなければならないのか。私のかかとを狙う者の悪意が私を取り囲むときに。'),
('JPN', '诗篇', 19, 49, 6, '彼らは自分の財産に拠り頼み豊かな富を誇っている。'),
('JPN', '诗篇', 19, 49, 7, '兄弟さえも人は贖い出すことができない。自分の身代金を神に払うことはできない。'),
('JPN', '诗篇', 19, 49, 8, 'たましいの贖いの代価は高く永久にあきらめなくてはならない。'),
('JPN', '诗篇', 19, 49, 9, '人はいつまでも生きられるだろうか。墓を見ないでいられるだろうか。'),
('JPN', '诗篇', 19, 49, 10, '彼は見る。知恵のある者たちが死に愚かな者浅はかな者も等しく滅び自分の財産を他人に残すのを。'),
('JPN', '诗篇', 19, 49, 11, '彼らの心の中ではその家は永遠で住まいは代々に及ぶ。彼らは土地に自分たちの名をつける。'),
('JPN', '诗篇', 19, 49, 12, 'しかし人は栄華のうちにとどまれない。人は滅び失せる獣に等しい。'),
('JPN', '诗篇', 19, 49, 13, 'これが愚か者の道。彼らに従う者もその口のことばを喜ぶ。セラ'),
('JPN', '诗篇', 19, 49, 14, '彼らは羊のようによみに定められ死が彼らの羊飼いとなる。朝には直ぐな者たちが彼らを支配する。彼らの形はなくなりよみがその住む所となる。'),
('JPN', '诗篇', 19, 49, 15, 'しかし神は私のたましいを贖い出しよみの手から私を奪い返してくださる。セラ'),
('JPN', '诗篇', 19, 49, 16, '恐れるな。人が富を得てもその人の家の栄誉が増し加わっても。'),
('JPN', '诗篇', 19, 49, 17, '人は死ぬとき何一つ持って行くことはできずその栄誉もその人を追って下ることはない。'),
('JPN', '诗篇', 19, 49, 18, 'たとえ人が自分自身を生きている間に祝福できてもあなたには物事がうまく行っていると人々があなたをほめたたえても。'),
('JPN', '诗篇', 19, 49, 19, 'そのたましいは代々の先祖のところに行く。そこでは永久に光を見ることはない。'),
('JPN', '诗篇', 19, 49, 20, '人は栄華のうちにあっても悟ることがなければ滅び失せる獣に等しい。'),
('JPN', '诗篇', 19, 50, 1, '神の神主は語り地を呼び集められる。日の昇るところから沈むところまで。'),
('JPN', '诗篇', 19, 50, 2, '麗しさの極みシオンから神は光を放たれる。'),
('JPN', '诗篇', 19, 50, 3, '私たちの神は来られる。黙ってはおられない。御前には食い尽くす火がありその周りには激しい嵐がある。'),
('JPN', '诗篇', 19, 50, 4, '神は上なる天をまた地を呼び集められる。ご自分の民をさばくために。'),
('JPN', '诗篇', 19, 50, 5, '「わたしにある敬虔な者をわたしのところに集めよ。いけにえによってわたしと契約を結んだ者たちを。」'),
('JPN', '诗篇', 19, 50, 6, '天は神の義を告げ知らせる。神こそが審判者であると。セラ'),
('JPN', '诗篇', 19, 50, 7, '「聞けわが民よ。わたしは語ろう。イスラエルよわたしはあなたを戒めよう。わたしは神あなたの神である。'),
('JPN', '诗篇', 19, 50, 8, 'あなたのいけにえのことであなたを責めるのではない。あなたの全焼のささげ物はいつもわたしの前にある。'),
('JPN', '诗篇', 19, 50, 9, 'わたしはあなたの家から雄牛を囲いから雄やぎを取ろうとしているのではない。'),
('JPN', '诗篇', 19, 50, 10, '森のすべての獣はわたしのもの。千の丘の家畜らも。'),
('JPN', '诗篇', 19, 50, 11, 'わたしは山の鳥も残らず知っている。野に群がるものたちもわたしのもとにいる。'),
('JPN', '诗篇', 19, 50, 12, 'たとえ飢えてもわたしはあなたに言わない。世界とそれに満ちるものはわたしのものだ。'),
('JPN', '诗篇', 19, 50, 13, 'わたしが雄牛の肉を食べ雄やぎの血を飲むだろうか。'),
('JPN', '诗篇', 19, 50, 14, '感謝のいけにえを神に献げよ。あなたの誓いをいと高き神に果たせ。'),
('JPN', '诗篇', 19, 50, 15, '苦難の日にわたしを呼び求めよ。わたしはあなたを助け出しあなたはわたしをあがめる。」'),
('JPN', '诗篇', 19, 50, 16, 'しかし悪しき者に対して神は仰せられる。「何事か。おまえがわたしのおきてを語りわたしの契約を口にするとは。'),
('JPN', '诗篇', 19, 50, 17, 'おまえは戒めを憎みわたしのことばをうしろに投げ捨てた。'),
('JPN', '诗篇', 19, 50, 18, 'おまえは盗人に会うとこれと組んで姦通する者と親しくする。'),
('JPN', '诗篇', 19, 50, 19, 'おまえの口は悪を放ち舌は欺きを仕組む。'),
('JPN', '诗篇', 19, 50, 20, 'おまえは座して兄弟の悪口を言い自分の母の子をそしる。'),
('JPN', '诗篇', 19, 50, 21, 'こういうことをおまえはしてきたがわたしは黙っていた。わたしがおまえと等しい者だとおまえは思っていたのだ。わたしはおまえを責める。おまえの目の前でこれらのことを並べ立てる。'),
('JPN', '诗篇', 19, 50, 22, '神を忘れる者どもよさあこのことをよくわきまえよ。そうでないとわたしはおまえたちを引き裂き救い出す者もいなくなる。'),
('JPN', '诗篇', 19, 50, 23, '感謝のいけにえを献げる者はわたしをあがめる。自分の道を正しくする人にわたしは神の救いを見せる。」'),
('JPN', '诗篇', 19, 51, 1, '神よ私をあわれんでください。あなたの恵みにしたがって。私の背きをぬぐい去ってください。あなたの豊かなあわれみによって。'),
('JPN', '诗篇', 19, 51, 2, '私の咎を私からすっかり洗い去り私の罪から私をきよめてください。'),
('JPN', '诗篇', 19, 51, 3, 'まことに私は自分の背きを知っています。私の罪はいつも私の目の前にあります。'),
('JPN', '诗篇', 19, 51, 4, '私はあなたにただあなたの前に罪ある者です。私はあなたの目に悪であることを行いました。ですからあなたが宣告するときあなたは正しくさばくときあなたは清くあられます。'),
('JPN', '诗篇', 19, 51, 5, 'ご覧ください。私は咎ある者として生まれ罪ある者として母は私を身ごもりました。'),
('JPN', '诗篇', 19, 51, 6, '確かにあなたは心のうちの真実を喜ばれます。どうか私の心の奥に知恵を教えてください。'),
('JPN', '诗篇', 19, 51, 7, 'ヒソプで私の罪を除いてください。そうすれば私はきよくなります。私を洗ってください。そうすれば私は雪よりも白くなります。'),
('JPN', '诗篇', 19, 51, 8, '楽しみと喜びの声を聞かせてください。そうすればあなたが砕かれた骨が喜びます。'),
('JPN', '诗篇', 19, 51, 9, '御顔を私の罪から隠し私の咎をすべてぬぐい去ってください。'),
('JPN', '诗篇', 19, 51, 10, '神よ私にきよい心を造り揺るがない霊を私のうちに新しくしてください。'),
('JPN', '诗篇', 19, 51, 11, '私をあなたの御前から投げ捨てずあなたの聖なる御霊を私から取り去らないでください。'),
('JPN', '诗篇', 19, 51, 12, 'あなたの救いの喜びを私に戻し仕えることを喜ぶ霊で私を支えてください。'),
('JPN', '诗篇', 19, 51, 13, '私は背く者たちにあなたの道を教えます。罪人たちはあなたのもとに帰るでしょう。'),
('JPN', '诗篇', 19, 51, 14, '神よ私の救いの神よ血の罪から私を救い出してください。私の舌はあなたの義を高らかに歌います。'),
('JPN', '诗篇', 19, 51, 15, '主よ私の唇を開いてください。私の口はあなたの誉れを告げ知らせます。'),
('JPN', '诗篇', 19, 51, 16, 'まことに私が供えてもあなたはいけにえを喜ばれず全焼のささげ物を望まれません。'),
('JPN', '诗篇', 19, 51, 17, '神へのいけにえは砕かれた霊。打たれ砕かれた心。神よあなたはそれを蔑まれません。'),
('JPN', '诗篇', 19, 51, 18, 'どうかご恩寵によりシオンにいつくしみを施しエルサレムの城壁を築き直してください。'),
('JPN', '诗篇', 19, 51, 19, 'そのときあなたは義のいけにえを焼き尽くされる全焼のささげ物を喜ばれます。そのとき雄牛があなたの祭壇に献げられます。'),
('JPN', '诗篇', 19, 52, 1, '勇士よなぜおまえは悪を誇りとするのか。神の恵みはいつもある。'),
('JPN', '诗篇', 19, 52, 2, '欺く者よおまえの舌は破壊を企む。まるで鋭い刃物のように。'),
('JPN', '诗篇', 19, 52, 3, 'おまえは善よりも悪を義を語るよりも偽りを愛している。セラ'),
('JPN', '诗篇', 19, 52, 4, '欺きの舌よおまえはあらゆる滅びのことばを愛している。'),
('JPN', '诗篇', 19, 52, 5, 'だが神はおまえを打ち砕いて倒し幕屋からおまえを引き抜かれる。生ける者の地からおまえは根絶やしにされる。セラ'),
('JPN', '诗篇', 19, 52, 6, '正しい人たちは見て恐れ彼に向かって笑う。'),
('JPN', '诗篇', 19, 52, 7, '「見よ彼こそは神を力とせず自分の大きな富に頼り破滅のわざを勝ち誇る者。」'),
('JPN', '诗篇', 19, 52, 8, 'しかし私は神の家に生い茂るオリーブの木。私は世々限りなく神の恵みに拠り頼む。'),
('JPN', '诗篇', 19, 52, 9, '私はとこしえに感謝します。あなたのみわざのゆえに。私はあなたにある敬虔な人たちの前ですばらしいあなたの御名を待ち望みます。'),
('JPN', '诗篇', 19, 53, 1, '愚か者は心の中で「神はいない」と言う。彼らは腐っている。忌まわしい不正を行っている。善を行う者はいない。'),
('JPN', '诗篇', 19, 53, 2, '神は天から人の子らを見下ろされた。悟る者神を求める者がいるかどうかと。'),
('JPN', '诗篇', 19, 53, 3, '彼らはことごとく背き去りだれもかれも無用の者となった。善を行う者はいない。だれ一人いない。'),
('JPN', '诗篇', 19, 53, 4, '不法を行う者たちは知らないのか。彼らはわたしの民を食らいながらパンを食べ神を呼ばない。'),
('JPN', '诗篇', 19, 53, 5, '見よ彼らは恐れのないところで大いに恐れた。神があなたに陣を張る者の骨を散らされたのだ。あなたは彼らを辱めた。神が彼らを捨てられたのだ。'),
('JPN', '诗篇', 19, 53, 6, 'ああイスラエルの救いがシオンから来るように。神が御民を元どおりにされるときヤコブは楽しめ。イスラエルは喜べ。'),
('JPN', '诗篇', 19, 54, 1, '神よあなたの御名によって私をお救いください。あなたの力強いみわざによって私を弁護してください。'),
('JPN', '诗篇', 19, 54, 2, '神よ私の祈りを聞いてください。私の口のことばに耳を傾けてください。'),
('JPN', '诗篇', 19, 54, 3, '見知らぬ者たちが私に立ち向かい横暴な者たちが私のいのちを求めています。彼らは神を前にしていないのです。セラ'),
('JPN', '诗篇', 19, 54, 4, '見よ神は私を助ける方。主は私のいのちを支える方。'),
('JPN', '诗篇', 19, 54, 5, '神は私を待ち伏せる者たちにわざわいをもって報いられます。あなたの真実によって彼らを滅ぼしてください。'),
('JPN', '诗篇', 19, 54, 6, '私は心からのささげ物をもってあなたにいけにえを献げます。主よあなたの御名に感謝します。すばらしい御名に。'),
('JPN', '诗篇', 19, 54, 7, '神がすべての苦難から私を救い出し私の目が敵を平然と眺めるようになったからです。'),
('JPN', '诗篇', 19, 55, 1, '神よ私の祈りを耳に入れ私の切なる願いに耳を閉ざさないでください。'),
('JPN', '诗篇', 19, 55, 2, '私をみこころに留め私に答えてください。私は悲嘆に暮れ泣き叫んでいます。'),
('JPN', '诗篇', 19, 55, 3, 'それは敵の叫びと悪者の迫害のためです。彼らは私にわざわいを降りかからせ怒って私を攻めたてています。'),
('JPN', '诗篇', 19, 55, 4, '私の心は内にもだえ死の恐怖が私を襲っています。'),
('JPN', '诗篇', 19, 55, 5, '恐れと震えが私に起こり戦慄が私を包みました。'),
('JPN', '诗篇', 19, 55, 6, '私は言いました。「ああ私に鳩のように翼があったなら。飛び去って休むことができたなら。'),
('JPN', '诗篇', 19, 55, 7, 'ああどこか遠くへ逃れ去り荒野の中に宿りたい。セラ'),
('JPN', '诗篇', 19, 55, 8, '嵐と疾風を避けて私の逃れ場に急ぎたい。」'),
('JPN', '诗篇', 19, 55, 9, '主よ彼らの舌を混乱させ分裂させてください。私はこの都の中に暴虐と争いを見ています。'),
('JPN', '诗篇', 19, 55, 10, '昼も夜も彼らは城壁の上を歩き回り不法と害悪が都のただ中にあります。'),
('JPN', '诗篇', 19, 55, 11, '破滅が都のただ中にあり虐待と詐欺はその広場を離れません。'),
('JPN', '诗篇', 19, 55, 12, 'まことに私をそしっているのは敵ではない。それなら私は忍ぶことができる。私に向かって高ぶっているのは私を憎む者ではない。それなら私は身を隠すことができる。'),
('JPN', '诗篇', 19, 55, 13, 'それはおまえ。私の同輩私の友私の親友のおまえなのだ。'),
('JPN', '诗篇', 19, 55, 14, '私たちはともに親しく交わりにぎわいの中神の家に一緒に歩いて行ったのに。'),
('JPN', '诗篇', 19, 55, 15, '死が彼らをつかめばよい。彼らは生きたままよみに下るがよい。悪が彼らの住まいに彼らのただ中にあるからだ。'),
('JPN', '诗篇', 19, 55, 16, '私が神を呼ぶと主は私を救ってくださる。'),
('JPN', '诗篇', 19, 55, 17, '夕べに朝にまた真昼に私は嘆きうめく。すると主は私の声を聞いてくださる。'),
('JPN', '诗篇', 19, 55, 18, '主は私のたましいを敵の挑戦から平和のうちに贖い出してくださる。私と争う者が多いから。'),
('JPN', '诗篇', 19, 55, 19, '神は聞き彼らを苦しめられる。昔から御座に着いておられる方は。セラ彼らは改めず神を恐れない。'),
('JPN', '诗篇', 19, 55, 20, '彼は親しい者にまで手を伸ばし自分の誓約を犯している。'),
('JPN', '诗篇', 19, 55, 21, 'その口はよどみなく語るが心には戦いがある。そのことばは油よりも滑らかだがそれは抜き身の剣である。'),
('JPN', '诗篇', 19, 55, 22, 'あなたの重荷を主にゆだねよ。主があなたを支えてくださる。主は決して正しい者が揺るがされるようにはなさらない。'),
('JPN', '诗篇', 19, 55, 23, 'しかし神よあなたは彼らを滅びの穴に落とされます。人の血を流す者どもと欺く者どもは日数の半ばも生きられないでしょう。しかし私はあなたに拠り頼みます。'),
('JPN', '诗篇', 19, 56, 1, '神よ私をあわれんでください。人が私を踏みつけ一日中戦って私を虐げているからです。'),
('JPN', '诗篇', 19, 56, 2, '私の敵は一日中私を踏みつけています。高ぶって私に戦いを挑む者が多いのです。'),
('JPN', '诗篇', 19, 56, 3, '心に恐れを覚える日私はあなたに信頼します。'),
('JPN', '诗篇', 19, 56, 4, '神にあって私はみことばをほめたたえます。神に信頼し私は何も恐れません。肉なる者が私に何をなし得るでしょう。'),
('JPN', '诗篇', 19, 56, 5, '一日中彼らは私のことを痛めつけています。彼らの思い計ることはみな私に対する悪です。'),
('JPN', '诗篇', 19, 56, 6, '彼らは襲おうとして待ち伏せし私の跡をつけています。私のいのちを狙って。'),
('JPN', '诗篇', 19, 56, 7, '不法があるのに彼らを見逃されるのですか。神よ御怒りで国々の民を打ち倒してください。'),
('JPN', '诗篇', 19, 56, 8, 'あなたは私のさすらいを記しておられます。どうか私の涙をあなたの皮袋に蓄えてください。それともあなたの書に記されていないのですか。'),
('JPN', '诗篇', 19, 56, 9, 'そのとき私の敵は退きます。私が呼び求める日に。私は知っています。神が味方であることを。'),
('JPN', '诗篇', 19, 56, 10, '神にあって私はみことばをほめたたえます。主にあって私はみことばをほめたたえます。'),
('JPN', '诗篇', 19, 56, 11, '神に信頼し私は何も恐れません。人が私に何をなし得るでしょう。'),
('JPN', '诗篇', 19, 56, 12, '神よあなたへの誓いは私の上にあります。感謝のいけにえであなたにそれを果たします。'),
('JPN', '诗篇', 19, 56, 13, 'まことにあなたは救い出してくださいました。私のいのちを死から。私の足をつまずきから。私がいのちの光のうちに神の御前に歩むために。'),
('JPN', '诗篇', 19, 57, 1, '私をあわれんでください。神よ。私をあわれんでください。私のたましいはあなたに身を避けていますから。私は滅びが過ぎ去るまで御翼の陰に身を避けます。'),
('JPN', '诗篇', 19, 57, 2, '私はいと高き方神を呼び求めます。私のためにすべてを成し遂げてくださる神を。'),
('JPN', '诗篇', 19, 57, 3, '神は天から助けを送って私を救い私を踏みつける者どもを辱められます。セラ神は恵みとまことを送ってくださいます。'),
('JPN', '诗篇', 19, 57, 4, '私のたましいは獅子たちの間で人の子らを貪り食う者の間で横たわっています。彼らの歯は槍と矢彼らの舌は鋭い剣です。'),
('JPN', '诗篇', 19, 57, 5, '神よあなたが天であなたの栄光が全世界であがめられますように。'),
('JPN', '诗篇', 19, 57, 6, '彼らは私の足を狙って網を仕掛けました。私のたましいはうなだれています。彼らは私の前に穴を掘り自分でその中に落ちました。セラ'),
('JPN', '诗篇', 19, 57, 7, '神よ私の心は揺るぎません。私の心は揺るぎません。私は歌いほめ歌います。'),
('JPN', '诗篇', 19, 57, 8, '私のたましいよ目を覚ませ。琴よ竪琴よ目を覚ませ。私は暁を呼び覚まそう。'),
('JPN', '诗篇', 19, 57, 9, '主よ私は国々の民の間であなたに感謝しもろもろの国民の間であなたをほめ歌います。'),
('JPN', '诗篇', 19, 57, 10, 'あなたの恵みは大きく天にまで及びあなたのまことは雲にまで及ぶからです。'),
('JPN', '诗篇', 19, 57, 11, '神よあなたが天であなたの栄光が全地であがめられますように。'),
('JPN', '诗篇', 19, 58, 1, '力ある者たちよおまえたちは本当に義を語り人の子らを公正にさばくことができるのか。'),
('JPN', '诗篇', 19, 58, 2, '実におまえたちは心で不正を働き地で手の暴虐をはびこらせている。'),
('JPN', '诗篇', 19, 58, 3, '悪しき者どもは母の胎を出たときから踏み迷い偽りを言う者どもは生まれたときからさまよっている。'),
('JPN', '诗篇', 19, 58, 4, '彼らには蛇の毒のような毒がある。耳の聞こえないコブラのように耳を閉ざし'),
('JPN', '诗篇', 19, 58, 5, '蛇使いの声も聞こうとしない。巧みに呪文を唱える者の声も。'),
('JPN', '诗篇', 19, 58, 6, '神よ彼らの歯をその口の中で折ってください。主よ若獅子たちの牙を打ち砕いてください。'),
('JPN', '诗篇', 19, 58, 7, '彼らが流れ行く水のように消え去り神が矢を放たれるとき干上がりますように。'),
('JPN', '诗篇', 19, 58, 8, '彼らが溶けて消え行くなめくじのように日の目を見ない死産の子のようになりますように。'),
('JPN', '诗篇', 19, 58, 9, 'おまえたちの釜が茨の火を感じる前に神はそれが緑のままでも燃えていても等しく吹き払われる。'),
('JPN', '诗篇', 19, 58, 10, '正しい人は復讐を見て喜びその足を悪しき者の血で洗う。'),
('JPN', '诗篇', 19, 58, 11, 'こうして人は言う。「まことに正しい人には報いがある。まことにさばく神が地におられる。」'),
('JPN', '诗篇', 19, 59, 1, '私の神よ私を敵から救い出してください。向かい立つ者たちよりも高く私を引き上げてください。'),
('JPN', '诗篇', 19, 59, 2, '不法を行う者どもから私を救い出してください。人の血を流す者どもから私を救ってください。'),
('JPN', '诗篇', 19, 59, 3, '今しも彼らは私のたましいを待ち伏せし力ある者どもは私に襲いかかろうとしています。主よそれは私の背きのゆえでもなく私の罪のゆえでもありません。'),
('JPN', '诗篇', 19, 59, 4, '私には咎がないのに彼らは走り身構えています。どうか目を覚ましここに来て見てください。'),
('JPN', '诗篇', 19, 59, 5, 'あなたは万軍の神主イスラエルの神。どうか目を覚ましすべての国を罰してください。邪悪な裏切り者をだれもあわれまないでください。セラ'),
('JPN', '诗篇', 19, 59, 6, '彼らは夕べに帰って来ては犬のようにほえ町をうろつき回ります。'),
('JPN', '诗篇', 19, 59, 7, 'ご覧ください。彼らの唇には多くの剣がありその口で放言しているのです。「だれが聞くものか」と。'),
('JPN', '诗篇', 19, 59, 8, 'しかし主よあなたは彼らを笑いすべての国々を嘲られます。'),
('JPN', '诗篇', 19, 59, 9, '私の力よ私はあなたを見続けます。神が私の砦だからです。'),
('JPN', '诗篇', 19, 59, 10, '私の恵みの神は私を迎えに来てくださる。神は私に敵を平然と眺めるようにしてくださる。'),
('JPN', '诗篇', 19, 59, 11, '彼らを殺してしまわないでください。私の民が忘れることのないように。御力によって彼らをさまよわせてください。彼らを打ち倒してください。主よ私たちの盾よ。'),
('JPN', '诗篇', 19, 59, 12, '彼らの口の罪は彼らの唇のことば。彼らは高慢にとらえられるがよい。彼らが語る呪いとへつらいのゆえに。'),
('JPN', '诗篇', 19, 59, 13, '憤りをもって滅ぼし尽くしてください。滅ぼし尽くしてください。彼らがいなくなるまで。神が地の果てまでもヤコブを治められることを彼らが知るようにしてください。セラ'),
('JPN', '诗篇', 19, 59, 14, '彼らは夕べに帰って来ては犬のようにほえ町をうろつき回ります。'),
('JPN', '诗篇', 19, 59, 15, '食を求めてさまよい歩き満ち足りなければ夜を明かします。'),
('JPN', '诗篇', 19, 59, 16, 'しかしこの私はあなたの力を歌います。朝明けにはあなたの恵みを喜び歌います。私の苦しみの日にあなたが私の砦また私の逃れ場であられたからです。'),
('JPN', '诗篇', 19, 59, 17, '私の力よ私はあなたにほめ歌を歌います。神は私の砦私の恵みの神であるからです。'),
('JPN', '诗篇', 19, 60, 1, '神よあなたは私たちを拒み私たちを破られました。あなたは怒られました。どうか私たちを回復させてください。'),
('JPN', '诗篇', 19, 60, 2, 'あなたは地を揺るがし引き裂かれました。その裂け目を癒やしてください。地が揺れ動いているからです。'),
('JPN', '诗篇', 19, 60, 3, 'あなたは御民を苦しい目にあわせよろめかす酒を私たちに飲ませられました。'),
('JPN', '诗篇', 19, 60, 4, 'あなたはあなたを恐れる者に旗を授けられました。弓から逃れた者をそこに集めるために。セラ'),
('JPN', '诗篇', 19, 60, 5, 'あなたの愛する者たちが助け出されるようあなたの右の手で救い私に答えてください。'),
('JPN', '诗篇', 19, 60, 6, '神は聖所から告げられました。「わたしは喜んでシェケムを分けスコテの平原を測ろう。'),
('JPN', '诗篇', 19, 60, 7, 'ギルアデはわたしのもの。マナセもわたしのもの。エフライムはわたしの頭のかぶと。ユダはわたしの王笏。'),
('JPN', '诗篇', 19, 60, 8, 'モアブはわたしの足を洗うたらい。エドムの上にわたしの履き物を投げつけよう。ペリシテよわたしのゆえに大声で叫べ。」'),
('JPN', '诗篇', 19, 60, 9, 'だれが私を防備の町に連れて行くのでしょうか。だれが私をエドムまで導くのでしょうか。'),
('JPN', '诗篇', 19, 60, 10, '神よあなたご自身が私たちを拒まれるのですか。神よあなたはもはや私たちとともに出陣なさらないのですか。'),
('JPN', '诗篇', 19, 60, 11, 'どうか敵から私たちを助けてください。人による救いはむなしいからです。'),
('JPN', '诗篇', 19, 60, 12, '神にあって私たちは力ある働きをします。神が私たちの敵を踏みつけてくださいます。'),
('JPN', '诗篇', 19, 61, 1, '神よ私の叫びを聞き私の祈りに耳を傾けてください。'),
('JPN', '诗篇', 19, 61, 2, '私の心が衰え果てるとき私は地の果てからあなたを呼び求めます。どうか及びがたいほど高い岩の上に私を導いてください。'),
('JPN', '诗篇', 19, 61, 3, 'あなたは私の避け所敵に対して強いやぐら。'),
('JPN', '诗篇', 19, 61, 4, '私はあなたの幕屋にいつまでも住み御翼の陰に身を避けます。セラ'),
('JPN', '诗篇', 19, 61, 5, '神よまことにあなたは私の誓いを聞き入れ御名を恐れる者の受け継ぐ地を私に下さいました。'),
('JPN', '诗篇', 19, 61, 6, 'どうか王のいのちを延ばしその齢を代々に至らせてください。'),
('JPN', '诗篇', 19, 61, 7, '王が神の御前でいつまでも王座に着いているようにしてください。恵みとまことを与えて王をお守りください。'),
('JPN', '诗篇', 19, 61, 8, 'こうして私はあなたの御名をとこしえまでもほめ歌い日ごとに私の誓いを果たします。'),
('JPN', '诗篇', 19, 62, 1, '私のたましいは黙ってただ神を待ち望む。私の救いは神から来る。'),
('JPN', '诗篇', 19, 62, 2, '神こそわが岩わが救いわがやぐら。私は決して揺るがされない。'),
('JPN', '诗篇', 19, 62, 3, 'おまえたちはいつまで一人の人を襲うのか。おまえたちはこぞって打ち殺そうとしている。城壁を傾け石垣を倒すように。'),
('JPN', '诗篇', 19, 62, 4, '実に彼らは人を高い地位から突き落とそうと企んでいる。彼らは偽りを好み口では祝福し心では呪う。セラ'),
('JPN', '诗篇', 19, 62, 5, '私のたましいよ黙ってただ神を待ち望め。私の望みは神から来るからだ。'),
('JPN', '诗篇', 19, 62, 6, '神こそわが岩わが救いわがやぐら。私は揺るがされることがない。'),
('JPN', '诗篇', 19, 62, 7, '私の救いと栄光はただ神にある。私の力の岩と避け所は神のうちにある。'),
('JPN', '诗篇', 19, 62, 8, '民よどんなときにも神に信頼せよ。あなたがたの心を神の御前に注ぎ出せ。神はわれらの避け所である。セラ'),
('JPN', '诗篇', 19, 62, 9, '低い者はただ空しく高い者も偽りだ。秤にかけると彼らは上に上がる。彼らを合わせても息より軽い。'),
('JPN', '诗篇', 19, 62, 10, '圧制に頼るな。略奪に空しい望みをかけるな。富が増えてもそれに心を留めるな。'),
('JPN', '诗篇', 19, 62, 11, '神は一度告げられた。二度私はそれを聞いた。力は神のものであることを。'),
('JPN', '诗篇', 19, 62, 12, '主よ恵みもあなたのものです。あなたはその行いに応じて人に報いられます。'),
('JPN', '诗篇', 19, 63, 1, '神よあなたは私の神。私はあなたを切に求めます。水のない衰え果てた乾いた地で私のたましいはあなたに渇き私の身もあなたをあえぎ求めます。'),
('JPN', '诗篇', 19, 63, 2, '私はあなたの力と栄光を見るためにこうして聖所であなたを仰ぎ見ています。'),
('JPN', '诗篇', 19, 63, 3, 'あなたの恵みはいのちにもまさるゆえ私の唇はあなたを賛美します。'),
('JPN', '诗篇', 19, 63, 4, 'それゆえ私は生きるかぎりあなたをほめたたえあなたの御名により両手を上げて祈ります。'),
('JPN', '诗篇', 19, 63, 5, '脂肪と髄をふるまわれたかのように私のたましいは満ち足りています。喜びにあふれた唇で私の口はあなたを賛美します。'),
('JPN', '诗篇', 19, 63, 6, '床の上であなたを思い起こすとき夜もすがらあなたのことを思い巡らすときに。'),
('JPN', '诗篇', 19, 63, 7, 'まことにあなたは私の助けでした。御翼の陰で私は喜び歌います。'),
('JPN', '诗篇', 19, 63, 8, '私のたましいはあなたにすがりあなたの右の手は私を支えてくださいます。'),
('JPN', '诗篇', 19, 63, 9, '私のいのちを求める者どもは滅び地の深い所に行くでしょう。'),
('JPN', '诗篇', 19, 63, 10, '彼らは剣の力に渡され狐の餌食となるのです。'),
('JPN', '诗篇', 19, 63, 11, 'しかし王は神にあって喜び神にかけて誓う者はみな誇ります。偽りを言う者の口が封じられるからです。'),
('JPN', '诗篇', 19, 64, 1, '神よ私が嘆くとき私の声を聞いてください。敵の脅かしから私のいのちを守ってください。'),
('JPN', '诗篇', 19, 64, 2, 'どうか私をかくまってください。悪を行う者どものはかりごとから不法を行う者どもの騒ぎから。'),
('JPN', '诗篇', 19, 64, 3, '彼らはその舌を剣のように研ぎ澄まし苦いことばの矢を放っています。'),
('JPN', '诗篇', 19, 64, 4, '全き人に向けて彼らは隠れた所から射掛け不意に矢を射て何も恐れません。'),
('JPN', '诗篇', 19, 64, 5, '彼らは悪事に凝っています。示し合わせてひそかに罠をかけ「だれが見破ることができよう」と言っています。'),
('JPN', '诗篇', 19, 64, 6, '彼らは不正を企み「企んだ策略がうまくいった」と言っています。人の内なる思いと心とは底が知れません。'),
('JPN', '诗篇', 19, 64, 7, 'しかし神が彼らに矢を射掛けられるので彼らは不意に傷つきます。'),
('JPN', '诗篇', 19, 64, 8, '彼らは自らの舌につまずきました。彼らを見る者はみな頭を振って嘲ります。'),
('JPN', '诗篇', 19, 64, 9, 'こうしてすべての人は恐れ神のみわざを告げ知らせそのなさったことを悟ります。'),
('JPN', '诗篇', 19, 64, 10, '正しい人は主にあって喜び主に身を避けます。心の直ぐな人はみな誇ることができます。'),
('JPN', '诗篇', 19, 65, 1, '神よ御前には静けさがありシオンには賛美があります。あなたに誓いが果たされますように。'),
('JPN', '诗篇', 19, 65, 2, '祈りを聞かれる方よみもとにすべての肉なる者が参ります。'),
('JPN', '诗篇', 19, 65, 3, '数々の咎が私を圧倒しています。しかし私たちの背きをあなたは赦してくださいます。'),
('JPN', '诗篇', 19, 65, 4, '幸いなことよあなたが選び近寄せられた人あなたの大庭に住む人は。私たちはあなたの家の良いものあなたの宮の聖なるもので満ち足ります。'),
('JPN', '诗篇', 19, 65, 5, '私たちの救いの神よ。あなたは恐るべきみわざで義のうちに答えられます。あなたは地のすべての果て遠い大海の信頼の的です。'),
('JPN', '诗篇', 19, 65, 6, 'あなたは御力によって山々を堅く据え大能を帯びておられます。'),
('JPN', '诗篇', 19, 65, 7, 'あなたは海のとどろきを鎮められます。その大波のとどろきもろもろの国民の騒ぎを。'),
('JPN', '诗篇', 19, 65, 8, '最果てに住む者もあなたの数々のしるしを恐れます。あなたは朝と夕の始まる所が高らかに歌うようにされます。'),
('JPN', '诗篇', 19, 65, 9, 'あなたは地を訪れ水を注ぎこれを大いに豊かにされます。神の川は水で満ちています。あなたはこうして地を整え人々の穀物を備えてくださいます。'),
('JPN', '诗篇', 19, 65, 10, '地のあぜ溝を水で満たしその畝をならし夕立で地を柔らかにしその生長を祝福されます。'),
('JPN', '诗篇', 19, 65, 11, 'あなたはその年に御恵みの冠をかぶらせます。あなたの通られた跡には油が滴っています。'),
('JPN', '诗篇', 19, 65, 12, '荒野の牧場に滴りもろもろの丘も喜びをまとっています。'),
('JPN', '诗篇', 19, 65, 13, '牧草地は羊の群れをまとい広やかな平原は穀物を覆いとしています。まことに喜び叫び歌っています。'),
('JPN', '诗篇', 19, 66, 1, '全地よ神に向かって喜び叫べ。'),
('JPN', '诗篇', 19, 66, 2, '御名の栄光をほめ歌い神の誉れに栄光を帰せよ。'),
('JPN', '诗篇', 19, 66, 3, '神に申し上げよ。「あなたのみわざはなんと恐ろしいことでしょう。偉大な御力のためにあなたの敵は御前にへつらい服します。'),
('JPN', '诗篇', 19, 66, 4, '全地はあなたを伏し拝みます。あなたをほめ歌いあなたの御名をほめ歌います。」セラ'),
('JPN', '诗篇', 19, 66, 5, 'さあ神のみわざを見よ。神が人の子らになさることは恐ろしい。'),
('JPN', '诗篇', 19, 66, 6, '神は海を乾いた所とされた。人々は川の中を歩いて渡った。さあ私たちは神にあって喜ぼう。'),
('JPN', '诗篇', 19, 66, 7, '神はその御力をもってとこしえに統べ治めその目は国々を見張られる。どうか頑迷な者を高ぶらせないでください。セラ'),
('JPN', '诗篇', 19, 66, 8, '国々の民よ私たちの神をほめたたえよ。神の誉れをたたえる声を響き渡らせよ。'),
('JPN', '诗篇', 19, 66, 9, '神は私たちのたましいをいのちのうちに保ち私たちの足を揺るがされない。'),
('JPN', '诗篇', 19, 66, 10, '神よまことにあなたは私たちを試し銀を精錬するように私たちを錬られました。'),
('JPN', '诗篇', 19, 66, 11, 'あなたは私たちを網に引き入れ私たちの腰に重荷を負わされました。'),
('JPN', '诗篇', 19, 66, 12, 'あなたは人々に私たちの頭をまたがせ私たちは火の中水の中を通りました。しかしあなたは私たちを豊かな所へ導き出してくださいました。'),
('JPN', '诗篇', 19, 66, 13, '私は全焼のささげ物を携えてあなたの家に行き私の誓いをあなたに果たします。'),
('JPN', '诗篇', 19, 66, 14, 'それは私の苦しみのときに唇を大きく開きこの口で申し上げた誓いです。'),
('JPN', '诗篇', 19, 66, 15, '私は肥えたものを全焼のささげ物として雄羊のいけにえの煙とともにあなたに献げます。雄牛を雄やぎとともに献げます。セラ'),
('JPN', '诗篇', 19, 66, 16, 'さあ聞けすべて神を恐れる者たちよ。神が私のたましいになさったことを語ろう。'),
('JPN', '诗篇', 19, 66, 17, '私はこの口で神を呼び求めこの舌で神をあがめた。'),
('JPN', '诗篇', 19, 66, 18, 'もしも不義を私が心のうちに見出すなら主は聞き入れてくださらない。'),
('JPN', '诗篇', 19, 66, 19, 'しかし確かに神は聞き入れ私の祈りの声に耳を傾けてくださった。'),
('JPN', '诗篇', 19, 66, 20, 'ほむべきかな神。神は私の祈りを退けず御恵みを私から取り去られなかった。'),
('JPN', '诗篇', 19, 67, 1, 'どうか神が私たちをあわれみ祝福し御顔を私たちの上に照り輝かせてくださいますように。セラ'),
('JPN', '诗篇', 19, 67, 2, 'あなたの道が地の上で御救いがすべての国々の間で知られるために。'),
('JPN', '诗篇', 19, 67, 3, '神よ諸国の民があなたをほめたたえ諸国の民がみなあなたをほめたたえますように。'),
('JPN', '诗篇', 19, 67, 4, '国々の民が喜びまた喜び歌いますように。それはあなたが公平に諸国の民をさばき地の国民を導かれるからです。セラ'),
('JPN', '诗篇', 19, 67, 5, '神よ諸国の民があなたをほめたたえ諸国の民がみなあなたをほめたたえますように。'),
('JPN', '诗篇', 19, 67, 6, '大地はその実りを産み出しました。神が私たちの神が私たちを祝福してくださいますように。'),
('JPN', '诗篇', 19, 67, 7, '神が私たちを祝福してくださり地の果てのすべての者が神を恐れますように。'),
('JPN', '诗篇', 19, 68, 1, '神は立ち上がりその敵は散り失せる。神を憎む者たちは御前から逃げ去る。'),
('JPN', '诗篇', 19, 68, 2, '煙が追い払われるように追い払ってください。ろうが火の前で溶け去るように悪しき者が神の御前から滅び失せますように。'),
('JPN', '诗篇', 19, 68, 3, 'しかし正しい者たちは小躍りして喜ぶ。神の御前で喜び楽しむ。'),
('JPN', '诗篇', 19, 68, 4, '神に向かって歌い御名をほめ歌え。雲に乗って来られる方のために道を備えよ。その御名は主。その御前で喜び躍れ。'),
('JPN', '诗篇', 19, 68, 5, 'みなしごの父やもめのためのさばき人は聖なる住まいにおられる神。'),
('JPN', '诗篇', 19, 68, 6, '神は孤独な者を家に住まわせ捕らわれ人を歓喜の歌声とともに導き出される。しかし頑迷な者は焦げつく地に住む。'),
('JPN', '诗篇', 19, 68, 7, '神よあなたが御民に先立って出て行き荒れ野を進み行かれたときセラ'),
('JPN', '诗篇', 19, 68, 8, '地は揺れ動き天も雨を降らせました。シナイにおられる神の御前で。イスラエルの神である神の御前で。'),
('JPN', '诗篇', 19, 68, 9, '神よあなたは豊かな雨を注ぎ疲れたあなたのゆずりの地を堅く立てられました。'),
('JPN', '诗篇', 19, 68, 10, 'あなたの群れはその地に住みました。神よあなたはいつくしみをもって苦しむ者のために備えをされました。'),
('JPN', '诗篇', 19, 68, 11, '主はみことばを与えてくださる。良き知らせを告げる女たちは大きな群れ。'),
('JPN', '诗篇', 19, 68, 12, '軍勢の王たちは逃げまた逃げる。家に残った女たちは獲物を分け合う。'),
('JPN', '诗篇', 19, 68, 13, '羊の囲いの中に横たわるとしてもあなたがたは翼が銀でおおわれてきらめく黄金で羽がおおわれた鳩のようだ。'),
('JPN', '诗篇', 19, 68, 14, '全能者が王たちをその地で散らされたときツァルモンには雪が降っていた。'),
('JPN', '诗篇', 19, 68, 15, '神々しい山バシャンの山よ。峰を連ねた山バシャンの山よ。'),
('JPN', '诗篇', 19, 68, 16, '峰を連ねた山々よ。なぜおまえたちはねたみ見るのか。神がその住まいとして望まれたあの山を。まことに主はとこしえにそこに住まわれる。'),
('JPN', '诗篇', 19, 68, 17, '神の戦車は幾千万と数知れず。主はその中におられる。シナイの神は聖所の中に。'),
('JPN', '诗篇', 19, 68, 18, 'あなたは捕虜を引き連れていと高き所に上り人々に頑迷な者どもにさえ贈り物を与えられた。神であられる主がそこに住まわれるために。'),
('JPN', '诗篇', 19, 68, 19, 'ほむべきかな主。日々私たちの重荷を担われる方。この神こそ私たちの救い。セラ'),
('JPN', '诗篇', 19, 68, 20, '神は私たちの救いの神。死を免れるのは私の主神による。'),
('JPN', '诗篇', 19, 68, 21, '神は必ず敵の頭を打ち砕かれる。自分の罪過のうちを歩む者の毛深い脳天を。'),
('JPN', '诗篇', 19, 68, 22, '主は言われた。「わたしはバシャンから彼らを連れ帰る。海の深みからも連れ帰る。'),
('JPN', '诗篇', 19, 68, 23, 'あなたが彼らを打ち砕き足を血に染めあなたの犬たちの舌が敵の血をなめるために。」'),
('JPN', '诗篇', 19, 68, 24, '神よ人々はあなたの行列を見ました。聖所で私の王私の神の行列を。'),
('JPN', '诗篇', 19, 68, 25, '歌い手が前を進み楽人が後に続く。タンバリンを鳴らすおとめたちのただ中を。'),
('JPN', '诗篇', 19, 68, 26, '「相集って神をほめたたえよ。イスラエルの泉から主をほめたたえよ。」'),
('JPN', '诗篇', 19, 68, 27, 'そこには彼らを導く末子のベニヤミンがいる。その群れの中にはユダの君主たちゼブルンの君主たちナフタリの君主たちもいる。'),
('JPN', '诗篇', 19, 68, 28, 'あなたの神はあなたの力を現れさせました。神よあなたが私たちに示された力を。'),
('JPN', '诗篇', 19, 68, 29, 'エルサレムにあるあなたの宮のゆえに王たちはあなたに献上品を携えて来ます。'),
('JPN', '诗篇', 19, 68, 30, '葦の中の獣を叱ってください。国々の民の子牛を連れた雄牛の群れを。彼らは銀の品々を踏みつけています。戦いを喜ぶ国々の民を散らしてください。'),
('JPN', '诗篇', 19, 68, 31, '貢ぎ物はエジプトから到来しクシュは神に向かって急いで手を伸ばします。'),
('JPN', '诗篇', 19, 68, 32, '地の王国よ神に向かって歌え。主にほめ歌を歌え。セラ'),
('JPN', '诗篇', 19, 68, 33, 'いにしえから天の天を御される方に。聞け。神は御声を発せられる。力強い御声を。'),
('JPN', '诗篇', 19, 68, 34, '力を神に帰せよ。威光はイスラエルの上に御力は雲の中にある。'),
('JPN', '诗篇', 19, 68, 35, '神よあなたは恐るべき方。あなたはご自分の聖なる所におられます。イスラエルの神こそ力と勢いを御民にお与えになる方です。ほむべきかな神。'),
('JPN', '诗篇', 19, 69, 1, '神よ私をお救いください。水が喉にまで入って来ました。'),
('JPN', '诗篇', 19, 69, 2, '私は深い泥沼に沈み足がかりもありません。私は大水の底に陥り奔流が私を押し流しています。'),
('JPN', '诗篇', 19, 69, 3, '私は叫んで疲れ果て喉は渇き目も衰え果てました。私の神を待ちわびて。'),
('JPN', '诗篇', 19, 69, 4, 'ゆえなく私を憎む者は私の髪の毛よりも多く私を滅ぼそうとする者私の敵偽り者は強いのです。私は奪わなかった物さえ返さなければならないのですか。'),
('JPN', '诗篇', 19, 69, 5, '神よあなたは私の愚かさをご存じです。私の数々の罪過はあなたに隠されていません。'),
('JPN', '诗篇', 19, 69, 6, '万軍の神主よあなたを待ち望む者たちが私のために恥を見ないようにしてください。イスラエルの神よあなたを慕い求める者たちが私のために卑しめられないようにしてください。'),
('JPN', '诗篇', 19, 69, 7, 'あなたのことで私はそしりを受け恥辱が私の顔をおおっているのです。'),
('JPN', '诗篇', 19, 69, 8, '私は自分の兄弟からのけ者にされ母の子らにはよそ者となりました。'),
('JPN', '诗篇', 19, 69, 9, 'それはあなたの家を思う熱心が私を食い尽くしあなたを嘲る者たちの嘲りが私に降りかかったからです。'),
('JPN', '诗篇', 19, 69, 10, '私が断食しわが身を泣き悲しむとそれが私への嘲りのもととなりました。'),
('JPN', '诗篇', 19, 69, 11, '私が粗布を自分の衣とすると私は彼らの物笑いの種となりました。'),
('JPN', '诗篇', 19, 69, 12, '門に座る者たちは私のうわさ話をし私は酔いどれの歌になりました。'),
('JPN', '诗篇', 19, 69, 13, 'しかし私は主よあなたに祈ります。神よみこころの時にあなたの豊かな恵みにより御救いのまことをもって私に答えてください。'),
('JPN', '诗篇', 19, 69, 14, '私を泥沼から救い出し沈まないようにしてください。私を憎む者どもから大水の底から救い出してください。'),
('JPN', '诗篇', 19, 69, 15, '奔流が私を押し流さず深い淵が私を吞み込まず穴が私の上で口を閉じないようにしてください。'),
('JPN', '诗篇', 19, 69, 16, '主よ私に答えてください。いつくしみ深いあなたの恵みのゆえに。あなたのあわれみの豊かさにしたがって私に御顔を向けてください。'),
('JPN', '诗篇', 19, 69, 17, 'あなたのしもべに御顔を隠さないでください。私は苦しんでいます。早く私に答えてください。'),
('JPN', '诗篇', 19, 69, 18, '私のたましいに近づきこれを贖ってください。そうして私の敵から私を贖い出してください。'),
('JPN', '诗篇', 19, 69, 19, 'あなたはよくご存じです。私への嘲りと恥と恥辱とを。私に敵する者はみなあなたの御前にいます。'),
('JPN', '诗篇', 19, 69, 20, '嘲りが私の心を打ち砕き私はひどく病んでいます。私が同情を求めてもそれはなく慰める者たちを求めても見つけられません。'),
('JPN', '诗篇', 19, 69, 21, '彼らは私の食べ物の代わりに毒を与え私が渇いたときには酢を飲ませました。'),
('JPN', '诗篇', 19, 69, 22, '彼らの前の食卓は罠となり栄えるときに落とし穴となりますように。'),
('JPN', '诗篇', 19, 69, 23, '彼らの目が暗くなり見えなくなりますように。その腰がいつもよろけますように。'),
('JPN', '诗篇', 19, 69, 24, 'あなたの憤りを彼らの上に注いでください。燃える怒りを彼らに追いつかせてください。'),
('JPN', '诗篇', 19, 69, 25, '彼らの宿営が荒れ果てその天幕から住む者が絶えますように。'),
('JPN', '诗篇', 19, 69, 26, '彼らはあなたが打たれた者を迫害しあなたに刺し貫かれた者の痛みを言いふらします。'),
('JPN', '诗篇', 19, 69, 27, 'どうか彼らの咎に咎を加え彼らをあなたの義のうちに入れないでください。'),
('JPN', '诗篇', 19, 69, 28, '彼らがいのちの書から消し去られますように。正しい者と並べて彼らが書き記されることがありませんように。'),
('JPN', '诗篇', 19, 69, 29, '私は苦しんで痛みの中にいます。神よ御救いが私を高く上げますように。'),
('JPN', '诗篇', 19, 69, 30, '歌をもって私は神の御名をほめたたえ感謝をもって私は神をあがめます。'),
('JPN', '诗篇', 19, 69, 31, 'それは雄牛にまさって主に喜ばれます。角が生えひづめが割れた若い牛にまさって。'),
('JPN', '诗篇', 19, 69, 32, '心の貧しい者たちよ見て喜べ。神を求める者たちよあなたがたの心を生かせ。'),
('JPN', '诗篇', 19, 69, 33, '主は貧しい者に耳を傾け捕らわれたご自分の民を蔑まれない。'),
('JPN', '诗篇', 19, 69, 34, '天地よ主をほめたたえよ。海とそこにうごめくすべてのものも。'),
('JPN', '诗篇', 19, 69, 35, 'まことに神はシオンを救いユダの町々を建て直される。彼らはそこに住みそこを自分たちの所有とする。'),
('JPN', '诗篇', 19, 69, 36, '主のしもべたちの子孫はその地を受け継ぎ御名を愛する者たちはそこに住む。'),
('JPN', '诗篇', 19, 70, 1, '神よ私を救い出してください。主よ急いで私を助けに来てください。'),
('JPN', '诗篇', 19, 70, 2, '私のいのちを求める者たちが恥を見辱められますように。私のわざわいを喜ぶ者たちが退き卑しめられますように。'),
('JPN', '诗篇', 19, 70, 3, '「あはは」とあざ笑う者たちが恥をかいて立ち去りますように。'),
('JPN', '诗篇', 19, 70, 4, 'あなたを慕い求める人たちがみなあなたにあって楽しみ喜びますように。あなたの救いを愛する人たちが「神は大いなる方」といつも言いますように。'),
('JPN', '诗篇', 19, 70, 5, '私は苦しむ者貧しい者です。神よ私のところに急いでください。あなたは私の助け私を救い出す方。主よ遅れないでください。'),
('JPN', '诗篇', 19, 71, 1, '主よ私はあなたに身を避けています。私が決して恥を見ないようにしてください。'),
('JPN', '诗篇', 19, 71, 2, 'あなたの義によって私を救い助け出してください。あなたの耳を私に傾け私をお救いください。'),
('JPN', '诗篇', 19, 71, 3, '私の避け所の岩となってください。いつでもそこに入れるように。あなたは私の救いを定められました。あなたは私の巌私の砦なのです。'),
('JPN', '诗篇', 19, 71, 4, 'わが神よ私を悪者の手から助け出してください。不正を行う者や残虐な者の手から。'),
('JPN', '诗篇', 19, 71, 5, '神である主よあなたは私の望み若い日からの拠り所。'),
('JPN', '诗篇', 19, 71, 6, '私は生まれたときからあなたに抱かれています。あなたは私を母の胎から取り上げた方。私はいつもあなたを賛美しています。'),
('JPN', '诗篇', 19, 71, 7, '私は多くの人にとって奇跡と思われました。あなたが私の力強い避け所だからです。'),
('JPN', '诗篇', 19, 71, 8, '私の口にはあなたへの賛美があなたの栄えが絶えず満ちています。'),
('JPN', '诗篇', 19, 71, 9, '年老いたときも私を見放さないでください。私の力が衰え果てても見捨てないでください。'),
('JPN', '诗篇', 19, 71, 10, '私の敵は私のことを相談し私のいのちを狙う者がともに企みます。'),
('JPN', '诗篇', 19, 71, 11, '彼らは言っています。「神は彼を見捨てたのだ。追いかけて彼を捕らえよ。救い出す者はいないから。」'),
('JPN', '诗篇', 19, 71, 12, '神よ私から遠く離れないでください。わが神よ急いで私を助けてください。'),
('JPN', '诗篇', 19, 71, 13, '私をなじる者どもが恥を見て消え失せますように。私を痛めつけようとする者どもが恥辱と恥でおおわれますように。'),
('JPN', '诗篇', 19, 71, 14, 'しかし私は絶えずあなたを待ち望みいよいよ切にあなたを賛美します。'),
('JPN', '诗篇', 19, 71, 15, '私の口は絶えず語り告げます。あなたの義と救いとを。そのすべてを私は知っておりませんが。'),
('JPN', '诗篇', 19, 71, 16, '神である主よ私はあなたの力とともに行きます。あなたのただあなたの義だけを心に留めて。'),
('JPN', '诗篇', 19, 71, 17, '神よあなたは私の若いころから私を教えてくださいました。私は今なおあなたの奇しいみわざを告げ知らせています。'),
('JPN', '诗篇', 19, 71, 18, '年老いて白髪頭になったとしても神よ私を捨てないでください。私はなおも告げ知らせます。あなたの力を世に。あなたの大能のみわざを後に来るすべての者に。'),
('JPN', '诗篇', 19, 71, 19, '神よあなたの義は天にまで届きます。あなたは大いなることをなさいました。神よだれがあなたのようでしょう。'),
('JPN', '诗篇', 19, 71, 20, 'あなたは私を多くの苦難とわざわいとにあわせられましたが私を再び生き返らせ地の深みから再び引き上げてくださいます。'),
('JPN', '诗篇', 19, 71, 21, 'あなたが私の偉大さを増し振り向いて私を慰めてくださいますように。'),
('JPN', '诗篇', 19, 71, 22, '私もまた琴であなたをほめたたえます。わが神よあなたの真実を。私は竪琴に合わせてあなたにほめ歌を歌います。イスラエルの聖なる方よ。'),
('JPN', '诗篇', 19, 71, 23, '私があなたにほめ歌を歌うとき私の唇は高らかに歌います。あなたが贖い出された私のたましいも。'),
('JPN', '诗篇', 19, 71, 24, '私の舌も絶えずあなたの義を告げます。私のわざわいを求める者どもが恥を見て屈辱を受けるからです。'),
('JPN', '诗篇', 19, 72, 1, '神よあなたのさばきを王にあなたの義を王の子に与えてください。'),
('JPN', '诗篇', 19, 72, 2, '彼が義をもってあなたの民をさばきますように。公正をもってあなたの苦しむ民を。'),
('JPN', '诗篇', 19, 72, 3, '山も丘も義によって民に平和をもたらしますように。'),
('JPN', '诗篇', 19, 72, 4, '王が民の苦しむ者たちを弁護し貧しい者の子らを救い虐げる者どもを打ち砕きますように。'),
('JPN', '诗篇', 19, 72, 5, '彼らが日と月の続くかぎり代々にわたってあなたを恐れますように。'),
('JPN', '诗篇', 19, 72, 6, '王は牧草地に降る雨のように地を潤す夕立のように下って来ます。'),
('JPN', '诗篇', 19, 72, 7, '彼の代に正しい者が栄え月がなくなるときまでも豊かな平和がありますように。'),
('JPN', '诗篇', 19, 72, 8, '海から海に至るまで川から地の果てに至るまで王が統べ治めますように。'),
('JPN', '诗篇', 19, 72, 9, '砂漠の民は王の前に膝をつき王の敵はちりをなめますように。'),
('JPN', '诗篇', 19, 72, 10, 'タルシシュと島々の王たちは貢ぎを納めシェバとセバの王たちは贈り物を献げます。'),
('JPN', '诗篇', 19, 72, 11, 'こうしてすべての王が彼にひれ伏しすべての国々が彼に仕えるでしょう。'),
('JPN', '诗篇', 19, 72, 12, 'それは王が叫び求める貧しい者や助ける人のない苦しむ者を救い出すからです。'),
('JPN', '诗篇', 19, 72, 13, '王は弱い者や貧しい者をあわれみ貧しい者たちのいのちを救います。'),
('JPN', '诗篇', 19, 72, 14, '虐げと暴虐から王は彼らのいのちを贖います。王の目には彼らの血は尊いのです。'),
('JPN', '诗篇', 19, 72, 15, 'どうか王が生き続け彼にシェバの黄金が献げられますように。王のためにいつも彼らが祈り絶えず王をほめたたえますように。'),
('JPN', '诗篇', 19, 72, 16, '大地には穀物が豊かにあり山々の頂では実がレバノンのようにたわわに揺れ町の人々は地の草花のように咲き誇りますように。'),
('JPN', '诗篇', 19, 72, 17, '王の名がとこしえに続きその名が日の照るかぎり増え広がりますように。人々が彼によって祝福されすべての国々が彼をほめたたえますように。'),
('JPN', '诗篇', 19, 72, 18, 'ほむべきかな神である主イスラエルの神。ただひとり奇しいみわざを行われる方。'),
('JPN', '诗篇', 19, 72, 19, 'とこしえにほむべきかなその栄光の御名。その栄光が全地に満ちあふれますように。アーメン、アーメン。'),
('JPN', '诗篇', 19, 72, 20, 'エッサイの子ダビデの祈りは終わった。'),
('JPN', '诗篇', 19, 73, 1, 'まことに神はいつくしみ深い。イスラエルに心の清らかな人たちに。'),
('JPN', '诗篇', 19, 73, 2, 'けれどもこの私は足がつまずきそうで私の歩みは滑りかけた。'),
('JPN', '诗篇', 19, 73, 3, 'それは私が悪しき者が栄えるのを見て誇り高ぶる者をねたんだからだ。'),
('JPN', '诗篇', 19, 73, 4, '実に彼らの死には苦痛がなく彼らのからだは肥えている。'),
('JPN', '诗篇', 19, 73, 5, '人が苦労するときに彼らはそうではなくほかの人のように打たれることもない。'),
('JPN', '诗篇', 19, 73, 6, 'それゆえ高慢が彼らの首飾りとなり暴虐の衣が彼らをおおっている。'),
('JPN', '诗篇', 19, 73, 7, '彼らの目は脂肪でふくらみ心の思い描くものがあふれ出る。'),
('JPN', '诗篇', 19, 73, 8, '彼らは嘲り悪意をもって語り高い所から虐げを言う。'),
('JPN', '诗篇', 19, 73, 9, '彼らは口を天に据えその舌は地を行き巡る。'),
('JPN', '诗篇', 19, 73, 10, 'それゆえこの民はここに帰り豊かな水は彼らに汲み尽くされる。'),
('JPN', '诗篇', 19, 73, 11, 'そして彼らは言う。「どうして神が知るだろうか。いと高き方に知識があるだろうか。」'),
('JPN', '诗篇', 19, 73, 12, '見よこれが悪しき者。彼らはいつまでも安らかで富を増している。'),
('JPN', '诗篇', 19, 73, 13, 'ただ空しく私は自分の心を清め手を洗って自分を汚れなしとした。'),
('JPN', '诗篇', 19, 73, 14, '私は休みなく打たれ朝ごとに懲らしめを受けた。'),
('JPN', '诗篇', 19, 73, 15, 'もしも私が「このままを語ろう」と言っていたならきっと私はあなたの子らの世代を裏切っていたことだろう。'),
('JPN', '诗篇', 19, 73, 16, '私はこのことを理解しようとしたがそれは私の目には苦役であった。'),
('JPN', '诗篇', 19, 73, 17, 'ついに私は神の聖所に入って彼らの最期を悟った。'),
('JPN', '诗篇', 19, 73, 18, 'まことにあなたは彼らを滑りやすい所に置き彼らを滅びに突き落とされます。'),
('JPN', '诗篇', 19, 73, 19, 'ああ彼らは瞬く間に滅ぼされ突然の恐怖で滅ぼし尽くされます。'),
('JPN', '诗篇', 19, 73, 20, '目覚めの夢のように主よあなたが目を覚ますとき彼らの姿を蔑まれます。'),
('JPN', '诗篇', 19, 73, 21, '私の心が苦みに満ち私の内なる思いが突き刺されたとき'),
('JPN', '诗篇', 19, 73, 22, '私は愚かで考えもなくあなたの前で獣のようでした。'),
('JPN', '诗篇', 19, 73, 23, 'しかし私は絶えずあなたとともにいました。あなたは私の右の手をしっかりとつかんでくださいました。'),
('JPN', '诗篇', 19, 73, 24, 'あなたは私を諭して導き後には栄光のうちに受け入れてくださいます。'),
('JPN', '诗篇', 19, 73, 25, 'あなたのほかに天では私にだれがいるでしょう。地では私はだれをも望みません。'),
('JPN', '诗篇', 19, 73, 26, 'この身も心も尽き果てるでしょう。しかし神は私の心の岩とこしえに私が受ける割り当ての地。'),
('JPN', '诗篇', 19, 73, 27, '見よあなたから遠く離れている者は滅びます。あなたに背き不実を行う者をあなたはみな滅ぼされます。'),
('JPN', '诗篇', 19, 73, 28, 'しかし私にとって神のみそばにいることが幸せです。私は神である主を私の避け所としあなたのすべてのみわざを語り告げます。'),
('JPN', '诗篇', 19, 74, 1, '神よなぜいつまでも拒み御怒りをあなたの牧場の羊に燃やされるのですか。'),
('JPN', '诗篇', 19, 74, 2, 'どうか思い起こしてください。昔あなたが買い取られゆずりの民として贖われたあなたの会衆を。あなたの住まいであるシオンの山を。'),
('JPN', '诗篇', 19, 74, 3, 'あなたの足を永遠の廃墟に踏み入れてください。敵は聖所であらゆる害を加えています。'),
('JPN', '诗篇', 19, 74, 4, 'あなたに敵対する者どもはあなたの聖なる所でほえたけり自分たちのしるしをそこに掲げています。'),
('JPN', '诗篇', 19, 74, 5, 'あたかも木の茂みの中で斧を高く振り上げる者のようです。'),
('JPN', '诗篇', 19, 74, 6, '今や彼らは手斧と槌で聖所の彫り物をことごとく打ち砕き'),
('JPN', '诗篇', 19, 74, 7, 'あなたの聖所に火を放ちあなたの御名の住まいをその地まで汚しました。'),
('JPN', '诗篇', 19, 74, 8, '彼らは心の中で「彼らをことごとく征服しよう」と言い国中の神の聖所をみな焼き払いました。'),
('JPN', '诗篇', 19, 74, 9, 'もう私たちのしるしは見られません。もはや預言者もいません。いつまでそうなのかを知っている者も私たちの間にはいません。'),
('JPN', '诗篇', 19, 74, 10, '神よいつまではむかう者はそしるのですか。敵は永久に御名を侮るのですか。'),
('JPN', '诗篇', 19, 74, 11, 'なぜあなたは御手を右の御手を引いておられるのですか。その手を懐から出して彼らを滅ぼし尽くしてください。'),
('JPN', '诗篇', 19, 74, 12, '神は昔から私の王この地において救いのみわざを行う方。'),
('JPN', '诗篇', 19, 74, 13, 'あなたは御力をもって海を打ち破りその水の上の竜の頭を砕かれました。'),
('JPN', '诗篇', 19, 74, 14, 'あなたはレビヤタンの頭を踏みにじり砂漠に住むものたちの餌食とされました。'),
('JPN', '诗篇', 19, 74, 15, 'あなたは泉と谷を切り開き流れの絶えない川を涸らされました。'),
('JPN', '诗篇', 19, 74, 16, '昼はあなたのもの夜もあなたのもの。あなたは月と太陽を備えられました。'),
('JPN', '诗篇', 19, 74, 17, 'あなたは地のすべての境を定め夏と冬を造られました。'),
('JPN', '诗篇', 19, 74, 18, '主よどうか心に留めてください。敵がそしり愚かな民が御名を侮っていることを。'),
('JPN', '诗篇', 19, 74, 19, 'あなたの山鳩のいのちを獣に引き渡さないでください。あなたの悩む者たちのいのちを永久に忘れないでください。'),
('JPN', '诗篇', 19, 74, 20, 'どうか契約に目を留めてください。地の暗い所は暴虐の巣ですから。'),
('JPN', '诗篇', 19, 74, 21, '虐げられる者が辱めを受けて帰されることがなく苦しむ者貧しい者が御名をほめたたえますように。'),
('JPN', '诗篇', 19, 74, 22, '神よ立ち上がりご自分の言い分を立ててください。愚か者が休みなくあなたをそしっていることを心に留めてください。'),
('JPN', '诗篇', 19, 74, 23, '忘れないでください。あなたに敵対する者の声をあなたに向かい立つ者どもが絶えずあげる叫びを。'),
('JPN', '诗篇', 19, 75, 1, '私たちはあなたに感謝します。神よ私たちは感謝します。あなたの御名は近くにありあなたの奇しいみわざが語り告げられています。'),
('JPN', '诗篇', 19, 75, 2, '「わたしが定めの時を決めわたし自ら公正にさばく。'),
('JPN', '诗篇', 19, 75, 3, '地とそこに住むすべての者が揺らぐときわたしが地の柱を堅く立てる。セラ'),
('JPN', '诗篇', 19, 75, 4, 'わたしは誇る者には『誇るな』と言い悪者どもには『角を上げるな。'),
('JPN', '诗篇', 19, 75, 5, 'おまえたちの角を高く上げるな。横柄な態度で語るな』と言う。」'),
('JPN', '诗篇', 19, 75, 6, '高く上げることは東からでもなく西からでもなく荒野からでもない。'),
('JPN', '诗篇', 19, 75, 7, 'まことに神こそさばき主。ある者を低くしある者を高く上げられる。'),
('JPN', '诗篇', 19, 75, 8, '主の御手には杯があり混ぜ合わされた泡立つぶどう酒が満ちている。主がこれを注ぎ出されると実にすべて地の悪者どもはそれを飲みかすまで飲み干す。'),
('JPN', '诗篇', 19, 75, 9, 'しかし私はとこしえまでもみわざを告げます。ヤコブの神にほめ歌を歌います。'),
('JPN', '诗篇', 19, 75, 10, '私は悪者どもの角をことごとく切り捨てます。正しい者の角は高く上げられます。'),
('JPN', '诗篇', 19, 76, 1, '神はユダにご自分を示される。イスラエルにその御名の偉大さを。'),
('JPN', '诗篇', 19, 76, 2, 'その仮庵はサレムにその住まいはシオンにある。'),
('JPN', '诗篇', 19, 76, 3, '神はそこで弓の火矢を砕かれる。盾と剣も戦いも。セラ'),
('JPN', '诗篇', 19, 76, 4, 'あなたは輝かしく獲物で満ちる山々にまさって威厳があります。'),
('JPN', '诗篇', 19, 76, 5, '剛胆な者たちは略奪され深い眠りに陥りました。どの勇士たちにも手の施しようがありませんでした。'),
('JPN', '诗篇', 19, 76, 6, 'ヤコブの神よあなたが叱りつけると戦車も馬も倒れ伏しました。'),
('JPN', '诗篇', 19, 76, 7, 'あなたは実にあなたは恐ろしい方。お怒りになればだれが御前に立てるでしょう。'),
('JPN', '诗篇', 19, 76, 8, '天からあなたの宣告が聞こえると地は恐れて沈黙しました。'),
('JPN', '诗篇', 19, 76, 9, '神がさばきのために地のすべての貧しい者たちを救うために立ち上がられたそのときに。セラ'),
('JPN', '诗篇', 19, 76, 10, 'まことに人の憤りまでもがあなたをたたえあなたはあふれ出た憤りを身に帯びられます。'),
('JPN', '诗篇', 19, 76, 11, 'あなたがたの神主に誓いを立てそれを果たせ。主の周りにいる者はみな恐るべき方に贈り物を献げよ。'),
('JPN', '诗篇', 19, 76, 12, '主は君主たちの霊を刈り取られる。地の王たちにとって恐るべき方。'),
('JPN', '诗篇', 19, 77, 1, '私は神に声をあげて叫ぶ。私が神に声をあげると神は聞いてくださる。'),
('JPN', '诗篇', 19, 77, 2, '苦難の日に私は主を求め夜もすがらたゆまず手を差し伸ばした。けれども私のたましいは慰めを拒んだ。'),
('JPN', '诗篇', 19, 77, 3, '神を思い起こして私は嘆き悲しむ。思いを潜めて私の霊は衰え果てる。セラ'),
('JPN', '诗篇', 19, 77, 4, 'あなたは私のまぶたを閉じさせません。私の心は乱れてもの言うこともできません。'),
('JPN', '诗篇', 19, 77, 5, '私は昔の日々遠い昔の年月について考えました。'),
('JPN', '诗篇', 19, 77, 6, '夜には私の歌を思い起こし自分の心と語り合い私の霊は探り求めます。'),
('JPN', '诗篇', 19, 77, 7, '「主はいつまでも拒まれるのか。もう決して受け入れてくださらないのか。'),
('JPN', '诗篇', 19, 77, 8, '主の恵みはとこしえに尽き果てたのか。約束のことばは永久に絶えたのか。'),
('JPN', '诗篇', 19, 77, 9, '神はいつくしみを忘れられたのか。怒ってあわれみを閉ざされたのか。」セラ'),
('JPN', '诗篇', 19, 77, 10, '私はこう言った。「私が弱り果てたのはいと高き方の右の手が変わったからだ」と。'),
('JPN', '诗篇', 19, 77, 11, '私は主のみわざを思い起こします。昔からのあなたの奇しいみわざを思い起こします。'),
('JPN', '诗篇', 19, 77, 12, '私はあなたのなさったすべてのことを思い巡らしあなたのみわざを静かに考えます。'),
('JPN', '诗篇', 19, 77, 13, '神よあなたの道は聖です。私たちの神のように大いなる神がいるでしょうか。'),
('JPN', '诗篇', 19, 77, 14, 'あなたは奇しいみわざを行われる神。国々の民の中で御力を現される方。'),
('JPN', '诗篇', 19, 77, 15, 'あなたは御腕をもって贖われました。ご自分の民ヤコブとヨセフの子らを。セラ'),
('JPN', '诗篇', 19, 77, 16, '神よ水はあなたを見ました。水はあなたを見てわななきました。大いなる水も震え上がりました。'),
('JPN', '诗篇', 19, 77, 17, '雨雲は水を注ぎ出し雷雲は雷をとどろかしあなたの矢もひらめき飛びました。'),
('JPN', '诗篇', 19, 77, 18, 'あなたの雷の声は戦車のように鳴り稲妻は世界を照らし地は震え揺れ動きました。'),
('JPN', '诗篇', 19, 77, 19, 'あなたの道は海の中。その通り道は大水の中。あなたの足跡を見た者はいませんでした。'),
('JPN', '诗篇', 19, 77, 20, 'あなたはモーセとアロンの手によってご自分の民を羊の群れのように導かれました。'),
('JPN', '诗篇', 19, 78, 1, '私の民よ私の教えを耳に入れ私の口のことばに耳を傾けよ。'),
('JPN', '诗篇', 19, 78, 2, '私は口を開いてたとえ話を昔からの謎を語ろう。'),
('JPN', '诗篇', 19, 78, 3, 'それは私たちが聞いて知っていること。私たちの先祖が語ってくれたこと。'),
('JPN', '诗篇', 19, 78, 4, 'それを私たちは息子たちに隠さず後の時代に語り告げよう。主の誉れを主が行われた力ある奇しいみわざを。'),
('JPN', '诗篇', 19, 78, 5, '主はヤコブのうちにさとしを置きイスラエルのうちにみおしえを定め私たちの先祖に命じてその子らに教えるようにされた。'),
('JPN', '诗篇', 19, 78, 6, '後の世代の者生まれてくる子らがこれを知りさらに彼らがその子らにまた語り告げるため'),
('JPN', '诗篇', 19, 78, 7, '彼らが神に信頼し神のみわざを忘れずその命令を守るために。'),
('JPN', '诗篇', 19, 78, 8, '先祖たちのように強情で逆らう世代心定まらない世代霊が神に忠実でない世代とならないために。'),
('JPN', '诗篇', 19, 78, 9, 'エフライムの人々は弓を射る者であったが戦いの日には退却した。'),
('JPN', '诗篇', 19, 78, 10, '彼らは神の契約を守らず神のおしえに従って歩むことを拒み'),
('JPN', '诗篇', 19, 78, 11, '神の数々のみわざを忘れてしまった。神が見せてくださった多くの不思議を。'),
('JPN', '诗篇', 19, 78, 12, '神は奇しいみわざを彼らの先祖の前でエジプトの地ツォアンの野で行われた。'),
('JPN', '诗篇', 19, 78, 13, '海を分けて彼らを通らせ堰のように水を立てられた。'),
('JPN', '诗篇', 19, 78, 14, '昼は雲で彼らを導かれた。夜は夜通し炎の光で。'),
('JPN', '诗篇', 19, 78, 15, '荒野で神は岩を割り大いなる深淵の水を豊かに飲ませてくださった。'),
('JPN', '诗篇', 19, 78, 16, 'あふれる流れを岩からほとばしらせ水を豊かな川のように流れさせてくださった。'),
('JPN', '诗篇', 19, 78, 17, 'けれども彼らはなおも神に罪を犯し砂漠でいと高き方に逆らった。'),
('JPN', '诗篇', 19, 78, 18, '彼らは心のうちで神を試み欲に任せて食べ物を求めた。'),
('JPN', '诗篇', 19, 78, 19, 'そのとき彼らは神に逆らって言った。「荒野で食事を備えることが神にできるのか。'),
('JPN', '诗篇', 19, 78, 20, '確かに神が岩を打たれると水が湧き出て流れがあふれた。だが神はパンも与えることができるのか。民のために肉を用意できるのか。」'),
('JPN', '诗篇', 19, 78, 21, 'それゆえ主はこれを聞いて激しく怒られた。火はヤコブに向かって燃え怒りはイスラエルに向かって燃え上がった。'),
('JPN', '诗篇', 19, 78, 22, 'これは彼らが神を信じず御救いに信頼しなかったからである。'),
('JPN', '诗篇', 19, 78, 23, '神は上の雲に命じて天の戸を開き'),
('JPN', '诗篇', 19, 78, 24, '彼らの上に食べ物としてマナを降らせ天の穀物を彼らに与えられた。'),
('JPN', '诗篇', 19, 78, 25, 'それで人々は御使いのパンを食べた。神は満ちたりるほど食物を送られた。'),
('JPN', '诗篇', 19, 78, 26, '神は東風を天に起こし御力をもって南風を吹かせられた。'),
('JPN', '诗篇', 19, 78, 27, '彼らの上に肉をちりのように翼のある鳥を海の砂のように降らせ'),
('JPN', '诗篇', 19, 78, 28, 'それを宿営の中住まいの周りに落とされた。'),
('JPN', '诗篇', 19, 78, 29, '彼らは食べ十分に満ち足りた。こうして彼らが欲望を満たすままにされた。'),
('JPN', '诗篇', 19, 78, 30, '彼らがその欲望を手放さずまだ食べ物が口にあるうちに'),
('JPN', '诗篇', 19, 78, 31, '神の怒りが彼らに向かって燃え上がり彼らのうちの最も頑丈な者たちを殺しイスラエルの若い男たちを打ちのめした。'),
('JPN', '诗篇', 19, 78, 32, 'これらすべてにもかかわらず彼らはなおも罪を犯し神の奇しいみわざを信じなかった。'),
('JPN', '诗篇', 19, 78, 33, 'それで神は彼らの日を一息のうちに彼らの齢を突然の恐怖のうちに終わらせられた。'),
('JPN', '诗篇', 19, 78, 34, '神が彼らを殺されると彼らは神を尋ね求め立ち返り神を切に求めた。'),
('JPN', '诗篇', 19, 78, 35, '彼らは思い出した。神が自分たちの岩でありいと高き神が自分たちを贖う方であることを。'),
('JPN', '诗篇', 19, 78, 36, 'しかし彼らはその口で神に媚び舌で神に偽りを言った。'),
('JPN', '诗篇', 19, 78, 37, '彼らの心は神に堅く立たず神の契約に忠実でなかった。'),
('JPN', '诗篇', 19, 78, 38, 'しかし神はあわれみ深く彼らの咎を赦して滅ぼされなかった。怒りを何度も抑えて憤りのすべてをかき立てられることはなかった。'),
('JPN', '诗篇', 19, 78, 39, '神は心に留めておられた。彼らが肉にすぎないことを。吹けば戻らない風であることを。'),
('JPN', '诗篇', 19, 78, 40, '幾たび彼らは荒野で神に逆らい荒れ地で神を悲しませたことか。'),
('JPN', '诗篇', 19, 78, 41, '彼らは繰り返し神を試みイスラエルの聖なる方の心を痛めた。'),
('JPN', '诗篇', 19, 78, 42, '彼らは神の力も神が敵から贖い出してくださった日も思い起こさなかった。'),
('JPN', '诗篇', 19, 78, 43, '神がエジプトでしるしをツォアンの野で奇跡を行われたことを。'),
('JPN', '诗篇', 19, 78, 44, '神が大河を血に変えられたのでその流れは飲めなくなった。'),
('JPN', '诗篇', 19, 78, 45, '神は彼らにあぶの群れを送り蛙を送って彼らを食い尽くされた。'),
('JPN', '诗篇', 19, 78, 46, 'また彼らの作物を若いいなごに彼らの勤労の実をいなごに与えられた。'),
('JPN', '诗篇', 19, 78, 47, '神は雹で彼らのぶどうの木を稲妻でいちじく桑の木を滅ぼされた。'),
('JPN', '诗篇', 19, 78, 48, '彼らの家畜を雹に家畜の群れを疫病に渡された。'),
('JPN', '诗篇', 19, 78, 49, '神は彼らの上に燃える怒りを送られた。激しい怒りと憤りと苦しみを。わざわいをもたらす御使いたちを。'),
('JPN', '诗篇', 19, 78, 50, '神は御怒りに道を備え彼ら自身に死を免れさせず彼らのいのちを疫病に渡された。'),
('JPN', '诗篇', 19, 78, 51, '神はエジプトですべての長子を打ち殺された。ハムの天幕で彼らの力の初穂を。'),
('JPN', '诗篇', 19, 78, 52, '神はご自分の民を羊の群れのように連れ出し家畜の群れのように荒野の中を連れて行かれた。'),
('JPN', '诗篇', 19, 78, 53, '神が安らかに導かれたので彼らは恐れなかった。しかし彼らの敵は海がおおい隠した。'),
('JPN', '诗篇', 19, 78, 54, 'こうして神は彼らをご自分の聖なる国に右の御手で造ったこの山に連れて来られた。'),
('JPN', '诗篇', 19, 78, 55, 'また彼らの前から異邦の民を追い出しその地を相続の地として彼らに分け与えイスラエル諸族をそれぞれの天幕に住まわせた。'),
('JPN', '诗篇', 19, 78, 56, 'けれども彼らはいと高き神を試み神に逆らいそのさとしを守らなかった。'),
('JPN', '诗篇', 19, 78, 57, '彼らは元に戻り先祖たちのように裏切りたるんだ弓の矢のようにそれて行った。'),
('JPN', '诗篇', 19, 78, 58, 'また高き所を築いて神の怒りを引き起こし刻んだ像で神のねたみを起こさせた。'),
('JPN', '诗篇', 19, 78, 59, '神は聞いて激しく怒りイスラエルを激しく退けられた。'),
('JPN', '诗篇', 19, 78, 60, 'シロの御住まい人々の間に張ったその幕屋を見放して'),
('JPN', '诗篇', 19, 78, 61, '御力を捕らえられるに任せ御栄えを敵の手に渡された。'),
('JPN', '诗篇', 19, 78, 62, '神はご自分の民を剣に引き渡しゆずりの民に対して激しく怒られた。'),
('JPN', '诗篇', 19, 78, 63, '火は若い男たちを食い尽くし若い女たちは婚礼の歌を歌わなかった。'),
('JPN', '诗篇', 19, 78, 64, '祭司たちは剣に倒れやもめたちは泣くこともできなかった。'),
('JPN', '诗篇', 19, 78, 65, 'そのとき主は眠りから目を覚まされた。ぶどう酒の酔いから覚めた勇士のように。'),
('JPN', '诗篇', 19, 78, 66, '主はその敵を打って退け彼らに永遠のそしりを与えられた。'),
('JPN', '诗篇', 19, 78, 67, '主はヨセフの天幕を捨てエフライム族を選ばず'),
('JPN', '诗篇', 19, 78, 68, 'ユダの部族を選ばれた。主が愛されたシオンの山を。'),
('JPN', '诗篇', 19, 78, 69, '主はその聖所を高い天のように建てられた。ご自分が永遠に基を据えた地のように。'),
('JPN', '诗篇', 19, 78, 70, '主はしもべダビデを選び羊の囲いから召し出された。'),
('JPN', '诗篇', 19, 78, 71, '乳を飲ませる雌羊の番から彼を連れて来て御民ヤコブをご自分のゆずりの民イスラエルを牧するようにされた。'),
('JPN', '诗篇', 19, 78, 72, '彼は全き心で彼らを牧し英知の手で彼らを導いた。'),
('JPN', '诗篇', 19, 79, 1, '神よ国々はあなたのゆずりの地に侵入しあなたの聖なる宮を汚しエルサレムを瓦礫の山としました。'),
('JPN', '诗篇', 19, 79, 2, '彼らはあなたのしもべたちの屍を空の鳥の餌食としあなたにある敬虔な人たちの肉を地の獣に与え'),
('JPN', '诗篇', 19, 79, 3, '彼らの血をエルサレムの周りに水のように注ぎ出しました。彼らを葬る者もいません。'),
('JPN', '诗篇', 19, 79, 4, '私たちは隣人のそしりの的となり周りの者に嘲られ笑いぐさとなりました。'),
('JPN', '诗篇', 19, 79, 5, '主よいつまでですか。とこしえにあなたはお怒りになるのですか。いつまであなたのねたみは火のように燃えるのですか。'),
('JPN', '诗篇', 19, 79, 6, 'どうかあなたの激しい憤りを注いでください。あなたを知らない国々に。御名を呼び求めない王国の上に。'),
('JPN', '诗篇', 19, 79, 7, '彼らはヤコブを食い尽くしその住む所を荒らしたのです。'),
('JPN', '诗篇', 19, 79, 8, '先祖たちの咎を私たちのものとして思い出さないでください。あなたのあわれみが速やかに私たちを迎えるようにしてください。私たちはひどくおとしめられているのです。'),
('JPN', '诗篇', 19, 79, 9, '私たちの救いの神よ私たちを助けてください。御名の栄光のために。私たちを救い出し私たちの罪をお赦しください。御名のゆえに。'),
('JPN', '诗篇', 19, 79, 10, 'なぜ国々は「彼らの神はどこにいるのか」と言うのでしょう。あなたのしもべたちの流された血の復讐が私たちの目の前で国々に果たされますように。'),
('JPN', '诗篇', 19, 79, 11, '捕らわれ人のうめきが御前に届きますように。あなたの大いなる力のゆえに死に定められた人々を生きながらえさせてください。'),
('JPN', '诗篇', 19, 79, 12, '主よあなたをそしったそのそしりの七倍を私たちの隣人らの胸に返してください。'),
('JPN', '诗篇', 19, 79, 13, '私たちはあなたの民あなたの牧場の羊です。私たちはとこしえまでもあなたに感謝し代々限りなくあなたの誉れを語り告げます。'),
('JPN', '诗篇', 19, 80, 1, 'イスラエルの牧者よ聞いてください。ヨセフを羊の群れのように導かれる方よ光を放ってください。ケルビムの上に座しておられる方よ。'),
('JPN', '诗篇', 19, 80, 2, 'エフライムとベニヤミンとマナセの前で御力を呼び覚まし私たちを救いに来てください。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '诗篇', 19, 80, 3, '神よ私たちを元に戻し御顔を照り輝かせてください。そうすれば私たちは救われます。'),
('JPN', '诗篇', 19, 80, 4, '万軍の神主よいつまであなたの民の祈りに怒りを燃やされるのですか。'),
('JPN', '诗篇', 19, 80, 5, 'あなたは彼らに涙のパンを食べさせあふれる涙を飲ませられました。'),
('JPN', '诗篇', 19, 80, 6, 'あなたは私たちを隣人らの争いの的とし私たちの敵は私たちを嘲っています。'),
('JPN', '诗篇', 19, 80, 7, '万軍の神よ私たちを元に戻し御顔を照り輝かせてください。そうすれば私たちは救われます。'),
('JPN', '诗篇', 19, 80, 8, 'あなたはエジプトからぶどうの木を引き抜き異邦の民を追い出してそれを植えられました。'),
('JPN', '诗篇', 19, 80, 9, 'その木のためにあなたが地を整えられたのでそれは深く根を張り地の全面に広がりました。'),
('JPN', '诗篇', 19, 80, 10, '山々もその影におおわれました。神の杉の木もその大枝に。'),
('JPN', '诗篇', 19, 80, 11, 'ぶどうの木はその枝を海にまで若枝をあの川にまで伸ばしました。'),
('JPN', '诗篇', 19, 80, 12, 'なぜあなたはその石垣を破り道を行くすべての者がその実を摘み取るままにされるのですか。'),
('JPN', '诗篇', 19, 80, 13, '林の猪はこれを食い荒らし野に群がるものもこれを食らっています。'),
('JPN', '诗篇', 19, 80, 14, '万軍の神よどうか帰って来てください。天から目を注ぎご覧になってください。このぶどうの木を顧みてください。'),
('JPN', '诗篇', 19, 80, 15, 'あなたの右の手が植えた苗とご自分のために強くされた枝とを。'),
('JPN', '诗篇', 19, 80, 16, 'それは火で焼かれ切り倒されています。民は御顔のとがめによって滅びています。'),
('JPN', '诗篇', 19, 80, 17, 'あなたの右にいる人の上に御手がご自分のため強くされた人の子の上に御手がありますように。'),
('JPN', '诗篇', 19, 80, 18, '私たちはあなたから離れ去りません。私たちを生かしてください。私たちはあなたの御名を呼び求めます。'),
('JPN', '诗篇', 19, 80, 19, '万軍の神主よ私たちを元に戻し御顔を照り輝かせてください。そうすれば私たちは救われます。'),
('JPN', '诗篇', 19, 81, 1, '喜び歌え私たちの力なる神に。喜び叫べヤコブの神に。'),
('JPN', '诗篇', 19, 81, 2, 'ほめ歌を歌いタンバリンを打ち鳴らせ。麗しい音色の竪琴を琴に合わせてかき鳴らせ。'),
('JPN', '诗篇', 19, 81, 3, '新月と満月に角笛を吹き鳴らせ。私たちの祭りの日に。'),
('JPN', '诗篇', 19, 81, 4, 'これはイスラエルのためのおきてヤコブの神のための定めである。'),
('JPN', '诗篇', 19, 81, 5, '神がエジプトの地に向かって出て行かれたときヨセフのうちにそれをさとしとして授けられた。私はまだ知らなかったことばを聞いた。'),
('JPN', '诗篇', 19, 81, 6, '「わたしは彼の肩から重荷を除き彼の手を荷かごから離してやった。'),
('JPN', '诗篇', 19, 81, 7, '苦しみの中であなたは叫びわたしはあなたを助け出した。わたしは雷の隠れ場からあなたに答えメリバの水のほとりであなたを試した。セラ'),
('JPN', '诗篇', 19, 81, 8, '聞けわが民よ。わたしはあなたを戒めよう。イスラエルよわたしの言うことをよく聞け。'),
('JPN', '诗篇', 19, 81, 9, 'あなたのうちに異なる神があってはならない。異国の神を拝んではならない。'),
('JPN', '诗篇', 19, 81, 10, 'わたしはあなたの神主である。わたしがあなたをエジプトの地から連れ上った。あなたの口を大きく開けよ。わたしがそれを満たそう。'),
('JPN', '诗篇', 19, 81, 11, 'しかしわたしの民はわたしの声を聞かずイスラエルはわたしに服従しなかった。'),
('JPN', '诗篇', 19, 81, 12, 'それでわたしは彼らを頑なな心のままに任せ自分たちのはかりごとのままに歩ませた。'),
('JPN', '诗篇', 19, 81, 13, 'ああただわたしの民がわたしに聞き従いイスラエルがわたしの道を歩んでいたなら。'),
('JPN', '诗篇', 19, 81, 14, 'わたしはただちに彼らの敵を征服し彼らに逆らう者に手を下したのに。'),
('JPN', '诗篇', 19, 81, 15, '主を憎む者どもは主にへつらうが彼らの刑罰の時は永遠にまで至る。'),
('JPN', '诗篇', 19, 81, 16, 'しかし主は最良の小麦を御民に食べさせる。わたしは岩から滴る蜜であなたを満ち足らせる。」'),
('JPN', '诗篇', 19, 82, 1, '神は神の会議の中に立ち神々のただ中でさばきを下す。'),
('JPN', '诗篇', 19, 82, 2, 'いつまでおまえたちは不正をもってさばき悪しき者たちの味方をするのか。セラ'),
('JPN', '诗篇', 19, 82, 3, '弱い者とみなしごのためにさばき苦しむ者と乏しい者の正しさを認めよ。'),
('JPN', '诗篇', 19, 82, 4, '弱い者と貧しい者を助け出し悪しき者たちの手から救い出せ。'),
('JPN', '诗篇', 19, 82, 5, '彼らは知らない。また悟らない。彼らは暗闇の中を歩き回る。地の基はことごとく揺らいでいる。'),
('JPN', '诗篇', 19, 82, 6, 'わたしは言った。「おまえたちは神々だ。みないと高き者の子らだ。'),
('JPN', '诗篇', 19, 82, 7, 'にもかかわらずおまえたちは人のように死に君主たちの一人のように倒れるのだ。」'),
('JPN', '诗篇', 19, 82, 8, '神よ立ち上がって地をさばいてください。あなたがすべての国々をご自分のものとしておられるからです。'),
('JPN', '诗篇', 19, 83, 1, '神よ沈黙していないでください。黙っていないでください。神よ黙り続けないでください。'),
('JPN', '诗篇', 19, 83, 2, 'ご覧ください。あなたの敵が騒ぎ立ちあなたを憎む者どもが頭をもたげています。'),
('JPN', '诗篇', 19, 83, 3, '彼らはあなたの民に対して悪賢いはかりごとをめぐらしあなたにかくまわれている者たちに悪を企んでいます。'),
('JPN', '诗篇', 19, 83, 4, '彼らは言っています。「さあ彼らの国を消し去ってイスラエルの名がもはや覚えられないようにしよう。」'),
('JPN', '诗篇', 19, 83, 5, '彼らは心を一つにして悪を企みあなたに逆らって盟約を結んでいます。'),
('JPN', '诗篇', 19, 83, 6, 'エドムの天幕の民とイシュマエル人モアブとハガル人'),
('JPN', '诗篇', 19, 83, 7, 'ゲバルとアンモンそれにアマレクペリシテさらにはツロの住民。'),
('JPN', '诗篇', 19, 83, 8, 'アッシリアも彼らにくみし彼らはロトの子らの腕となりました。セラ'),
('JPN', '诗篇', 19, 83, 9, 'どうか彼らをミディアンやキション川でのシセラとヤビンのようにしてください。'),
('JPN', '诗篇', 19, 83, 10, 'エン・ドルで滅ぼし尽くされ土地の肥やしとなった者たちのように。'),
('JPN', '诗篇', 19, 83, 11, '彼らの貴族たちをオレブとゼエブのようにし彼らの君主たちをみなゼバフとツァルムナのようにしてください。'),
('JPN', '诗篇', 19, 83, 12, '彼らは言っています。「神の牧場を奪ってわれわれのものとしよう。」'),
('JPN', '诗篇', 19, 83, 13, '私の神よ彼らを風の前に吹き転がされる藁のようにしてください。'),
('JPN', '诗篇', 19, 83, 14, '林を燃やす火のように山々を焼き尽くす炎のように'),
('JPN', '诗篇', 19, 83, 15, 'そのようにあなたの疾風で彼らを追いあなたの嵐で恐れおののかせてください。'),
('JPN', '诗篇', 19, 83, 16, '彼らの顔を恥で満たしてください。主よ彼らが御名を捜し回りますように。'),
('JPN', '诗篇', 19, 83, 17, '彼らがいつまでも恥を見て恐れおののきますように。辱めを受けて滅びますように。'),
('JPN', '诗篇', 19, 83, 18, 'こうして彼らが知りますように。その名が主であるあなただけが全地の上におられるいと高き方であることを。'),
('JPN', '诗篇', 19, 84, 1, '万軍の主よあなたの住まいはなんと慕わしいことでしょう。'),
('JPN', '诗篇', 19, 84, 2, '私のたましいは主の大庭を恋い慕って絶え入るばかりです。私の心も身も生ける神に喜びの歌を歌います。'),
('JPN', '诗篇', 19, 84, 3, '雀さえも住みかを燕もひなを入れる巣をあなたの祭壇のところに得ます。万軍の主私の王私の神よ。'),
('JPN', '诗篇', 19, 84, 4, 'なんと幸いなことでしょう。あなたの家に住む人たちは。彼らはいつもあなたをほめたたえています。セラ'),
('JPN', '诗篇', 19, 84, 5, 'なんと幸いなことでしょう。その力があなたにあり心の中にシオンへの大路のある人は。'),
('JPN', '诗篇', 19, 84, 6, '彼らは涙の谷を過ぎるときもそこを泉の湧く所とします。初めの雨もそこを大いなる祝福でおおいます。'),
('JPN', '诗篇', 19, 84, 7, '彼らは力から力へと進みシオンで神の御前に現れます。'),
('JPN', '诗篇', 19, 84, 8, '万軍の神主よ私の祈りを聞いてください。ヤコブの神よ耳を傾けてください。セラ'),
('JPN', '诗篇', 19, 84, 9, '神よわれらの盾をご覧ください。あなたに油注がれた者の顔に目を留めてください。'),
('JPN', '诗篇', 19, 84, 10, 'まことにあなたの大庭にいる一日は千日にまさります。私は悪の天幕に住むよりは私の神の家の門口に立ちたいのです。'),
('JPN', '诗篇', 19, 84, 11, 'まことに神である主は太陽また盾。主は恵みと栄光を与え誠実に歩む者に良いものを拒まれません。'),
('JPN', '诗篇', 19, 84, 12, '万軍の主よなんと幸いなことでしょう。あなたに信頼する人は。'),
('JPN', '诗篇', 19, 85, 1, '主よあなたはご自分の地に恵みを施しヤコブを元どおりにされます。'),
('JPN', '诗篇', 19, 85, 2, 'あなたは御民の咎を担いすべての罪をおおってくださいます。セラ'),
('JPN', '诗篇', 19, 85, 3, 'あなたは激しい怒りをすべて収め燃える御怒りから身を引かれます。'),
('JPN', '诗篇', 19, 85, 4, '帰って来てください。私たちのところに。私たちの救いの神。私たちへの御怒りをやめてください。'),
('JPN', '诗篇', 19, 85, 5, 'あなたはとこしえに私たちに対して怒られるのですか。代々に至るまで御怒りを引き延ばされるのですか。'),
('JPN', '诗篇', 19, 85, 6, 'あなたは帰って来て私たちを生かしてくださらないのですか。あなたの民があなたにあって喜ぶために。'),
('JPN', '诗篇', 19, 85, 7, '主よ私たちにお示しください。あなたの恵みを。私たちにお与えください。あなたの救いを。'),
('JPN', '诗篇', 19, 85, 8, '聞かせてください。主である神の仰せを。主は御民に主にある敬虔な人たちに平和を告げられます。彼らが再び愚かさに戻らないように。'),
('JPN', '诗篇', 19, 85, 9, '確かに御救いは主を恐れる者たちに近い。それは栄光が私たちの地にとどまるためです。'),
('JPN', '诗篇', 19, 85, 10, '恵みとまことはともに会い義と平和は口づけします。'),
('JPN', '诗篇', 19, 85, 11, 'まことは地から生え出で義は天から見下ろします。'),
('JPN', '诗篇', 19, 85, 12, '主が良いものを下さるので私たちの大地は産物を産み出します。'),
('JPN', '诗篇', 19, 85, 13, '義は主の御前に先立って行き主の足跡を道とします。'),
('JPN', '诗篇', 19, 86, 1, '主よ耳を傾けて私に答えてください。私は苦しみ貧しいのです。'),
('JPN', '诗篇', 19, 86, 2, '私のたましいをお守りください。私は神を恐れる者です。あなたのしもべをお救いください。あなたは私の神。私はあなたに信頼します。'),
('JPN', '诗篇', 19, 86, 3, '主よ私をあわれんでください。絶えず私はあなたを呼んでいます。'),
('JPN', '诗篇', 19, 86, 4, 'このしもべのたましいを喜ばせてください。主よ私のたましいはあなたを仰ぎ求めています。'),
('JPN', '诗篇', 19, 86, 5, '主よまことにあなたはいつくしみ深く赦しに富みあなたを呼び求める者すべてに恵み豊かであられます。'),
('JPN', '诗篇', 19, 86, 6, '主よ私の祈りに耳を傾け私の願いの声を心に留めてください。'),
('JPN', '诗篇', 19, 86, 7, '苦難の日に私はあなたを呼び求めます。あなたが私に答えてくださるからです。'),
('JPN', '诗篇', 19, 86, 8, '主よ神々のうちであなたに並ぶ者はなくあなたのみわざに比べられるものはありません。'),
('JPN', '诗篇', 19, 86, 9, '主よあなたが造られたすべての国々はあなたの御前に来て伏し拝みあなたの御名をあがめます。'),
('JPN', '诗篇', 19, 86, 10, 'まことにあなたは大いなる方奇しいみわざを行われる方。あなただけが神です。'),
('JPN', '诗篇', 19, 86, 11, '主よあなたの道を私に教えてください。私はあなたの真理のうちを歩みます。私の心を一つにしてください。御名を恐れるように。'),
('JPN', '诗篇', 19, 86, 12, 'わが神主よ私は心を尽くしてあなたに感謝しとこしえまでもあなたの御名をあがめます。'),
('JPN', '诗篇', 19, 86, 13, 'あなたの恵みは私の上に大きくあなたが私のたましいをよみの深みから救い出してくださるからです。'),
('JPN', '诗篇', 19, 86, 14, '神よ高ぶる者どもは私に向かい立ち横暴な者の群れが私のいのちを求めます。彼らはあなたを前にしていません。'),
('JPN', '诗篇', 19, 86, 15, 'しかし主よあなたはあわれみ深く情け深い神。怒るのに遅く恵みとまことに富んでおられます。'),
('JPN', '诗篇', 19, 86, 16, '御顔を私に向け私をあわれんでください。あなたのしもべに御力を与えあなたのはしための子をお救いください。'),
('JPN', '诗篇', 19, 86, 17, '私にいつくしみのしるしを行ってください。そうすれば私を憎む者どもは見て恥を受けます。主よあなたが私を助け慰めてくださるからです。'),
('JPN', '诗篇', 19, 87, 1, '主の礎は聖なる山にある。'),
('JPN', '诗篇', 19, 87, 2, '主はシオンの門を愛される。ヤコブのどの住まいよりも。'),
('JPN', '诗篇', 19, 87, 3, '神の都よあなたについて誉れあることが語られている。セラ'),
('JPN', '诗篇', 19, 87, 4, '「わたしはラハブとバビロンをわたしを知る者として記憶しよう。見よペリシテとツロクシュもともに。『この者はこの都で生まれた』と。」'),
('JPN', '诗篇', 19, 87, 5, 'しかしシオンについてはこう言われている。「この者もあの者もこの都で生まれた。いと高き方ご自身がシオンを堅く建てられる」と。'),
('JPN', '诗篇', 19, 87, 6, '主が「この者はこの都で生まれた」と記して国々の民を登録される。セラ'),
('JPN', '诗篇', 19, 87, 7, '歌う者も踊る者も「私の泉はみなあなたにあります」と言う。'),
('JPN', '诗篇', 19, 88, 1, '主よ私の救いの神よ昼私は叫びます。夜もあなたのみそばで。'),
('JPN', '诗篇', 19, 88, 2, '私の祈りをあなたの御前にささげます。どうか私の叫びに耳を傾けてください。'),
('JPN', '诗篇', 19, 88, 3, '私のたましいは苦しみに満ち私のいのちはよみに触れていますから。'),
('JPN', '诗篇', 19, 88, 4, '私は穴に下る者たちとともに数えられ力の失せた者のようになっています。'),
('JPN', '诗篇', 19, 88, 5, '私は死人たちの間に放り出され墓に横たわる刺し殺された者たちのようです。あなたはもはや彼らを覚えてはおられません。彼らはあなたの御手から断ち切られています。'),
('JPN', '诗篇', 19, 88, 6, 'あなたは私を最も深い穴に置かれました。暗い所に深い淵に。'),
('JPN', '诗篇', 19, 88, 7, 'あなたの憤りが私の上にとどまりあなたのすべての波であなたは私を苦しめておられます。セラ'),
('JPN', '诗篇', 19, 88, 8, 'あなたは私の親友を私から遠ざけ私を彼らの忌み嫌う者とされました。私は閉じ込められて出て行くことができません。'),
('JPN', '诗篇', 19, 88, 9, '私の目は苦しみによって衰えています。主よ私は日ごとにあなたを呼び求めています。あなたに向かって両手を差し伸ばしています。'),
('JPN', '诗篇', 19, 88, 10, 'あなたは死人のために奇しいみわざを行われるでしょうか。亡霊が起き上がりあなたをほめたたえるでしょうか。セラ'),
('JPN', '诗篇', 19, 88, 11, 'あなたの恵みが墓の中で宣べられるでしょうか。あなたの真実が滅びの淵で。'),
('JPN', '诗篇', 19, 88, 12, 'あなたの奇しいみわざが闇の中で知られるでしょうか。あなたの義が忘却の地で。'),
('JPN', '诗篇', 19, 88, 13, 'しかし私は主よあなたに叫び求めます。朝明けに私の祈りは御前にあります。'),
('JPN', '诗篇', 19, 88, 14, '主よなぜあなたは私のたましいを退け私に御顔を隠されるのですか。'),
('JPN', '诗篇', 19, 88, 15, '私は苦しんでいます。若いころから死に瀕してきました。あなたの恐ろしさに耐えかねて私の心はくずおれそうです。'),
('JPN', '诗篇', 19, 88, 16, 'あなたの燃える怒りが私の上を越えて行きあなたからの恐怖が私を滅ぼし尽くしました。'),
('JPN', '诗篇', 19, 88, 17, 'それらは日夜大水のように私を囲み瞬く間に私を取り巻いてしまいました。'),
('JPN', '诗篇', 19, 88, 18, 'あなたは私から愛する者や友を遠ざけられました。私は暗闇を親しい友としています。'),
('JPN', '诗篇', 19, 89, 1, '私は主の恵みをとこしえに歌います。あなたの真実を代々限りなく私の口で知らせます。'),
('JPN', '诗篇', 19, 89, 2, '私は言います。「御恵みはとこしえに打ち立てられあなたはその真実を天に堅く立てておられます。」'),
('JPN', '诗篇', 19, 89, 3, '「わたしはわたしの選んだ者と契約を結びわたしのしもべダビデに誓う。'),
('JPN', '诗篇', 19, 89, 4, 'わたしはあなたの裔をとこしえまでも堅く立てあなたの王座を代々限りなく打ち立てる。」セラ'),
('JPN', '诗篇', 19, 89, 5, '主よ天はあなたの奇しいみわざをほめたたえます。まことにあなたの真実を聖なる者の集いで。'),
('JPN', '诗篇', 19, 89, 6, 'いったい雲の上ではだれが主と並び得るでしょう。力ある者の子らの中でだれが主に似ているでしょう。'),
('JPN', '诗篇', 19, 89, 7, '主は聖なる者の会合で大いに恐れられる神。主を囲むすべての者の上におられる恐るべき方。'),
('JPN', '诗篇', 19, 89, 8, '万軍の神主よ。だれがあなたのように力があるでしょう。主よ。あなたの真実はあなたを取り囲んでいます。'),
('JPN', '诗篇', 19, 89, 9, 'あなたは海の高まりを治めておられます。波が逆巻くときあなたはそれを鎮められます。'),
('JPN', '诗篇', 19, 89, 10, 'ラハブを打ち砕いて殺された者のようにしあなたの敵を力ある御腕で散らされました。'),
('JPN', '诗篇', 19, 89, 11, '天はあなたのもの地もあなたのもの。世界とそこに満ちているものはあなたが基を据えられました。'),
('JPN', '诗篇', 19, 89, 12, '北と南あなたがこれらを創造されました。タボルとヘルモンは御名を高らかに歌います。'),
('JPN', '诗篇', 19, 89, 13, 'あなたには力ある腕があります。御手は強く右の手は高く上げられています。'),
('JPN', '诗篇', 19, 89, 14, '義と公正はあなたの王座の基。恵みとまことが御前を進みます。'),
('JPN', '诗篇', 19, 89, 15, '幸いなことよ喜びの叫びを知る民は。主よ彼らはあなたの御顔の光の中を歩みます。'),
('JPN', '诗篇', 19, 89, 16, '彼らはあなたの御名をいつも喜びあなたの義によって高く上げられます。'),
('JPN', '诗篇', 19, 89, 17, 'あなたが彼らの力の輝きでありあなたのご恩寵によって私たちの角を高く上げられるからです。'),
('JPN', '诗篇', 19, 89, 18, '私たちの盾は主のもの私たちの王はイスラエルの聖なる方のもの。'),
('JPN', '诗篇', 19, 89, 19, 'あなたはかつて幻を通してあなたにある敬虔な者たちに告げられました。「わたしは一人の勇士に助けを与え民の中から一人の若者を高く上げた。'),
('JPN', '诗篇', 19, 89, 20, 'わたしはわたしのしもべダビデを見出しわたしの聖なる油で油を注いだ。'),
('JPN', '诗篇', 19, 89, 21, 'わたしの手は彼とともにあって揺るがずわたしの腕も彼を強くする。'),
('JPN', '诗篇', 19, 89, 22, '敵が彼に害を加えることはなく不正な者も彼を苦しめることはない。'),
('JPN', '诗篇', 19, 89, 23, 'わたしは彼の前で彼の敵を打ち砕き彼を憎む者を打ち破る。'),
('JPN', '诗篇', 19, 89, 24, 'わたしの真実とわたしの恵みは彼とともにありわたしの名によって彼の角は高く上げられる。'),
('JPN', '诗篇', 19, 89, 25, 'わたしは彼の手を海の上に彼の右の手を川の上に置く。'),
('JPN', '诗篇', 19, 89, 26, '彼はわたしを呼ぶ。『あなたはわが父わが神わが救いの岩』と。'),
('JPN', '诗篇', 19, 89, 27, 'わたしもまた彼をわたしの長子地の王たちのうちの最も高い者とする。'),
('JPN', '诗篇', 19, 89, 28, 'わたしの恵みを彼のために永遠に保つ。わたしの契約は彼にとって確かなものである。'),
('JPN', '诗篇', 19, 89, 29, 'わたしは彼の子孫をいつまでも彼の王座を天の日数のように続かせる。'),
('JPN', '诗篇', 19, 89, 30, 'もしその子孫がわたしのおしえを捨てわたしの定めのうちを歩まないなら'),
('JPN', '诗篇', 19, 89, 31, 'またもし彼らがわたしのおきてを破りわたしの命令を守らないなら'),
('JPN', '诗篇', 19, 89, 32, 'わたしは杖をもって彼らの背きをむちをもって彼らの咎を罰する。'),
('JPN', '诗篇', 19, 89, 33, 'しかしわたしは彼から恵みをもぎ取らずわたしの真実を偽らない。'),
('JPN', '诗篇', 19, 89, 34, 'わたしはわたしの契約を汚さない。唇から出たことをわたしは変えない。'),
('JPN', '诗篇', 19, 89, 35, 'わたしはかつてわが聖によって誓った。わたしは決してダビデに偽りを言わないと。'),
('JPN', '诗篇', 19, 89, 36, '彼の子孫はとこしえまでも続く。その王座は太陽のようにわたしの前にあり'),
('JPN', '诗篇', 19, 89, 37, '月のようにとこしえに堅く立つ。その子孫は雲の上の確かな証人である。」セラ'),
('JPN', '诗篇', 19, 89, 38, 'しかしあなたは拒んでお捨てになりました。あなたは激しく怒っておられます。あなたに油注がれた者に向かって。'),
('JPN', '诗篇', 19, 89, 39, 'あなたはあなたのしもべとの契約を廃棄し彼の王冠を地に捨てて汚しておられます。'),
('JPN', '诗篇', 19, 89, 40, 'あなたは彼の城壁をことごとく打ち壊しその要塞を廃墟とされました。'),
('JPN', '诗篇', 19, 89, 41, '道行く者はみな彼から奪い取り彼は隣人のそしりの的となっています。'),
('JPN', '诗篇', 19, 89, 42, 'あなたは彼の仇の右手を高く上げ彼の敵をみな喜ばせておられます。'),
('JPN', '诗篇', 19, 89, 43, 'しかもあなたは彼の剣の刃をさやに戻し彼が戦いに立てないようにしておられます。'),
('JPN', '诗篇', 19, 89, 44, 'あなたは彼の輝きを消し彼の王座を地に投げ倒されました。'),
('JPN', '诗篇', 19, 89, 45, 'あなたは彼の若い日を短くし恥で彼をおおわれました。セラ'),
('JPN', '诗篇', 19, 89, 46, 'いつまでですか。主よ。あなたがどこまでも身を隠されあなたの憤りが火のように燃えるのは。'),
('JPN', '诗篇', 19, 89, 47, '心に留めてください。私の生涯がどれほどかを。あなたがすべての人の子らをいかにむなしいものとして創造されたかを。'),
('JPN', '诗篇', 19, 89, 48, '生きていて死を見ない人はだれでしょう。だれが自分自身をよみの手から救い出せるでしょう。セラ'),
('JPN', '诗篇', 19, 89, 49, '主よあなたのかつての恵みはどこにあるのでしょうか。あなたは真実をもってダビデに誓われたのです。'),
('JPN', '诗篇', 19, 89, 50, '主よみこころに留めてください。あなたのしもべたちの受ける恥辱を。私が多くの国々の民をすべてこの胸にこらえていることを。'),
('JPN', '诗篇', 19, 89, 51, '主よあなたの敵どもはそしりました。あなたに油注がれた者の足跡をそしったのです。'),
('JPN', '诗篇', 19, 89, 52, '主はとこしえにほむべきかな。アーメン、アーメン。'),
('JPN', '诗篇', 19, 90, 1, '主よ代々にわたってあなたは私たちの住まいです。'),
('JPN', '诗篇', 19, 90, 2, '山々が生まれる前から地と世界をあなたが生み出す前からとこしえからとこしえまであなたは神です。'),
('JPN', '诗篇', 19, 90, 3, 'あなたは人をちりに帰らせます。「人の子らよ帰れ」と言われます。'),
('JPN', '诗篇', 19, 90, 4, 'まことにあなたの目には千年も昨日のように過ぎ去り夜回りのひと時ほどです。'),
('JPN', '诗篇', 19, 90, 5, 'あなたが押し流すと人は眠りに落ちます。朝には草のように消えています。'),
('JPN', '诗篇', 19, 90, 6, '朝花を咲かせても移ろい夕べにはしおれて枯れています。'),
('JPN', '诗篇', 19, 90, 7, '私たちはあなたの御怒りによって消え失せあなたの憤りにおじ惑います。'),
('JPN', '诗篇', 19, 90, 8, 'あなたは私たちの咎を御前に私たちの秘め事を御顔の光の中に置かれます。'),
('JPN', '诗篇', 19, 90, 9, '私たちのすべての日はあなたの激しい怒りの中に消え去り私たちは自分の齢を一息のように終わらせます。'),
('JPN', '诗篇', 19, 90, 10, '私たちの齢は七十年。健やかであっても八十年。そのほとんどは労苦とわざわいです。瞬く間に時は過ぎ私たちは飛び去ります。'),
('JPN', '诗篇', 19, 90, 11, 'だれが御怒りの力をあなたの激しい怒りの力を知っているでしょう。ふさわしい恐れを持つほどに。'),
('JPN', '诗篇', 19, 90, 12, 'どうか教えてください。自分の日を数えることを。そうして私たちに知恵の心を得させてください。'),
('JPN', '诗篇', 19, 90, 13, '帰って来てください。主よいつまでなのですか。あなたのしもべたちをあわれんでください。'),
('JPN', '诗篇', 19, 90, 14, '朝ごとにあなたの恵みで私たちを満ち足らせてください。私たちのすべての日に喜び歌い楽しむことができるように。'),
('JPN', '诗篇', 19, 90, 15, 'どうか喜ばせてください。私たちが苦しめられた日々とわざわいにあった年月に応じて。'),
('JPN', '诗篇', 19, 90, 16, 'みわざをあなたのしもべらにご威光を彼らの子らの上に現してください。'),
('JPN', '诗篇', 19, 90, 17, '私たちの神主の慈愛が私たちの上にありますように。私たちのために私たちの手のわざを確かなものにしてください。どうか私たちの手のわざを確かなものにしてください。'),
('JPN', '诗篇', 19, 91, 1, 'いと高き方の隠れ場に住む者その人は全能者の陰に宿る。'),
('JPN', '诗篇', 19, 91, 2, '私は主に申し上げよう。「私の避け所私の砦私が信頼する私の神」と。'),
('JPN', '诗篇', 19, 91, 3, '主こそ狩人の罠から破滅をもたらす疫病からあなたを救い出される。'),
('JPN', '诗篇', 19, 91, 4, '主はご自分の羽であなたをおおいあなたはその翼の下に身を避ける。主の真実は大盾また砦。'),
('JPN', '诗篇', 19, 91, 5, 'あなたは恐れない。夜襲の恐怖も昼に飛び来る矢も。'),
('JPN', '诗篇', 19, 91, 6, '暗闇に忍び寄る疫病も真昼に荒らす滅びをも。'),
('JPN', '诗篇', 19, 91, 7, '千人があなたの傍らに万人があなたの右に倒れてもそれはあなたには近づかない。'),
('JPN', '诗篇', 19, 91, 8, 'あなたはただそれを目にし悪者への報いを見るだけである。'),
('JPN', '诗篇', 19, 91, 9, 'それはわが避け所主をいと高き方をあなたが自分の住まいとしたからである。'),
('JPN', '诗篇', 19, 91, 10, 'わざわいはあなたに降りかからず疫病もあなたの天幕に近づかない。'),
('JPN', '诗篇', 19, 91, 11, '主があなたのために御使いたちに命じてあなたのすべての道であなたを守られるからだ。'),
('JPN', '诗篇', 19, 91, 12, '彼らはその両手にあなたをのせあなたの足が石に打ち当たらないようにする。'),
('JPN', '诗篇', 19, 91, 13, 'あなたは獅子とコブラを踏みつけ若獅子と蛇を踏みにじる。'),
('JPN', '诗篇', 19, 91, 14, '「彼がわたしを愛しているからわたしは彼を助け出す。彼がわたしの名を知っているからわたしは彼を高く上げる。'),
('JPN', '诗篇', 19, 91, 15, '彼がわたしを呼び求めればわたしは彼に答える。わたしは苦しみのときに彼とともにいて彼を救い彼に誉れを与える。'),
('JPN', '诗篇', 19, 91, 16, 'わたしは彼をとこしえのいのちで満ち足らせわたしの救いを彼に見せる。」'),
('JPN', '诗篇', 19, 92, 1, '主に感謝することは良いことです。いと高き方よあなたの御名をほめ歌うことは。'),
('JPN', '诗篇', 19, 92, 2, '朝にあなたの恵みを夜ごとにあなたの真実を告げることは。'),
('JPN', '诗篇', 19, 92, 3, '十弦の琴に合わせ竪琴の妙なる調べにのせて。'),
('JPN', '诗篇', 19, 92, 4, '主よあなたはあなたのなさったことで私を喜ばせてくださいました。あなたの御手のわざを私は喜び歌います。'),
('JPN', '诗篇', 19, 92, 5, '主よあなたのみわざはなんと大きいことでしょう。あなたの御思いはあまりにも深いのです。'),
('JPN', '诗篇', 19, 92, 6, '無思慮な者は知らず愚か者にはこれが分かりません。'),
('JPN', '诗篇', 19, 92, 7, '悪い者が青草のように萌え出で不法を行う者がみな花を咲かせてもそれは彼らが永久に滅ぼされるためです。'),
('JPN', '诗篇', 19, 92, 8, '主よあなたは永遠にいと高き所におられます。'),
('JPN', '诗篇', 19, 92, 9, '主よまことに今あなたの敵がまことに今あなたの敵が滅びます。不法を行う者はみな散らされます。'),
('JPN', '诗篇', 19, 92, 10, 'あなたは野牛の角のように私の角を高く上げ私にみずみずしい油を注がれました。'),
('JPN', '诗篇', 19, 92, 11, '私の目は私を待ち構えている者どもを眺め耳は私に向かい立つ悪人どものことを聞きます。'),
('JPN', '诗篇', 19, 92, 12, '正しい者はなつめ椰子の木のように萌え出でレバノンの杉のように育ちます。'),
('JPN', '诗篇', 19, 92, 13, '彼らは主の家に植えられ私たちの神の大庭で花を咲かせます。'),
('JPN', '诗篇', 19, 92, 14, '彼らは年老いてもなお実を実らせ青々と生い茂ります。'),
('JPN', '诗篇', 19, 92, 15, 'こうして告げます。「主は正しい方。わが岩。主には偽りがありません。」'),
('JPN', '诗篇', 19, 93, 1, '主こそ王です。威光をまとっておられます。主はまとっておられます。力を帯とされます。まことに世界は堅く据えられ揺るぎません。'),
('JPN', '诗篇', 19, 93, 2, 'あなたの御座はいにしえから堅く立ちあなたはとこしえからおられます。'),
('JPN', '诗篇', 19, 93, 3, '主よ川はとどろかせています。轟音を川はとどろかせています。激しい響きを川はとどろかせています。'),
('JPN', '诗篇', 19, 93, 4, '大水のとどろきにまさり力強い海の波にもまさって主は力に満ちておられます。いと高き所で。'),
('JPN', '诗篇', 19, 93, 5, 'あなたの証しはまことに確かです。聖なることがあなたの家にはふさわしいのです。主よいつまでも。'),
('JPN', '诗篇', 19, 94, 1, '復讐の神主よ復讐の神よ光を放ってください。'),
('JPN', '诗篇', 19, 94, 2, '地をさばく方よ立ち上がってください。高ぶる者に報復してください。'),
('JPN', '诗篇', 19, 94, 3, '主よいつまでですか悪しき者がいつまでですか悪しき者が勝ち誇るのは。'),
('JPN', '诗篇', 19, 94, 4, '彼らは放言し横柄に語り不法を行う者はみな自慢します。'),
('JPN', '诗篇', 19, 94, 5, '主よ彼らはあなたの民を打ち砕きあなたのゆずりの民を苦しめています。'),
('JPN', '诗篇', 19, 94, 6, '彼らはやもめや寄留者を殺しみなしごたちを死なせています。'),
('JPN', '诗篇', 19, 94, 7, '彼らは言っています。「主は見ることはない。ヤコブの神は気づかない。」'),
('JPN', '诗篇', 19, 94, 8, '気づけ。民のうちのまぬけな者どもよ愚かな者どもよいつになったら悟るのか。'),
('JPN', '诗篇', 19, 94, 9, '耳を植えつけた方が聞かないだろうか。目を造った方が見ないだろうか。'),
('JPN', '诗篇', 19, 94, 10, '国々を戒める方が責めないだろうか。人に知識を教えるその方が。'),
('JPN', '诗篇', 19, 94, 11, '主は人の思い計ることがいかに空しいかを知っておられる。'),
('JPN', '诗篇', 19, 94, 12, 'なんと幸いなことでしょう。主よあなたに戒められあなたのみおしえを教えられる人は。'),
('JPN', '诗篇', 19, 94, 13, 'わざわいの日にあなたはその人に平安を与えられます。しかし悪しき者のためには穴が掘られます。'),
('JPN', '诗篇', 19, 94, 14, 'まことに主はご自分の民を見放さずご自分のゆずりの民をお見捨てになりません。'),
('JPN', '诗篇', 19, 94, 15, 'こうしてさばきは再び義に戻り心の直ぐな人はみなこれに従います。'),
('JPN', '诗篇', 19, 94, 16, 'だれが私のために悪を行う者に向かって立ち上がるでしょうか。だれが私のために不法を行う者に向かって堅く立つでしょうか。'),
('JPN', '诗篇', 19, 94, 17, 'もしも主が私の助けでなかったなら私のたましいはただちに沈黙のうちにとどまったでしょう。'),
('JPN', '诗篇', 19, 94, 18, '「私の足はよろけています」と私が言ったなら主よあなたの恵みで私を支えてください。'),
('JPN', '诗篇', 19, 94, 19, '私のうちで思い煩いが増すときにあなたの慰めで私のたましいを喜ばせてください。'),
('JPN', '诗篇', 19, 94, 20, '破滅をもたらす法廷があなたを仲間に加えるでしょうか。おきてに従いながら邪悪なことを謀る者どもが。'),
('JPN', '诗篇', 19, 94, 21, '彼らは正しい者のいのちを求めてともに集まり不義に定めて咎なき者の血を流します。'),
('JPN', '诗篇', 19, 94, 22, 'しかし主は私の砦となり私の神は私の避け所の岩となられました。'),
('JPN', '诗篇', 19, 94, 23, '主は彼らの不義をその身に返し彼ら自身の悪によって彼らを滅ぼされます。私たちの神主が彼らを滅ぼされます。'),
('JPN', '诗篇', 19, 95, 1, 'さあ主に向かって喜び歌おう。私たちの救いの岩に向かって喜び叫ぼう。'),
('JPN', '诗篇', 19, 95, 2, '感謝をもって御前に進み賛美をもって主に喜び叫ぼう。'),
('JPN', '诗篇', 19, 95, 3, 'まことに主は大いなる神。すべての神々にまさって大いなる王である。'),
('JPN', '诗篇', 19, 95, 4, '地の深みは御手のうちにあり山々の頂も主のものである。'),
('JPN', '诗篇', 19, 95, 5, '海は主のもの。主がそれを造られた。陸地も御手が形造った。'),
('JPN', '诗篇', 19, 95, 6, '来たれ。ひれ伏し膝をかがめよう。私たちを造られた方主の御前にひざまずこう。'),
('JPN', '诗篇', 19, 95, 7, 'まことに主は私たちの神。私たちはその牧場の民その御手の羊。今日もし御声を聞くなら'),
('JPN', '诗篇', 19, 95, 8, 'あなたがたの心を頑なにしてはならない。メリバでのように荒野のマサでの日のように。'),
('JPN', '诗篇', 19, 95, 9, 'あなたがたの先祖はそこでわたしを試みわたしを試した。わたしのわざを見ていたのに。'),
('JPN', '诗篇', 19, 95, 10, '四十年の間わたしはその世代を退けそして言った。「彼らは心の迷った民だ。彼らはわたしの道を知らない。」'),
('JPN', '诗篇', 19, 95, 11, 'そのためわたしは怒りをもって誓った。「彼らは決してわたしの安息に入れない。」'),
('JPN', '诗篇', 19, 96, 1, '新しい歌を主に歌え。全地よ主に歌え。'),
('JPN', '诗篇', 19, 96, 2, '主に歌え。御名をほめたたえよ。日から日へと御救いの良い知らせを告げよ。'),
('JPN', '诗篇', 19, 96, 3, '主の栄光を国々の間で語り告げよ。その奇しいみわざをあらゆる民の間で。'),
('JPN', '诗篇', 19, 96, 4, 'まことに主は大いなる方大いに賛美される方。すべての神々にまさって恐れられる方だ。'),
('JPN', '诗篇', 19, 96, 5, 'まことにどの民の神々もみな偽りだ。しかし主は天をお造りになった。'),
('JPN', '诗篇', 19, 96, 6, '威厳と威光は御前にあり力と輝きは主の聖所にある。'),
('JPN', '诗篇', 19, 96, 7, 'もろもろの民の諸族よ主に帰せよ。栄光と力を主に帰せよ。'),
('JPN', '诗篇', 19, 96, 8, '御名の栄光を主に帰せよ。ささげ物を携えて主の大庭に入れ。'),
('JPN', '诗篇', 19, 96, 9, '聖なる装いをして主にひれ伏せ。全地よ主の御前におののけ。'),
('JPN', '诗篇', 19, 96, 10, '国々の間で言え。「主は王である。まことに世界は堅く据えられ揺るがない。主は公正をもって諸国の民をさばかれる。」'),
('JPN', '诗篇', 19, 96, 11, '天は喜び地は小躍りし海とそこに満ちているものは鳴りとどろけ。'),
('JPN', '诗篇', 19, 96, 12, '野とそこにあるものはみな喜び躍れ。そのとき森の木々もみな喜び歌う。主の御前で。'),
('JPN', '诗篇', 19, 96, 13, '主は必ず来られる。地をさばくために来られる。主は義をもって世界をその真実をもって諸国の民をさばかれる。'),
('JPN', '诗篇', 19, 97, 1, '主は王である。地は小躍りせよ。多くの島々は喜べ。'),
('JPN', '诗篇', 19, 97, 2, '雲と暗黒が主を囲み義とさばきが御座の基である。'),
('JPN', '诗篇', 19, 97, 3, '火は御前に先立ち主の敵を囲んで焼き尽くす。'),
('JPN', '诗篇', 19, 97, 4, '主の稲妻は世界を照らし地はそれを見ておののく。'),
('JPN', '诗篇', 19, 97, 5, '山々は主の御前にろうのように溶ける。全地の主の御前に。'),
('JPN', '诗篇', 19, 97, 6, '天は主の義を告げ諸国の民はその栄光を見る。'),
('JPN', '诗篇', 19, 97, 7, 'すべて偶像に仕える者偽りの神々を誇る者は恥を見る。すべての神々よ主にひれ伏せ。'),
('JPN', '诗篇', 19, 97, 8, 'シオンは聞いて喜びユダの娘たちも小躍りしました。主よあなたのさばきのゆえに。'),
('JPN', '诗篇', 19, 97, 9, '主よあなたこそ全地の上におられるいと高き方。すべての神々を超えて高くあがめられています。'),
('JPN', '诗篇', 19, 97, 10, '主を愛する者たちよ。悪を憎め。主は主にある敬虔な者たちのたましいを守り悪者どもの手から彼らを救い出される。'),
('JPN', '诗篇', 19, 97, 11, '光は正しい者のために蒔かれている。喜びは心の直ぐな人のために。'),
('JPN', '诗篇', 19, 97, 12, '正しい者たち。主にあって喜べ。その聖なる御名に感謝せよ。'),
('JPN', '诗篇', 19, 98, 1, '新しい歌を主に歌え。主は奇しいみわざを行われた。主の右の御手聖なる御腕が主に勝利をもたらしたのだ。'),
('JPN', '诗篇', 19, 98, 2, '主は御救いを知らしめご自分の義を国々の前に現された。'),
('JPN', '诗篇', 19, 98, 3, '主はイスラエルの家への恵みと真実を覚えておられる。地の果てのすべての者が私たちの神の救いを見ている。'),
('JPN', '诗篇', 19, 98, 4, '全地よ主に喜び叫べ。大声で叫び喜び歌いほめ歌を歌え。'),
('JPN', '诗篇', 19, 98, 5, '主にほめ歌を歌え。竪琴に合わせて。竪琴に合わせほめ歌の調べにのせて。'),
('JPN', '诗篇', 19, 98, 6, 'ラッパに合わせ角笛の調べにのせて王である主の御前で喜び叫べ。'),
('JPN', '诗篇', 19, 98, 7, '海とそこに満ちているもの世界とその中に住むものよ鳴りとどろけ。'),
('JPN', '诗篇', 19, 98, 8, 'もろもろの川よ手を打ち鳴らせ。山々もこぞって喜び歌え。'),
('JPN', '诗篇', 19, 98, 9, '主の御前で。主は地をさばくために来られる。主は義をもって世界をさばき公正をもって諸国の民をさばかれる。'),
('JPN', '诗篇', 19, 99, 1, '主は王である。国々の民は恐れおののけ。ケルビムの上に座しておられる方に。地よ震えよ。'),
('JPN', '诗篇', 19, 99, 2, '主はシオンにおられる大いなる方。主はすべての国々の民の上に高くいます。'),
('JPN', '诗篇', 19, 99, 3, '大いなる恐れ多い御名をほめたたえよ。主は聖なる方。'),
('JPN', '诗篇', 19, 99, 4, '王は力をもってさばきを愛する。あなたは公正を堅く立てさばきと正義をヤコブの中で行われた。'),
('JPN', '诗篇', 19, 99, 5, 'われらの神主をあがめよ。その足台のもとにひれ伏せ。主は聖なる方。'),
('JPN', '诗篇', 19, 99, 6, 'モーセとアロンは主の祭司たちの中にサムエルは御名を呼ぶ者たちの中にいた。彼らは主を呼び主は彼らに答えられた。'),
('JPN', '诗篇', 19, 99, 7, '主は雲の柱から彼らに語られた。彼らは主のさとしと主が賜ったおきてを守った。'),
('JPN', '诗篇', 19, 99, 8, 'われらの神主よあなたは彼らに答えられた。あなたは彼らには赦しの神彼らの悪しきわざには報復される方。'),
('JPN', '诗篇', 19, 99, 9, 'われらの神主をあがめよ。その聖なる山に向かってひれ伏せ。まことにわれらの神主は聖なる方。'),
('JPN', '诗篇', 19, 100, 1, '全地よ主に向かって喜びの声をあげよ。'),
('JPN', '诗篇', 19, 100, 2, '喜びをもって主に仕えよ。喜び歌いつつ御前に来たれ。'),
('JPN', '诗篇', 19, 100, 3, '知れ。主こそ神。主が私たちを造られた。私たちは主のもの主の民その牧場の羊。'),
('JPN', '诗篇', 19, 100, 4, '感謝しつつ主の門に賛美しつつその大庭に入れ。主に感謝し御名をほめたたえよ。'),
('JPN', '诗篇', 19, 100, 5, '主はいつくしみ深くその恵みはとこしえまでその真実は代々に至る。'),
('JPN', '诗篇', 19, 101, 1, '恵みとさばきを私は歌います。主よあなたにほめ歌を歌います。'),
('JPN', '诗篇', 19, 101, 2, '私は全き道に心を留めます。いつあなたは私のところに来てくださいますか。私は家の中を全き心で行き来します。'),
('JPN', '诗篇', 19, 101, 3, '私は目の前に卑しいことを置きません。私は曲がったわざを憎みそれが私にまといつくことはありません。'),
('JPN', '诗篇', 19, 101, 4, '曲がった心は私から遠ざかります。私は悪を知ろうともしません。'),
('JPN', '诗篇', 19, 101, 5, '陰で自分の隣人をそしる者を私は滅ぼします。高ぶる目とおごる心に耐えることはできません。'),
('JPN', '诗篇', 19, 101, 6, '私の目はこの国の忠実な人たちに注がれます。彼らが私とともに住むために。全き道を歩む者その人は私に仕えます。'),
('JPN', '诗篇', 19, 101, 7, '欺きを行う者は私の家の中に住むことはなく偽りを語る者は私の目の前に堅く立つことはありません。'),
('JPN', '诗篇', 19, 101, 8, '朝ごとに私は国の中の悪しき者をことごとく滅ぼし主の都から不法を行う者をことごとく断ち切ります。'),
('JPN', '诗篇', 19, 102, 1, '主よ私の祈りを聞いてください。私の叫びがあなたに届きますように。'),
('JPN', '诗篇', 19, 102, 2, '私の苦しみのときに御顔を私に隠さないでください。私に耳を傾けてください。私が呼ぶときにすぐに私に答えてください。'),
('JPN', '诗篇', 19, 102, 3, '私の日は煙の中に尽き果て私の骨は炉のように燃えているのです。'),
('JPN', '诗篇', 19, 102, 4, '私の心は青菜のように打たれてしおれパンを食べることさえ忘れました。'),
('JPN', '诗篇', 19, 102, 5, '私の嘆きの声で私の骨は肉に溶けてしまいました。'),
('JPN', '诗篇', 19, 102, 6, '私はまるで荒野のみみずく廃墟のふくろうのようです。'),
('JPN', '诗篇', 19, 102, 7, '私は眠ることもできず屋根の上のはぐれた鳥のようになりました。'),
('JPN', '诗篇', 19, 102, 8, '敵は絶えず私をそしり嘲る者は私を名指しにして毒づきます。'),
('JPN', '诗篇', 19, 102, 9, 'まことに私は灰をパンのように食べ飲み物に涙を混ぜ合わせました。'),
('JPN', '诗篇', 19, 102, 10, 'それはあなたが憤りと激しい怒りのゆえに私を持ち上げ私を投げ捨てられたからです。'),
('JPN', '诗篇', 19, 102, 11, '私の日は伸びていく夕影のようです。私は青菜のようにしおれています。'),
('JPN', '诗篇', 19, 102, 12, 'しかし主よあなたはとこしえに御座に着いておられます。あなたの呼び名は代々に及びます。'),
('JPN', '诗篇', 19, 102, 13, 'あなたは立ち上がりシオンをあわれんでくださいます。今やいつくしみの時です。定めの時が来ました。'),
('JPN', '诗篇', 19, 102, 14, 'まことにあなたのしもべたちはシオンの石を喜びシオンのちりをいとおしみます。'),
('JPN', '诗篇', 19, 102, 15, 'こうして国々は主の御名を地のすべての王はあなたの栄光を恐れます。'),
('JPN', '诗篇', 19, 102, 16, 'なぜなら主はシオンを建て直しその栄光のうちに現れ'),
('JPN', '诗篇', 19, 102, 17, '窮した者の祈りを顧み彼らの祈りをないがしろにされないからです。'),
('JPN', '诗篇', 19, 102, 18, 'このことが後の世代のために書き記され新しく造られる民が主を賛美しますように。'),
('JPN', '诗篇', 19, 102, 19, '主はその聖なるいと高き所から見下ろし天から地の上に目を注がれました。'),
('JPN', '诗篇', 19, 102, 20, '捕らわれ人のうめきを聞き死に定められた者たちを解き放つために。'),
('JPN', '诗篇', 19, 102, 21, '人々が主の御名をシオンで主の誉れをエルサレムで語り告げるために。'),
('JPN', '诗篇', 19, 102, 22, '諸国の民や王国が一つに集められて主に仕えるために。'),
('JPN', '诗篇', 19, 102, 23, '主は私の力を道の半ばで弱らせ私の日数を短くされました。'),
('JPN', '诗篇', 19, 102, 24, '私は申し上げます。「私の神よ私の日の半ばで私を取り去らないでください。あなたの年は代々に至ります。'),
('JPN', '诗篇', 19, 102, 25, 'あなたははるか昔に地の基を据えられました。天もあなたの御手のわざです。'),
('JPN', '诗篇', 19, 102, 26, 'これらのものは滅びます。しかしあなたはとこしえの方です。すべてのものは衣のようにすり切れます。外套のようにあなたがそれらを取り替えられるとそれらはすっかり変えられます。'),
('JPN', '诗篇', 19, 102, 27, 'しかしあなたは変わることがなくあなたの年は尽きることがありません。'),
('JPN', '诗篇', 19, 102, 28, 'あなたのしもべたちの子らは住まいを定め彼らの裔は御前に堅く立てられます。」'),
('JPN', '诗篇', 19, 103, 1, 'わがたましいよ主をほめたたえよ。私のうちにあるすべてのものよ聖なる御名をほめたたえよ。'),
('JPN', '诗篇', 19, 103, 2, 'わがたましいよ主をほめたたえよ。主が良くしてくださったことを何一つ忘れるな。'),
('JPN', '诗篇', 19, 103, 3, '主はあなたのすべての咎を赦しあなたのすべての病を癒やし'),
('JPN', '诗篇', 19, 103, 4, 'あなたのいのちを穴から贖われる。主はあなたに恵みとあわれみの冠をかぶらせ'),
('JPN', '诗篇', 19, 103, 5, 'あなたの一生を良いもので満ち足らせる。あなたの若さは鷲のように新しくなる。'),
('JPN', '诗篇', 19, 103, 6, '主は義とさばきをすべての虐げられている人々のために行われる。'),
('JPN', '诗篇', 19, 103, 7, '主はご自分の道をモーセにそのみわざをイスラエルの子らに知らされた方。'),
('JPN', '诗篇', 19, 103, 8, '主はあわれみ深く情け深い。怒るのに遅く恵み豊かである。'),
('JPN', '诗篇', 19, 103, 9, '主はいつまでも争ってはおられない。とこしえに怒ってはおられない。'),
('JPN', '诗篇', 19, 103, 10, '私たちの罪にしたがって私たちを扱うことをせず私たちの咎にしたがって私たちに報いをされることもない。'),
('JPN', '诗篇', 19, 103, 11, '天が地上はるかに高いように御恵みは主を恐れる者の上に大きい。'),
('JPN', '诗篇', 19, 103, 12, '東が西から遠く離れているように主は私たちの背きの罪を私たちから遠く離される。'),
('JPN', '诗篇', 19, 103, 13, '父がその子をあわれむように主はご自分を恐れる者をあわれまれる。'),
('JPN', '诗篇', 19, 103, 14, '主は私たちの成り立ちを知り私たちが土のちりにすぎないことを心に留めてくださる。'),
('JPN', '诗篇', 19, 103, 15, '人その一生は草のよう。人は咲く。野の花のように。'),
('JPN', '诗篇', 19, 103, 16, '風がそこを過ぎるとそれはもはやない。その場所さえもそれを知らない。'),
('JPN', '诗篇', 19, 103, 17, 'しかし主の恵みはとこしえからとこしえまで主を恐れる者の上にあり主の義はその子らの子たちに及ぶ。'),
('JPN', '诗篇', 19, 103, 18, '主の契約を守る者主の戒めに心を留めて行う者に。'),
('JPN', '诗篇', 19, 103, 19, '主は天にご自分の王座を堅く立てその王国はすべてを統べ治める。'),
('JPN', '诗篇', 19, 103, 20, '主をほめたたえよ主の御使いたちよ。みことばの声に聞き従いみことばを行う力ある勇士たちよ。'),
('JPN', '诗篇', 19, 103, 21, '主をほめたたえよ主のすべての軍勢よ。主のみこころを行い主に仕える者たちよ。'),
('JPN', '诗篇', 19, 103, 22, '主をほめたたえよすべて造られたものたちよ。主が治められるすべてのところで。わがたましいよ主をほめたたえよ。'),
('JPN', '诗篇', 19, 104, 1, 'わがたましいよ主をほめたたえよ。わが神主よあなたはまことに大いなる方。あなたは威厳と威光を身にまとっておられます。'),
('JPN', '诗篇', 19, 104, 2, 'あなたは光を衣のようにまとい天を幕のように張られます。'),
('JPN', '诗篇', 19, 104, 3, '水の中にご自分の高殿の梁を置き密雲をご自分の車とし風の翼に乗って進み行かれます。'),
('JPN', '诗篇', 19, 104, 4, '風をご自分の使いとし燃える火をご自分の召使いとされます。'),
('JPN', '诗篇', 19, 104, 5, 'あなたは地をその基の上に据えられました。地はとこしえまでも揺るぎません。'),
('JPN', '诗篇', 19, 104, 6, 'あなたは大水で衣のように地をおおわれました。水は山々の上にとどまりました。'),
('JPN', '诗篇', 19, 104, 7, '水はあなたに叱られて逃げあなたの雷の声で急ぎ去りました。'),
('JPN', '诗篇', 19, 104, 8, '山を上り谷を下りました。あなたがそれらの基とされた場所へと。'),
('JPN', '诗篇', 19, 104, 9, 'あなたは境を定められました。水がそれを越えないように再び地をおおわないように。'),
('JPN', '诗篇', 19, 104, 10, '主は泉の水を谷に送り山々の間を流れさせ'),
('JPN', '诗篇', 19, 104, 11, '野のすべての獣に飲まされます。野ろばも渇きを癒やします。'),
('JPN', '诗篇', 19, 104, 12, 'その傍らには空の鳥が住み枝の間でさえずります。'),
('JPN', '诗篇', 19, 104, 13, '主はその高殿から山々に水を注がれます。みわざの結ぶ実によって地は満ち足りています。'),
('JPN', '诗篇', 19, 104, 14, '主は家畜のために草をまた人が労して得る作物を生えさせます。地から食物を生じさせてくださいます。'),
('JPN', '诗篇', 19, 104, 15, 'ぶどう酒は人の心を喜ばせパンは人の心を支えます。油よりも顔をつややかにするために。'),
('JPN', '诗篇', 19, 104, 16, '主の木々は満ち足りています。主が植えられたレバノンの杉の木も。'),
('JPN', '诗篇', 19, 104, 17, 'そこに鳥は巣をかけこうのとりはもみの木を宿とします。'),
('JPN', '诗篇', 19, 104, 18, '高い山は野やぎのため岩は岩だぬきの隠れ場。'),
('JPN', '诗篇', 19, 104, 19, '主は季節のために月を造られました。太陽はその沈むところを知っています。'),
('JPN', '诗篇', 19, 104, 20, 'あなたが闇をもたらされると夜になりあらゆる森の獣が這い回ります。'),
('JPN', '诗篇', 19, 104, 21, '若い獅子は餌食を求めて吼えたけり神に自分の食物を求めます。'),
('JPN', '诗篇', 19, 104, 22, '日が昇ると彼らは退いて自分のねぐらで横になります。'),
('JPN', '诗篇', 19, 104, 23, '人は自分の仕事に出て行き夕暮れまでその働きにつきます。'),
('JPN', '诗篇', 19, 104, 24, '主よあなたのみわざはなんと多いことでしょう。あなたは知恵をもってそれらをみな造られました。地はあなたのもので満ちています。'),
('JPN', '诗篇', 19, 104, 25, 'そこには大きく広い海があり這うものや生き物は数えきれません。小さなものも大きなものも。'),
('JPN', '诗篇', 19, 104, 26, 'そこを船が行き交いあなたが造られたレビヤタンもそこで戯れます。'),
('JPN', '诗篇', 19, 104, 27, '彼らはみなあなたを待ち望んでいます。あなたが時にかなって食物をお与えになるのを。'),
('JPN', '诗篇', 19, 104, 28, 'あなたがお与えになると彼らは集めあなたが御手を開かれると彼らは良いもので満ち足ります。'),
('JPN', '诗篇', 19, 104, 29, 'あなたが御顔を隠されると彼らはおじ惑い彼らの息を取り去られると彼らは息絶えて自分のちりに帰ります。')
on conflict (version, book, chapter, verse) do nothing;
